def _wrap_api_exceptions(error_code: str, message: str):
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            try:
                return fn(*args, **kwargs)
            except Exception as exc:
                try:
                    current_app.logger.exception('%s', error_code)
                except Exception:
                    pass

                expose = (os.getenv('EXPOSE_API_ERRORS') or '').strip() == '1'
                payload = {
                    'error': error_code,
                    'message': message,
                }
                if 'account_id' in kwargs:
                    payload['account_id'] = kwargs['account_id']
                if expose:
                    payload['details'] = str(exc)
                return jsonify(payload), 500

        return wrapper

    return decorator


_DB_COLUMN_CACHE: dict[tuple[str, str], bool] = {}


def _normalize_account_ref(value):
    """Accept either an account id or account_number-like integer."""
    if value in (None, '', False, 0, '0'):
        return None
    try:
        return int(str(value).strip())
    except Exception:
        return None


def _normalize_fk_ref(value):
    """Accept nullable integer FK values (treat 0 as null)."""
    if value in (None, '', False, 0, '0'):
        return None
    try:
        return int(str(value).strip())
    except Exception:
        return None


def _db_has_column(table_name: str, column_name: str) -> bool:
    key = (table_name, column_name)
    cached = _DB_COLUMN_CACHE.get(key)
    if cached is not None:
        return cached
    try:
        from sqlalchemy import inspect as sa_inspect

        inspector = sa_inspect(db.engine)
        cols = {c.get('name') for c in inspector.get_columns(table_name)}
        exists = column_name in cols
    except Exception:
        exists = False
    _DB_COLUMN_CACHE[key] = exists
    return exists
