@api.route('/safe-boxes/gold/unify', methods=['POST'])
@require_permission('safe_boxes.edit')
def unify_gold_safe_boxes():
    """Unify legacy karat-specific gold safe boxes into a single multi-karat safe.

    This helps move from the old design (one safe per karat) to the new design
    (one safe that tracks all karats).

    Body JSON (optional):
      - target_safe_box_id: int
      - dry_run: bool (default false)

    Effects when not dry_run:
      - Ensures target safe has karat=None and is_default=True
      - Reassigns SafeBoxTransaction/Invoice/PaymentMethod/Employee references
        from other karat-specific gold safes to target
      - Deactivates the merged legacy safes
    """

    data = request.get_json(silent=True) or {}
    dry_run = bool(data.get('dry_run', False))
    target_id = data.get('target_safe_box_id')

    if target_id is not None:
        try:
            target_id = int(target_id)
        except Exception:
            return jsonify({'error': 'invalid_target_safe_box_id'}), 400

    # Pick target
    target = None
    if target_id:
        target = SafeBox.query.get(target_id)
        if not target:
            return jsonify({'error': 'target_safe_box_not_found'}), 404
        if (target.safe_type or '').strip().lower() != 'gold':
            return jsonify({'error': 'target_safe_box_must_be_gold'}), 400
    else:
        target = SafeBox.query.filter_by(safe_type='gold', karat=None, is_active=True).order_by(SafeBox.is_default.desc(), SafeBox.id.asc()).first()
        if not target:
            target = SafeBox.query.filter_by(safe_type='gold', is_active=True).order_by(SafeBox.is_default.desc(), SafeBox.id.asc()).first()

    if not target:
        return jsonify({'error': 'no_gold_safe_boxes_found'}), 404

    legacy = (
        SafeBox.query
        .filter(SafeBox.safe_type == 'gold', SafeBox.id != target.id, SafeBox.karat.isnot(None))
        .all()
    )

    summary = {
        'dry_run': dry_run,
        'target_safe_box_id': int(target.id),
        'target_name': target.name,
        'legacy_safe_boxes': [
            {'id': int(sb.id), 'name': sb.name, 'karat': sb.karat, 'is_active': bool(sb.is_active)}
            for sb in legacy
        ],
        'moved': {
            'safe_box_transactions': 0,
            'invoices': 0,
            'payment_methods': 0,
            'employees': 0,
        },
        'deactivated_safe_boxes': 0,
    }

    if dry_run:
        return jsonify({'status': 'ok', 'summary': summary}), 200

    try:
        # Ensure target is the unified safe
        target.karat = None
        target.is_active = True

        # Make it default gold safe (and clear others)
        SafeBox.query.filter(SafeBox.safe_type == 'gold', SafeBox.id != target.id, SafeBox.is_default == True).update({'is_default': False})
        target.is_default = True

        for sb in legacy:
            # Rewire references
            summary['moved']['safe_box_transactions'] += int(
                SafeBoxTransaction.query.filter_by(safe_box_id=sb.id).update({'safe_box_id': target.id})
            )
            summary['moved']['invoices'] += int(
                Invoice.query.filter_by(safe_box_id=sb.id).update({'safe_box_id': target.id})
            )
            summary['moved']['payment_methods'] += int(
                PaymentMethod.query.filter_by(default_safe_box_id=sb.id).update({'default_safe_box_id': target.id})
            )
            summary['moved']['employees'] += int(
                Employee.query.filter_by(gold_safe_box_id=sb.id).update({'gold_safe_box_id': target.id})
            )

            # Deactivate legacy safe
            sb.is_active = False
            sb.is_default = False
            try:
                note = (sb.notes or '').strip()
                prefix = 'تم دمجها في خزينة ذهب موحّدة'
                sb.notes = (note + ('\n' if note else '') + prefix + f' (target_id={target.id})')
            except Exception:
                pass
            summary['deactivated_safe_boxes'] += 1

        db.session.commit()
        return jsonify({'status': 'ok', 'summary': summary}), 200

    except Exception as e:
        db.session.rollback()
        return jsonify({'status': 'error', 'message': str(e)}), 500


@api.route('/safe-boxes/transfer-voucher', methods=['POST'])
@require_permission('safe_boxes.edit')
def create_safe_box_transfer_voucher():
    """Create a safe-box transfer voucher and update the SafeBox ledger immediately.

    Supports:
    - Gold transfer between gold safes (weights by karat)
    - Cash transfer between non-gold safes (cash/bank/check/clearing) using amount_cash

    Body JSON:
        - from_safe_box_id: int (required)
        - to_safe_box_id: int (required)
        - Gold mode:
                - weights: {"24k": float, "22k": float, "21k": float, "18k": float} (optional)
                    OR weight_24k/weight_22k/weight_21k/weight_18k (optional)
        - Cash mode:
                - amount_cash: float (required)  (alias: amount)
        - date: ISO datetime (optional)
        - notes: str (optional)
        - created_by / approved_by: str (optional)

    Result: creates an approved adjustment Voucher + JournalEntry + SafeBoxTransaction rows (out/in).
    """

    data = request.get_json(silent=True) or {}
    from_safe_box_id = data.get('from_safe_box_id')
    to_safe_box_id = data.get('to_safe_box_id')

    if not from_safe_box_id or not to_safe_box_id:
        return jsonify({'error': 'from_safe_box_id_and_to_safe_box_id_required'}), 400

    try:
        from_safe_box_id = int(from_safe_box_id)
        to_safe_box_id = int(to_safe_box_id)
    except Exception:
        return jsonify({'error': 'invalid_safe_box_id'}), 400

    if from_safe_box_id == to_safe_box_id:
        return jsonify({'error': 'cannot_transfer_to_same_safe_box'}), 400

    from_safe = SafeBox.query.get_or_404(from_safe_box_id)
    to_safe = SafeBox.query.get_or_404(to_safe_box_id)

    from_type = (from_safe.safe_type or '').strip().lower()
    to_type = (to_safe.safe_type or '').strip().lower()

    if not bool(getattr(from_safe, 'is_active', True)) or not bool(getattr(to_safe, 'is_active', True)):
        return jsonify({'error': 'safe_box_inactive'}), 400

    # Prevent mixing gold transfer with cash transfer in a single request.
    if ('gold' in {from_type, to_type}) and not (from_type == 'gold' and to_type == 'gold'):
        return jsonify({'error': 'cannot_mix_gold_and_cash_safe_boxes'}), 400

    def _f(v):
        try:
            return float(v or 0.0)
        except Exception:
            return 0.0

    is_gold_transfer = (from_type == 'gold' and to_type == 'gold')

    # ------------------------------------------------------------------
    # Gold transfer (weights)
    # ------------------------------------------------------------------
    if is_gold_transfer:
        weights = data.get('weights') or {}

        w_24 = _f(weights.get('24k') if isinstance(weights, dict) else None)
        w_22 = _f(weights.get('22k') if isinstance(weights, dict) else None)
        w_21 = _f(weights.get('21k') if isinstance(weights, dict) else None)
        w_18 = _f(weights.get('18k') if isinstance(weights, dict) else None)

        # Allow alternate flat fields
        if w_24 == 0.0:
            w_24 = _f(data.get('weight_24k'))
        if w_22 == 0.0:
            w_22 = _f(data.get('weight_22k'))
        if w_21 == 0.0:
            w_21 = _f(data.get('weight_21k'))
        if w_18 == 0.0:
            w_18 = _f(data.get('weight_18k'))

        for v in (w_24, w_22, w_21, w_18):
            if v < 0:
                return jsonify({'error': 'negative_weight_not_allowed'}), 400

        if (w_24 + w_22 + w_21 + w_18) <= 0:
            return jsonify({'error': 'no_weights_provided'}), 400

        # Compute current source balance from ledger and enforce sufficiency.
        q = SafeBoxTransaction.query.filter_by(safe_box_id=from_safe_box_id)
        w_in = {
            '18k': float(q.with_entities(func.coalesce(func.sum(SafeBoxTransaction.weight_18k), 0.0)).filter(SafeBoxTransaction.direction == 'in').scalar() or 0.0),
            '21k': float(q.with_entities(func.coalesce(func.sum(SafeBoxTransaction.weight_21k), 0.0)).filter(SafeBoxTransaction.direction == 'in').scalar() or 0.0),
            '22k': float(q.with_entities(func.coalesce(func.sum(SafeBoxTransaction.weight_22k), 0.0)).filter(SafeBoxTransaction.direction == 'in').scalar() or 0.0),
            '24k': float(q.with_entities(func.coalesce(func.sum(SafeBoxTransaction.weight_24k), 0.0)).filter(SafeBoxTransaction.direction == 'in').scalar() or 0.0),
        }
        w_out = {
            '18k': float(q.with_entities(func.coalesce(func.sum(SafeBoxTransaction.weight_18k), 0.0)).filter(SafeBoxTransaction.direction == 'out').scalar() or 0.0),
            '21k': float(q.with_entities(func.coalesce(func.sum(SafeBoxTransaction.weight_21k), 0.0)).filter(SafeBoxTransaction.direction == 'out').scalar() or 0.0),
            '22k': float(q.with_entities(func.coalesce(func.sum(SafeBoxTransaction.weight_22k), 0.0)).filter(SafeBoxTransaction.direction == 'out').scalar() or 0.0),
            '24k': float(q.with_entities(func.coalesce(func.sum(SafeBoxTransaction.weight_24k), 0.0)).filter(SafeBoxTransaction.direction == 'out').scalar() or 0.0),
        }
        w_bal = {k: float(w_in.get(k, 0.0)) - float(w_out.get(k, 0.0)) for k in ['18k', '21k', '22k', '24k']}
        eps = 1e-6
        if (w_24 - (w_bal.get('24k', 0.0) or 0.0)) > eps:
            return jsonify({'error': 'insufficient_balance_24k', 'available': round(w_bal.get('24k', 0.0), 3)}), 400
        if (w_22 - (w_bal.get('22k', 0.0) or 0.0)) > eps:
            return jsonify({'error': 'insufficient_balance_22k', 'available': round(w_bal.get('22k', 0.0), 3)}), 400
        if (w_21 - (w_bal.get('21k', 0.0) or 0.0)) > eps:
            return jsonify({'error': 'insufficient_balance_21k', 'available': round(w_bal.get('21k', 0.0), 3)}), 400
        if (w_18 - (w_bal.get('18k', 0.0) or 0.0)) > eps:
            return jsonify({'error': 'insufficient_balance_18k', 'available': round(w_bal.get('18k', 0.0), 3)}), 400

    # ------------------------------------------------------------------
    # Cash transfer (amount_cash)
    # ------------------------------------------------------------------
    else:
        amount_cash = _f(data.get('amount_cash') or data.get('amount') or data.get('cash_amount'))
        if amount_cash <= 0:
            return jsonify({'error': 'amount_cash_required'}), 400

        if amount_cash < 0:
            return jsonify({'error': 'negative_amount_not_allowed'}), 400

        # Use live GL balance (same source used by safe-box balances UI)
        # to avoid false "insufficient" when historical SBT rows are incomplete.
        cash_bal = 0.0
        try:
            live = (
                live_balances_by_account_ids([int(from_safe.account_id)])
                .get(int(from_safe.account_id), {})
            )
            cash_bal = float((live or {}).get('cash') or 0.0)
        except Exception:
            cash_bal = 0.0

        eps = 1e-6
        if (amount_cash - cash_bal) > eps:
            return jsonify({'error': 'insufficient_cash_balance', 'available': round(float(cash_bal), 2)}), 400

        # Reuse existing variables to minimize changes below.
        w_24 = w_22 = w_21 = w_18 = 0.0

    created_by = (data.get('approved_by') or data.get('created_by') or 'system')
    notes = (data.get('notes') or '').strip() or None

    try:
        voucher_dt = datetime.fromisoformat(data.get('date')) if data.get('date') else datetime.now()
    except Exception:
        return jsonify({'error': 'invalid_date'}), 400

    lines = []
    if is_gold_transfer:
        # Build balanced gold account lines (credit from_safe.account, debit to_safe.account)
        def _line(account_id: int, *, line_type: str, karat: int, amount: float):
            return VoucherAccountLine(
                account_id=account_id,
                line_type=line_type,
                amount_type='gold',
                amount=float(amount),
                karat=float(karat),
            )

        if w_24 > 0:
            lines.append(_line(to_safe.account_id, line_type='debit', karat=24, amount=w_24))
            lines.append(_line(from_safe.account_id, line_type='credit', karat=24, amount=w_24))
        if w_22 > 0:
            lines.append(_line(to_safe.account_id, line_type='debit', karat=22, amount=w_22))
            lines.append(_line(from_safe.account_id, line_type='credit', karat=22, amount=w_22))
        if w_21 > 0:
            lines.append(_line(to_safe.account_id, line_type='debit', karat=21, amount=w_21))
            lines.append(_line(from_safe.account_id, line_type='credit', karat=21, amount=w_21))
        if w_18 > 0:
            lines.append(_line(to_safe.account_id, line_type='debit', karat=18, amount=w_18))
            lines.append(_line(from_safe.account_id, line_type='credit', karat=18, amount=w_18))
    else:
        # Cash transfer: debit to_safe, credit from_safe.
        amount_cash = float(amount_cash)
        lines.append(VoucherAccountLine(
            account_id=to_safe.account_id,
            line_type='debit',
            amount_type='cash',
            amount=amount_cash,
        ))
        lines.append(VoucherAccountLine(
            account_id=from_safe.account_id,
            line_type='credit',
            amount_type='cash',
            amount=amount_cash,
        ))

    try:
        voucher_number = generate_voucher_number('adjustment', voucher_date=voucher_dt)

        voucher = Voucher(
            voucher_number=voucher_number,
            voucher_type='adjustment',
            date=voucher_dt,
            party_type=None,
            description=(
                f"تحويل خزنة ذهب: {from_safe.name} → {to_safe.name}"
                if is_gold_transfer
                else f"تحويل خزنة: {from_safe.name} → {to_safe.name}"
            ),
            amount_cash=(0.0 if is_gold_transfer else float(amount_cash)),
            amount_gold=(float(w_24 + w_22 + w_21 + w_18) if is_gold_transfer else 0.0),
            reference_type='manual',
            reference_number=None,
            notes=notes,
            created_by=created_by,
            status='pending',
        )
        db.session.add(voucher)
        db.session.flush()

        for l in lines:
            l.voucher_id = voucher.id
            db.session.add(l)

        # Approve/post immediately
        journal_entry = create_journal_entry_from_voucher(voucher)
        if not journal_entry:
            raise Exception('فشل إنشاء القيد المحاسبي')

        voucher.status = 'approved'
        voucher.approved_at = datetime.now()
        voucher.approved_by = created_by
        voucher.journal_entry_id = journal_entry.id

        _append_safe_transactions_for_voucher(voucher, created_by=created_by)

        # Stamp per-karat stones data onto SBTs (if provided)
        if is_gold_transfer:
            _st_raw = data.get('stones') or {}
            _sf2 = lambda v: max(0.0, float(v or 0))
            _st18 = _sf2(_st_raw.get('18k'))
            _st21 = _sf2(_st_raw.get('21k'))
            _st22 = _sf2(_st_raw.get('22k'))
            _st24 = _sf2(_st_raw.get('24k'))
            _st_total = _st18 + _st21 + _st22 + _st24
            if _st_total > 0:
                _sbts = SafeBoxTransaction.query.filter_by(
                    ref_id=voucher.id, ref_type='voucher'
                ).all()
                for _sbt in _sbts:
                    if _sbt.safe_box_id == from_safe.id and _sbt.direction == 'out':
                        _sbt.stones_18k    = _st18
                        _sbt.stones_21k    = _st21
                        _sbt.stones_22k    = _st22
                        _sbt.stones_24k    = _st24
                        _sbt.stones_weight = _st_total
                    elif _sbt.safe_box_id == to_safe.id and _sbt.direction == 'in':
                        _sbt.stones_18k    = _st18
                        _sbt.stones_21k    = _st21
                        _sbt.stones_22k    = _st22
                        _sbt.stones_24k    = _st24
                        _sbt.stones_weight = _st_total

        db.session.commit()

        return jsonify({
            'message': 'تم إنشاء سند التحويل وتحديث الخزائن بنجاح',
            'voucher': voucher.to_dict(),
            'journal_entry': {
                'id': journal_entry.id,
                'entry_number': journal_entry.entry_number,
                'date': journal_entry.date.isoformat() if journal_entry.date else None,
            },
            'transfer': {
                'from_safe_box_id': from_safe.id,
                'to_safe_box_id': to_safe.id,
                'type': ('gold' if is_gold_transfer else 'cash'),
                **({'amount_cash': round(float(amount_cash), 2)} if not is_gold_transfer else {}),
                **({
                    'weights': {
                        '24k': round(float(w_24), 3),
                        '22k': round(float(w_22), 3),
                        '21k': round(float(w_21), 3),
                        '18k': round(float(w_18), 3),
                    },
                } if is_gold_transfer else {}),
            },
        }), 201
    except ValueError as e:
        db.session.rollback()
        msg = str(e)
        if msg.startswith('karat_mismatch_for_safe_box:'):
            return jsonify({
                'error': 'karat_mismatch_for_safe_box',
                'message': 'لا يمكن تنفيذ التحويل: عيار الحركة لا يتطابق مع عيار الخزنة (الخزنة مخصصة لعيار واحد)',
                'details': msg,
            }), 400
        return jsonify({'error': 'validation_error', 'message': msg}), 400
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'error': 'safe_box_transfer_voucher_failed', 'message': str(e)}), 500


# =========================================================================
# Karat Correction within same Gold Safe Box
# =========================================================================

@api.route('/safe-boxes/<int:safe_box_id>/correct-karat', methods=['POST'])
@require_permission('safe_boxes.edit')
def correct_safe_box_karat(safe_box_id):
    """تصحيح عيار خاطئ داخل نفس الخزينة الذهبية.

    يُنقَل وزن X غرام من عيار قديم (مسجَّل خطأً) إلى عيار صحيح
    داخل نفس الخزينة، دون أي تحويل حسابي للوزن.

    Body JSON:
        - from_karat: int  (18 | 21 | 22 | 24)  — العيار الخاطئ المسجَّل
        - to_karat:   int  (18 | 21 | 22 | 24)  — العيار الصحيح
        - weight:     float  (غرام، موجب)
        - notes:      str  (اختياري)  — سبب التصحيح
    """
    data = request.get_json(silent=True) or {}

    _valid_karats = {18, 21, 22, 24}

    try:
        from_karat = int(data.get('from_karat', 0))
        to_karat   = int(data.get('to_karat', 0))
    except (TypeError, ValueError):
        return jsonify({'error': 'invalid_karat'}), 400

    if from_karat not in _valid_karats or to_karat not in _valid_karats:
        return jsonify({'error': 'invalid_karat', 'allowed': list(_valid_karats)}), 400

    if from_karat == to_karat:
        return jsonify({'error': 'same_karat'}), 400

    try:
        weight = float(data.get('weight') or 0)
    except (TypeError, ValueError):
        weight = 0.0
    if weight <= 0:
        return jsonify({'error': 'invalid_weight'}), 400

    notes = (data.get('notes') or '').strip() or None

    try:
        safe = SafeBox.query.filter_by(id=safe_box_id).first()
        if safe is None:
            return jsonify({'error': 'safe_box_not_found'}), 404
        if (safe.safe_type or '').lower() != 'gold':
            return jsonify({'error': 'not_a_gold_safe'}), 400
        if not bool(getattr(safe, 'is_active', True)):
            return jsonify({'error': 'safe_box_inactive'}), 400

        # --- التحقق من رصيد العيار المصدر ---
        from_col = f'weight_{from_karat}k'
        q = SafeBoxTransaction.query.filter_by(safe_box_id=safe_box_id)
        col_attr = getattr(SafeBoxTransaction, from_col)
        w_in  = float(q.with_entities(func.coalesce(func.sum(col_attr), 0.0))
                        .filter(SafeBoxTransaction.direction == 'in').scalar() or 0.0)
        w_out = float(q.with_entities(func.coalesce(func.sum(col_attr), 0.0))
                        .filter(SafeBoxTransaction.direction == 'out').scalar() or 0.0)
        available = round(w_in - w_out, 6)

        if weight > available + 1e-6:
            return jsonify({
                'error': 'insufficient_balance',
                'karat': from_karat,
                'available': round(available, 3),
            }), 400

        created_by = getattr(getattr(g, 'current_user', None), 'username', None) or 'system'
    except Exception as pre_err:
        import traceback
        traceback.print_exc()
        return jsonify({'error': 'pre_validation_failed', 'message': str(pre_err)}), 500

    try:
        voucher_dt = datetime.now()
        voucher_number = generate_voucher_number('adjustment', voucher_date=voucher_dt)

        voucher = Voucher(
            voucher_number=voucher_number,
            voucher_type='adjustment',
            date=voucher_dt,
            party_type=None,
            description=f"تصحيح عيار: {from_karat}k → {to_karat}k ({weight:.3f} جم) — {safe.name}",
            amount_cash=0.0,
            amount_gold=round(weight, 4),
            reference_type='manual',
            reference_number=None,
            notes=notes,
            created_by=created_by,
            status='pending',
        )
        db.session.add(voucher)
        db.session.flush()

        # قيد محاسبي: مدين بالعيار الجديد — دائن بالعيار القديم (نفس الحساب)
        for lt, karat_val in (('debit', float(to_karat)), ('credit', float(from_karat))):
            db.session.add(VoucherAccountLine(
                voucher_id=voucher.id,
                account_id=safe.account_id,
                line_type=lt,
                amount_type='gold',
                amount=weight,
                karat=karat_val,
            ))

        journal_entry = create_journal_entry_from_voucher(voucher)
        if not journal_entry:
            raise Exception('فشل إنشاء القيد المحاسبي')

        voucher.status = 'approved'
        voucher.approved_at = datetime.now()
        voucher.approved_by = created_by
        voucher.journal_entry_id = journal_entry.id

        # حركتان في ledger الخزينة: خروج من العيار القديم، دخول للعيار الجديد
        kw_out = {'amount_cash': 0.0, from_col: round(weight, 6)}
        kw_in  = {'amount_cash': 0.0, f'weight_{to_karat}k': round(weight, 6)}

        db.session.add(SafeBoxTransaction(
            safe_box_id=safe_box_id,
            direction='out',
            ref_type='voucher',
            ref_id=voucher.id,
            created_by=created_by,
            notes=f'تصحيح عيار — خروج {from_karat}k',
            **kw_out,
        ))
        db.session.add(SafeBoxTransaction(
            safe_box_id=safe_box_id,
            direction='in',
            ref_type='voucher',
            ref_id=voucher.id,
            created_by=created_by,
            notes=f'تصحيح عيار — دخول {to_karat}k',
            **kw_in,
        ))

        db.session.commit()

        return jsonify({
            'message': 'تم تصحيح العيار بنجاح',
            'voucher': voucher.to_dict(),
            'correction': {
                'safe_box_id': safe_box_id,
                'safe_name': safe.name,
                'from_karat': from_karat,
                'to_karat': to_karat,
                'weight': round(weight, 3),
            },
        }), 201

    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'error': 'karat_correction_failed', 'message': str(e)}), 500


# =========================================================================
# Melting / Renewal Operation  (تكسير وتجديد)
# =========================================================================

@api.route('/melting-renewal', methods=['POST'])
@require_permission('safe_boxes.edit')
def create_melting_renewal():
    """تسجيل عملية تكسير أو تجديد.

    Body JSON:
        operation_type : str   — 'melting' | 'renewal'
        from_safe_box_id : int — الخزينة المصدر (للتكسير: خزينة الذهب المعروض)
        to_safe_box_id   : int — الخزينة الوجهة  (للتكسير: صندوق الكسر)
        from_karat       : int — عيار الذهب المكسَّر  (18|21|22|24)
        to_karat         : int — عيار الذهب الناتج   (18|21|22|24)  [اختياري ← يساوي from_karat إن لم يُحدَّد]
        gold_weight      : float — وزن الذهب (جم)
        stones_weight    : float — وزن الفصوص (جم)  [اختياري]
        stones_revenue_account_id  : int — حساب إيراد الفصوص الداخلة  [اختياري]
        stones_expense_account_id  : int — حساب مصروف الفصوص الخارجة [اختياري]
        damage_wage_weight         : float — مبلغ المصنعية التالفة (نقد) [اختياري، تكسير فقط]
        damage_wage_account_id     : int   — حساب مصروف المصنعية التالفة [اختياري، تكسير فقط]
        notes            : str — ملاحظات       [اختياري]
    """
    data = request.get_json(silent=True) or {}

    operation_type = (data.get('operation_type') or '').strip().lower()
    if operation_type not in ('melting', 'renewal'):
        return jsonify({'error': 'invalid_operation_type', 'allowed': ['melting', 'renewal']}), 400

    _valid_karats = {18, 21, 22, 24}

    try:
        from_safe_id = int(data['from_safe_box_id'])
        to_safe_id   = int(data['to_safe_box_id'])
    except (KeyError, TypeError, ValueError):
        return jsonify({'error': 'missing_safe_box_ids'}), 400

    try:
        from_karat = int(data.get('from_karat', 21))
        to_karat   = int(data.get('to_karat') or from_karat)
    except (TypeError, ValueError):
        return jsonify({'error': 'invalid_karat'}), 400

    if from_karat not in _valid_karats or to_karat not in _valid_karats:
        return jsonify({'error': 'invalid_karat', 'allowed': list(_valid_karats)}), 400

    try:
        gold_weight        = float(data.get('gold_weight') or 0)
        stones_weight      = float(data.get('stones_weight') or 0)
        damage_wage_amount = float(data.get('damage_wage_amount') or data.get('damage_wage_weight') or 0)
    except (TypeError, ValueError):
        return jsonify({'error': 'invalid_weight'}), 400

    if gold_weight <= 0:
        return jsonify({'error': 'invalid_gold_weight'}), 400

    stones_rev_account_id  = data.get('stones_revenue_account_id')
    stones_exp_account_id  = data.get('stones_expense_account_id')
    damage_wage_account_id = data.get('damage_wage_account_id')
    try:
        if stones_rev_account_id:
            stones_rev_account_id = int(stones_rev_account_id)
        if stones_exp_account_id:
            stones_exp_account_id = int(stones_exp_account_id)
        if damage_wage_account_id:
            damage_wage_account_id = int(damage_wage_account_id)
    except (TypeError, ValueError):
        return jsonify({'error': 'invalid_account_id'}), 400

    notes = (data.get('notes') or '').strip() or None

    # Validate safe boxes + available balance
    try:
        from_safe = SafeBox.query.filter_by(id=from_safe_id).first()
        to_safe   = SafeBox.query.filter_by(id=to_safe_id).first()
        if not from_safe:
            return jsonify({'error': 'from_safe_not_found'}), 404
        if not to_safe:
            return jsonify({'error': 'to_safe_not_found'}), 404
        if from_safe_id == to_safe_id:
            return jsonify({'error': 'same_safe_box'}), 400

        from_col  = f'weight_{from_karat}k'
        q_src = SafeBoxTransaction.query.filter_by(safe_box_id=from_safe_id)
        col_a = getattr(SafeBoxTransaction, from_col)
        w_in  = float(q_src.with_entities(func.coalesce(func.sum(col_a), 0.0))
                           .filter(SafeBoxTransaction.direction == 'in').scalar() or 0.0)
        w_out = float(q_src.with_entities(func.coalesce(func.sum(col_a), 0.0))
                           .filter(SafeBoxTransaction.direction == 'out').scalar() or 0.0)
        available = round(w_in - w_out, 6)

        if gold_weight > available + 1e-6:
            return jsonify({
                'error': 'insufficient_balance',
                'karat': from_karat,
                'available': round(available, 3),
            }), 400

        # تحقق من رصيد الفصوص إذا أُدخل وزن فصوص
        if stones_weight > 0:
            s_in  = float(q_src.with_entities(
                func.coalesce(func.sum(SafeBoxTransaction.stones_weight), 0.0))
                .filter(SafeBoxTransaction.direction == 'in').scalar() or 0.0)
            s_out = float(q_src.with_entities(
                func.coalesce(func.sum(SafeBoxTransaction.stones_weight), 0.0))
                .filter(SafeBoxTransaction.direction == 'out').scalar() or 0.0)
            stones_available = round(s_in - s_out, 6)
            if stones_weight > stones_available + 1e-6:
                return jsonify({
                    'error': 'insufficient_stones_balance',
                    'message': f'وزن الفصوص المطلوب ({stones_weight:.3f} جم) يتجاوز الرصيد المتاح ({stones_available:.3f} جم)',
                    'stones_available': round(stones_available, 3),
                }), 400

        created_by = getattr(getattr(g, 'current_user', None), 'username', None) or 'system'

        # Optional: validate stones accounts exist
        if stones_rev_account_id:
            if not Account.query.get(stones_rev_account_id):
                return jsonify({'error': 'stones_revenue_account_not_found'}), 404
        if stones_exp_account_id:
            if not Account.query.get(stones_exp_account_id):
                return jsonify({'error': 'stones_expense_account_not_found'}), 404
        if damage_wage_account_id:
            if not Account.query.get(damage_wage_account_id):
                return jsonify({'error': 'damage_wage_account_not_found'}), 404

    except Exception as pre_err:
        import traceback; traceback.print_exc()
        return jsonify({'error': 'pre_validation_failed', 'message': str(pre_err)}), 500

    try:
        op_label = 'تكسير' if operation_type == 'melting' else 'تجديد'
        voucher_dt     = datetime.now()
        voucher_number = generate_voucher_number('adjustment', voucher_date=voucher_dt)

        desc_parts = [
            f'{op_label}: {gold_weight:.3f} جم {from_karat}k',
            f'من: {from_safe.name}',
            f'إلى: {to_safe.name}',
        ]
        if stones_weight > 0:
            desc_parts.append(f'فصوص: {stones_weight:.3f} جم')
        if damage_wage_amount > 0 and operation_type == 'melting':
            desc_parts.append(f'مصنعية تالفة: {damage_wage_amount:.2f}')

        voucher = Voucher(
            voucher_number=voucher_number,
            voucher_type='adjustment',
            date=voucher_dt,
            description=' | '.join(desc_parts),
            amount_cash=0.0,
            amount_gold=round(gold_weight, 4),
            reference_type='manual',
            notes=notes,
            created_by=created_by,
            status='pending',
        )
        db.session.add(voucher)
        db.session.flush()

        # قيد ذهبي: دائن خزينة المصدر، مدين خزينة الوجهة
        for lt, acct_id, karat_val in (
            ('credit', from_safe.account_id, float(from_karat)),
            ('debit',  to_safe.account_id,   float(to_karat)),
        ):
            db.session.add(VoucherAccountLine(
                voucher_id=voucher.id,
                account_id=acct_id,
                line_type=lt,
                amount_type='gold',
                amount=gold_weight,
                karat=karat_val,
            ))

        # ─── قيد الفصوص عند التجديد فقط ───
        # مدين:  حساب أصول الفصوص  (الفصوص تُسجَّل كأصل)
        # دائن:  حساب إيراد الفصوص  (إيراد يُعترف به عند التجديد)
        _stones_je_warning = None
        if operation_type == 'renewal' and stones_weight > 0:
            _s = Settings.query.first()
            _stones_asset_acc   = getattr(_s, 'stones_pending_account_id', None) if _s else None
            _stones_revenue_acc = getattr(_s, 'stones_display_revenue_account_id', None) if _s else None
            if not _stones_asset_acc or not _stones_revenue_acc:
                _stones_je_warning = 'لم تُسجَّل قيود الفصوص المحاسبية — يرجى تعريف حسابَي أصول وإيراد الفصوص في الإعدادات'
            if _stones_asset_acc and _stones_revenue_acc:
                db.session.add(VoucherAccountLine(
                    voucher_id=voucher.id,
                    account_id=_stones_asset_acc,
                    line_type='debit',
                    amount_type='gold',
                    amount=stones_weight,
                    karat=float(to_karat),
                    description=f'أصول فصوص — تجديد ({stones_weight:.3f} جم)',
                ))
                db.session.add(VoucherAccountLine(
                    voucher_id=voucher.id,
                    account_id=_stones_revenue_acc,
                    line_type='credit',
                    amount_type='gold',
                    amount=stones_weight,
                    karat=float(to_karat),
                    description=f'إيراد فصوص — تجديد ({stones_weight:.3f} جم)',
                ))

        # قيد المصنعية التالفة (تكسير فقط):
        # مدين: حساب مصروف المصنعية التالفة (نقد)
        # دائن: حساب مخزون أجور المصنعية
        if damage_wage_amount > 0 and operation_type == 'melting' and damage_wage_account_id:
            wage_inventory_acc_id = _get_manufacturing_wage_inventory_account_id()
            if not wage_inventory_acc_id:
                raise Exception('حساب مخزون أجور المصنعية غير موجود. يرجى إنشاؤه أولاً.')
            db.session.add(VoucherAccountLine(
                voucher_id=voucher.id,
                account_id=damage_wage_account_id,
                line_type='debit',
                amount_type='cash',
                amount=damage_wage_amount,
                karat=None,
                description='مصروف مصنعية تالفة',
            ))
            db.session.add(VoucherAccountLine(
                voucher_id=voucher.id,
                account_id=wage_inventory_acc_id,
                line_type='credit',
                amount_type='cash',
                amount=damage_wage_amount,
                karat=None,
                description='تخفيض مخزون أجور المصنعية - تكسير',
            ))

        journal_entry = create_journal_entry_from_voucher(voucher)
        if not journal_entry:
            raise Exception('فشل إنشاء القيد المحاسبي')

        voucher.status     = 'approved'
        voucher.approved_at = datetime.now()
        voucher.approved_by = created_by
        voucher.journal_entry_id = journal_entry.id

        # stones_weight: معلوماتي فقط — لا يؤثر على رصيد الوزن الذهبي
        _stones_raw = data.get('stones') or {}
        _sf = lambda v: max(0.0, float(v or 0))
        _s18 = _sf(_stones_raw.get('18k'))
        _s21 = _sf(_stones_raw.get('21k'))
        _s22 = _sf(_stones_raw.get('22k'))
        _s24 = _sf(_stones_raw.get('24k'))
        _s_total = _s18 + _s21 + _s22 + _s24
        if _s_total > 0:
            _stones_kw = {
                'stones_weight': round(_s_total, 6),
                'stones_18k': round(_s18, 6),
                'stones_21k': round(_s21, 6),
                'stones_22k': round(_s22, 6),
                'stones_24k': round(_s24, 6),
            }
        elif stones_weight > 0:
            _stones_kw = {'stones_weight': round(stones_weight, 6)}
        else:
            _stones_kw = {}

        # SafeBoxTransaction: خروج من المصدر (وزن صافي + فصوص معلوماتي)
        db.session.add(SafeBoxTransaction(
            safe_box_id=from_safe_id,
            direction='out',
            ref_type='voucher',
            ref_id=voucher.id,
            created_by=created_by,
            notes=f'{op_label} — خروج {from_karat}k',
            amount_cash=0.0,
            **{f'weight_{from_karat}k': round(gold_weight, 6)},
            **_stones_kw,
        ))

        # SafeBoxTransaction: دخول إلى الوجهة (وزن صافي + فصوص معلوماتي)
        db.session.add(SafeBoxTransaction(
            safe_box_id=to_safe_id,
            direction='in',
            ref_type='voucher',
            ref_id=voucher.id,
            created_by=created_by,
            notes=f'{op_label} — دخول {to_karat}k',
            amount_cash=0.0,
            **{f'weight_{to_karat}k': round(gold_weight, 6)},
            **_stones_kw,
        ))

        db.session.commit()

        resp = {
            'message': f'تم تسجيل عملية {op_label} بنجاح',
            'voucher': voucher.to_dict(),
            'operation': {
                'type': operation_type,
                'from_safe': from_safe.name,
                'to_safe': to_safe.name,
                'from_karat': from_karat,
                'to_karat': to_karat,
                'gold_weight': round(gold_weight, 3),
                'stones_weight': round(stones_weight, 3),
                'damage_wage_amount': round(damage_wage_amount, 2),
            },
        }
        if _stones_je_warning:
            resp['warning'] = _stones_je_warning
        return jsonify(resp), 201

    except Exception as e:
        db.session.rollback()
        import traceback; traceback.print_exc()
        return jsonify({'error': 'melting_renewal_failed', 'message': str(e)}), 500


# =========================================================================
# BNPL Settlement (Tabby/Tamara → Bank)
# =========================================================================


# =========================================================================
# Clearing Settlement (Clearing → Bank)
# =========================================================================


def _compute_clearing_due_amount(safe_box_id):
    """Compute how much is actually owed in a clearing safe box.

    due = ip_in + net_transfer_in - net_voucher_out

    Where:
      net_voucher_out  = voucher OUT − reversal IN
                         (reversal IN undoes a previously counted OUT)
      net_transfer_in  = voucher IN (no IP) − reversal OUT (no IP)
                         (reversal OUT undoes a previously counted transfer IN)

    This correctly handles the cancel-and-redo workflow where a transfer
    voucher was issued then reversed (voucher_reversal), so the cancelled
    amount is no longer double-counted in either direction.
    """
    # Inflow: authoritative IP total via PaymentMethod routing
    ip_in = (
        db.session.query(func.coalesce(func.sum(InvoicePayment.amount), 0.0))
        .join(PaymentMethod, PaymentMethod.id == InvoicePayment.payment_method_id)
        .filter(PaymentMethod.default_safe_box_id == safe_box_id)
        .scalar()
    ) or 0.0

    # Inflow: safe-box transfers arriving (routing corrections, no IP link)
    transfer_in = (
        db.session.query(func.coalesce(func.sum(SafeBoxTransaction.amount_cash), 0.0))
        .filter(
            SafeBoxTransaction.safe_box_id == safe_box_id,
            SafeBoxTransaction.ref_type == 'voucher',
            SafeBoxTransaction.direction == 'in',
            SafeBoxTransaction.invoice_payment_id.is_(None),
        )
        .scalar()
    ) or 0.0

    # Offset: reversal-outs negate previously-counted transfer-ins
    reversal_out = (
        db.session.query(func.coalesce(func.sum(SafeBoxTransaction.amount_cash), 0.0))
        .filter(
            SafeBoxTransaction.safe_box_id == safe_box_id,
            SafeBoxTransaction.ref_type == 'voucher_reversal',
            SafeBoxTransaction.direction == 'out',
            SafeBoxTransaction.invoice_payment_id.is_(None),
        )
        .scalar()
    ) or 0.0

    # Outflow: settlement / transfer vouchers
    voucher_out = (
        db.session.query(func.coalesce(func.sum(SafeBoxTransaction.amount_cash), 0.0))
        .filter(
            SafeBoxTransaction.safe_box_id == safe_box_id,
            SafeBoxTransaction.ref_type == 'voucher',
            SafeBoxTransaction.direction == 'out',
        )
        .scalar()
    ) or 0.0

    # Offset: reversal-ins negate previously-counted voucher-outs
    reversal_in = (
        db.session.query(func.coalesce(func.sum(SafeBoxTransaction.amount_cash), 0.0))
        .filter(
            SafeBoxTransaction.safe_box_id == safe_box_id,
            SafeBoxTransaction.ref_type == 'voucher_reversal',
            SafeBoxTransaction.direction == 'in',
        )
        .scalar()
    ) or 0.0

    net_transfer_in = max(0.0, float(transfer_in) - float(reversal_out))
    net_voucher_out = max(0.0, float(voucher_out) - float(reversal_in))

    return round(float(ip_in) + net_transfer_in - net_voucher_out, 2)


def _create_clearing_settlement_voucher(
    *,
    clearing_safe_box_id,
    bank_safe_box_id,
    gross_amount,
    fee_amount=0.0,
    fee_is_net=True,
    commission_vat_account_id=None,
    settlement_dt=None,
    reference_number=None,
    created_by='system',
    fee_account_id=None,
    description_override=None,
    notes=None,
    ensure_unique_reference: bool = False,
    allow_continuation: bool = False,
    invoice_payment_ids=None,
):
    """Core implementation for clearing settlement.

    This is shared between the HTTP endpoint and the scheduler job.

    allow_continuation: only meaningful when ensure_unique_reference=True and a
    prior voucher with this reference already exists. The caller must have
    already independently confirmed (from SettlementLine-based remaining-due
    data, not from voucher existence) that a genuine unsettled amount remains
    for this reference's period — e.g. the scheduler's daily loop checks
    _compute_due_for_day() > 0 before ever reaching this call. A prior voucher
    means that period was attempted before, not that it was fully covered:
    gross_amount can be capped by running_balance/running_cap mid-loop, which
    deliberately leaves the newest IPs of that period without a SettlementLine
    so they stay visible as pending. When allow_continuation is True, this
    function creates a new, independent voucher (own id/journal entry/
    approval — the prior voucher is never modified) reusing the same
    reference_number as a grouping label, and records which prior voucher(s)
    it continues in `notes` for traceability (non-authoritative — nothing
    depends on that text). Defaults to False so every other caller (manual
    HTTP trigger, per-transaction path) keeps today's exact skip-on-duplicate
    behavior.
    """
    if not clearing_safe_box_id or not bank_safe_box_id:
        raise ValueError('missing_required_fields')

    try:
        gross_amount = float(gross_amount or 0.0)
        fee_amount = float(fee_amount or 0.0)
    except (TypeError, ValueError):
        raise ValueError('invalid_amounts')

    if gross_amount <= 0:
        raise ValueError('gross_amount_must_be_positive')
    if fee_amount < 0:
        raise ValueError('fee_amount_must_be_non_negative')

    # نحتسب ضريبة العمولة عند التسوية لأن النسبة المدخلة صافي ضريبة
    # fee_is_net=True يعني أن fee_amount صافي بدون ضريبة قيمة مضافة
    # إذا كانت الضريبة معطلة في الإعدادات، تكون zero
    def _normalize_tax_rate(raw_value, fallback=0.15):
        try:
            val = float(raw_value)
        except Exception:
            val = float(fallback)
        if val > 1.0:
            val = val / 100.0
        if val < 0:
            val = abs(val)
        return val

    settings_row = None
    try:
        settings_row = Settings.query.first()
    except Exception:
        settings_row = None

    tax_enabled = True
    vat_rate = 0.15
    try:
        tax_enabled = bool(getattr(settings_row, 'tax_enabled', True)) if settings_row else True
        vat_rate = _normalize_tax_rate(getattr(settings_row, 'tax_rate', 0.15) if settings_row else 0.15, fallback=0.15)
    except Exception:
        tax_enabled = True
        vat_rate = 0.15

    fee_vat = 0.0
    if fee_is_net and tax_enabled and fee_amount > 0:
        fee_vat = round(fee_amount * vat_rate, 2)

    net_amount = round(gross_amount - fee_amount - fee_vat, 2)
    if net_amount < 0:
        raise ValueError('fee_amount_exceeds_gross')

    if settlement_dt is None:
        settlement_dt = datetime.now()

    # قفل صف خزينة المقاصة هنا (لا في أي مستدعٍ) كي يحصل كل المستدعين
    # (سكدولر، API اليدوي، أي مستدعٍ مستقبلي) على نفس الحماية ضد تشغيل
    # متزامن يقرأ "المتبقي الحالي" قبل أن يلتزم تشغيل آخر تغييراته —
    # يُحرَّر تلقائياً عند commit/rollback في المستدعي.
    clearing_safe_box = (
        SafeBox.query.filter_by(id=clearing_safe_box_id)
        .with_for_update()
        .first()
    )
    if not clearing_safe_box or not clearing_safe_box.is_active:
        raise ValueError('not_found:clearing_safe_box')

    bank_safe_box = SafeBox.query.get(bank_safe_box_id)
    if not bank_safe_box or not bank_safe_box.is_active:
        raise ValueError('not_found:bank_safe_box')

    if (clearing_safe_box.safe_type or '').strip().lower() != 'clearing':
        raise ValueError('invalid_safe_type:clearing')
    if (bank_safe_box.safe_type or '').strip().lower() != 'bank':
        raise ValueError('invalid_safe_type:bank')

    # Optional idempotency for scheduler jobs
    prior_vouchers_same_reference = []
    if ensure_unique_reference and reference_number:
        prior_vouchers_same_reference = Voucher.query.filter_by(
            reference_type='clearing_settlement',
            reference_number=reference_number,
        ).order_by(Voucher.id.asc()).all()
        if prior_vouchers_same_reference and not allow_continuation:
            existing = prior_vouchers_same_reference[0]
            return {
                'success': True,
                'voucher': existing.to_dict(),
                'balances': {},
                'skipped': True,
                'skip_reason': 'already_exists',
            }
        # allow_continuation=True: a prior voucher for this reference exists,
        # but the caller has already confirmed (via SettlementLine-based
        # remaining-due data) that a genuine unsettled amount remains. Fall
        # through and create a new, independent voucher — see docstring.

    # HARD GUARD (anti double-deduction):
    # If the clearing safe box is the default safe for one or more payment methods,
    # and those methods record commission at invoice time, then fee must be zero here.
    if fee_amount > 0:
        try:
            matched_methods = (
                PaymentMethod.query
                .filter_by(default_safe_box_id=clearing_safe_box.id, is_active=True)
                .all()
            )
        except Exception:
            matched_methods = []

        if matched_methods:
            timings = set()
            for pm in matched_methods:
                try:
                    t = str(getattr(pm, 'commission_timing', 'invoice') or 'invoice').strip().lower()
                except Exception:
                    t = 'invoice'
                if t not in {'invoice', 'settlement'}:
                    t = 'invoice'
                timings.add(t)

            if 'invoice' in timings:
                raise ValueError('fee_not_allowed_when_commission_timing_invoice')

    clearing_account = clearing_safe_box.account
    bank_account = bank_safe_box.account
    if not clearing_account or not bank_account:
        raise ValueError('safe_box_missing_account')

    fee_account = None
    if fee_amount > 0:
        if not fee_account_id:
            # Auto-resolve from the PaymentMethod linked to this clearing safe.
            # Use joinedload to fetch fee_expense_account in one query (avoids N+1).
            matched_pm = (
                PaymentMethod.query
                .options(joinedload(PaymentMethod.fee_expense_account))
                .filter_by(default_safe_box_id=clearing_safe_box_id)
                .first()
            )
            if matched_pm and getattr(matched_pm, 'fee_expense_account_id', None):
                fee_account_id = matched_pm.fee_expense_account_id
            else:
                # Fall back to a generic commission-expense account if it exists
                generic = (
                    Account.query.filter_by(account_number='5100').first()
                    or Account.query.filter_by(account_number='5110').first()
                    or Account.query.filter_by(account_number='5113').first()
                )
                if generic:
                    fee_account_id = generic.id

        if not fee_account_id:
            raise ValueError('fee_account_id_required')
        fee_account = Account.query.get(fee_account_id)
        if not fee_account:
            raise ValueError('not_found:fee_account')

    commission_vat_account = None
    if fee_vat > 0:
        # Prefer a dedicated account for VAT on commissions; if not configured,
        # fall back to the generic VAT receivable (input VAT) account.
        commission_vat_account_id = (
            commission_vat_account_id
            or get_account_id_for_mapping('بيع', 'commission_vat')
            or _get_default_account_id('commission_vat')
        )
        if commission_vat_account_id:
            commission_vat_account = Account.query.get(commission_vat_account_id)

        if not commission_vat_account:
            fallback_vat_id = (
                get_account_id_for_mapping('بيع', 'vat_receivable')
                or _get_default_account_id('vat_receivable')
            )
            if fallback_vat_id:
                commission_vat_account = Account.query.get(fallback_vat_id)

        if not commission_vat_account:
            raise ValueError('commission_vat_account_not_found')

    def _live_cash_balance(account_obj, fallback=0.0):
        account_id = getattr(account_obj, 'id', None)
        if account_id is None:
            return float(fallback or 0.0)
        try:
            live = live_balances_by_account_ids([int(account_id)]).get(int(account_id))
            if isinstance(live, dict):
                return float(live.get('cash') or 0.0)
        except Exception:
            pass
        return float(fallback or 0.0)

    clearing_balance = _live_cash_balance(
        clearing_account,
        fallback=float(getattr(clearing_account, 'balance_cash', 0.0) or 0.0),
    )
    if clearing_balance < gross_amount:
        raise ValueError('insufficient_clearing_balance')

    # Due-amount guard: prevent settling more than what's actually owed.
    due_amount = _compute_clearing_due_amount(clearing_safe_box_id)
    if due_amount < 0.01:
        raise ValueError('no_due_amount')
    if gross_amount > due_amount + 0.01:
        raise ValueError(f'exceeds_due_amount:{due_amount:.2f}')

    voucher_number = generate_voucher_number('adjustment', voucher_date=settlement_dt)

    if description_override:
        description = description_override
    else:
        description = (
            f'تسوية مستحقات تحصيل: {clearing_safe_box.name} → {bank_safe_box.name} '
            f'(إجمالي {gross_amount:.2f}، عمولة {fee_amount:.2f}، صافي {net_amount:.2f})'
        )

    final_notes = (notes or '').strip()
    if prior_vouchers_same_reference:
        # تتبّع نصي بحت (غير معتمَد من أي منطق) — للتدقيق البشري فقط:
        # رقم الدفعة وأسلاف نفس المرجع محسوبان من السندات الموجودة، لا قيمة مخزَّنة منفصلة.
        prior_numbers = ', '.join(v.voucher_number for v in prior_vouchers_same_reference)
        continuation_note = (
            f'دفعة تكميلية #{len(prior_vouchers_same_reference) + 1} لمرجع {reference_number} '
            f'— يتبع: {prior_numbers}'
        )
        final_notes = f'{final_notes}\n{continuation_note}'.strip()

    voucher = Voucher(
        voucher_number=voucher_number,
        voucher_type='adjustment',
        date=settlement_dt,
        description=description,
        reference_type='clearing_settlement',
        reference_id=clearing_safe_box_id,
        reference_number=reference_number,
        notes=final_notes or None,
        created_by=created_by,
        status='approved',
        approved_by=created_by,
        approved_at=datetime.now(),
        amount_cash=round(gross_amount, 2),
        amount_gold=0.0,
    )
    db.session.add(voucher)
    db.session.flush()

    if net_amount > 0:
        db.session.add(VoucherAccountLine(
            voucher_id=voucher.id,
            account_id=bank_account.id,
            line_type='debit',
            amount_type='cash',
            amount=round(net_amount, 2),
            description=f'إيداع صافي تسوية مستحقات إلى {bank_safe_box.name}',
        ))

    if fee_amount > 0 and fee_account:
        db.session.add(VoucherAccountLine(
            voucher_id=voucher.id,
            account_id=fee_account.id,
            line_type='debit',
            amount_type='cash',
            amount=round(fee_amount, 2),
            description='عمولة تحصيل (صافي)',
        ))

    if fee_vat > 0 and commission_vat_account:
        db.session.add(VoucherAccountLine(
            voucher_id=voucher.id,
            account_id=commission_vat_account.id,
            line_type='debit',
            amount_type='cash',
            amount=round(fee_vat, 2),
            description='ضريبة قيمة مضافة على عمولة التحصيل',
        ))

    db.session.add(VoucherAccountLine(
        voucher_id=voucher.id,
        account_id=clearing_account.id,
        line_type='credit',
        amount_type='cash',
        amount=round(gross_amount, 2),
        description='إقفال مستحقات التحصيل',
    ))

    db.session.flush()

    journal_entry = create_journal_entry_from_voucher(voucher)
    if journal_entry:
        voucher.journal_entry_id = journal_entry.id

    _append_safe_transactions_for_voucher(voucher, created_by=created_by)

    clearing_account.update_balance(cash_amount=-gross_amount)
    bank_account.update_balance(cash_amount=net_amount)
    if fee_account:
        fee_account.update_balance(cash_amount=fee_amount)
    if commission_vat_account:
        commission_vat_account.update_balance(cash_amount=fee_vat)

    # --- Per-transaction settlement lines ---
    # If the caller provided specific invoice_payment_ids, link them to this
    # voucher.  Only create SettlementLine entries for IPs that are actually
    # covered by gross_amount (FIFO from oldest to newest).  This prevents
    # "phantom settlement" where an IP is marked settled but the voucher amount
    # did not actually include its value — which causes due_amount > 0 while
    # pending_count = 0 on subsequent queries.
    if invoice_payment_ids:
        ip_rows = sorted(
            InvoicePayment.query.filter(
                InvoicePayment.id.in_(invoice_payment_ids)
            ).all(),
            key=lambda x: x.created_at or datetime.min,
        )
        # Root-cause fix (2026-07-01): cancel_voucher() now deletes SettlementLine
        # rows for clearing_settlement vouchers, so future cancellations won't
        # leave phantom-settled IPs. See the cancel_voucher() edit above.
        #
        # This approved-filter predates that fix (added after incident
        # AV-2026-00133 in May 2026 -- IP#1547 phantom-settled from cancelled
        # AV-130/AV-131). It is kept here as protection against the existing
        # historical orphaned rows from those 3 vouchers (AV-130/131/132) until
        # they are cleaned up in the DB. Once cleaned, this filter becomes
        # redundant with get_settled_amounts() and can be simplified.
        _all_ids = [ip.id for ip in ip_rows]
        _prev_settled: dict = {}
        if _all_ids:
            _sl_rows = (
                db.session.query(
                    SettlementLine.invoice_payment_id,
                    func.coalesce(func.sum(SettlementLine.amount_settled), 0.0),
                )
                .join(Voucher, Voucher.id == SettlementLine.voucher_id)
                .filter(SettlementLine.invoice_payment_id.in_(_all_ids))
                .filter(Voucher.status == 'approved')
                .group_by(SettlementLine.invoice_payment_id)
                .all()
            )
            _prev_settled = {r[0]: round(float(r[1]), 2) for r in _sl_rows}
        ip_total = sum(float(ip.amount or 0) for ip in ip_rows) or 1.0
        remaining_gross = round(float(gross_amount), 2)
        for ip in ip_rows:
            if remaining_gross <= 0.005:
                # gross_amount exhausted: stop — do NOT create SettlementLine
                # for remaining IPs so they stay visible as pending next cycle.
                break
            ip_amt = round(float(ip.amount or 0), 2)
            already_settled = _prev_settled.get(ip.id, 0.0)
            # Use the true remaining balance, not the full IP amount.
            ip_remaining = round(ip_amt - already_settled, 2)
            if ip_remaining <= 0.005:
                continue
            amount_to_settle = round(min(ip_remaining, remaining_gross), 2)
            ratio = ip_amt / ip_total
            db.session.add(SettlementLine(
                voucher_id=voucher.id,
                invoice_payment_id=ip.id,
                amount_settled=amount_to_settle,
                commission=round(fee_amount * ratio, 2),
                commission_vat=round(fee_vat * ratio, 2),
            ))
            remaining_gross = round(remaining_gross - amount_to_settle, 2)

        # Invariant: when the caller asks us to link specific invoice
        # payments, the SettlementLine total we actually created must equal
        # gross_amount. If the given invoice_payment_ids can't absorb the
        # full gross_amount (e.g. a manual entry listing fewer/smaller IPs
        # than the amount entered), reject the whole voucher instead of
        # silently crediting cash with no matching SettlementLine — that
        # silent gap is exactly what produced AV-2026-00133's unexplained
        # +6050 (credited 19710, SettlementLine totalled only 13660).
        if remaining_gross > 0.01:
            raise ValueError(
                f'settlement_line_coverage_mismatch:requested={gross_amount:.2f},'
                f'unallocated={remaining_gross:.2f}'
            )

    return {
        'success': True,
        'voucher': voucher.to_dict(),
        'balances': {
            'clearing_account_cash': round(_live_cash_balance(clearing_account, fallback=float(getattr(clearing_account, 'balance_cash', 0.0) or 0.0)), 2),
            'bank_account_cash': round(_live_cash_balance(bank_account, fallback=float(getattr(bank_account, 'balance_cash', 0.0) or 0.0)), 2),
            **({'fee_account_cash': round(_live_cash_balance(fee_account, fallback=float(getattr(fee_account, 'balance_cash', 0.0) or 0.0)), 2)} if fee_account else {}),
            **({'commission_vat_account_cash': round(_live_cash_balance(commission_vat_account, fallback=float(getattr(commission_vat_account, 'balance_cash', 0.0) or 0.0)), 2)} if commission_vat_account else {}),
        }
    }


@api.route('/clearing/settlements', methods=['POST'])
@require_permission('vouchers.create')
def create_clearing_settlement():
    """Create a clearing settlement voucher and update balances.

    Best practice flow:
    - Credit: Clearing receivable (gross)
    - Debit: Bank (net)
    - Debit: Commission expense (fee)

    Body:
      - clearing_safe_box_id: int (required) (alias: from_safe_box_id)
      - bank_safe_box_id: int (required) (alias: to_safe_box_id)
      - gross_amount: float (required) (alias: amount)
      - fee_amount: float (optional, default 0) (alias: fee)
      - settlement_date: ISO datetime/date (optional)
      - reference_number: str (optional)
      - created_by: str (optional)
      - fee_account_id: int (required if fee_amount > 0)
      - description: str (optional)
    """
    data = request.get_json(silent=True) or {}

    clearing_safe_box_id = data.get('clearing_safe_box_id') or data.get('from_safe_box_id')
    bank_safe_box_id = data.get('bank_safe_box_id') or data.get('to_safe_box_id')
    created_by = data.get('created_by', 'system')
    reference_number = data.get('reference_number')
    description_override = (data.get('description') or '').strip() or None
    fee_is_net = bool(data.get('fee_is_net', True))
    commission_vat_account_id = data.get('commission_vat_account_id')

    # Parse settlement date
    settlement_date_raw = data.get('settlement_date') or data.get('date')
    settlement_dt = datetime.now()
    if settlement_date_raw:
        try:
            if isinstance(settlement_date_raw, str) and len(settlement_date_raw) == 10:
                settlement_dt = datetime.fromisoformat(settlement_date_raw + 'T00:00:00')
            else:
                settlement_dt = datetime.fromisoformat(settlement_date_raw)
        except Exception:
            return jsonify({'error': 'invalid settlement_date'}), 400

    try:
        result = _create_clearing_settlement_voucher(
            clearing_safe_box_id=clearing_safe_box_id,
            bank_safe_box_id=bank_safe_box_id,
            gross_amount=(data.get('gross_amount') or data.get('amount') or 0.0),
            fee_amount=(data.get('fee_amount') or data.get('fee') or 0.0),
            fee_is_net=fee_is_net,
            commission_vat_account_id=commission_vat_account_id,
            settlement_dt=settlement_dt,
            reference_number=reference_number,
            created_by=created_by,
            fee_account_id=data.get('fee_account_id'),
            description_override=description_override,
            notes=(data.get('notes') or ''),
            invoice_payment_ids=data.get('invoice_payment_ids'),
        )
        db.session.commit()
        return jsonify(result), 201

    except ValueError as exc:
        db.session.rollback()
        msg = str(exc)
        if msg.startswith('not_found:'):
            which = msg.split(':', 1)[1]
            if which == 'clearing_safe_box':
                return jsonify({'error': 'Clearing safe box not found or inactive'}), 404
            if which == 'bank_safe_box':
                return jsonify({'error': 'Bank safe box not found or inactive'}), 404
            if which == 'fee_account':
                return jsonify({'error': 'fee_account_id not found'}), 404
            return jsonify({'error': 'not_found'}), 404

        if msg == 'missing_required_fields':
            return jsonify({'error': 'clearing_safe_box_id and bank_safe_box_id are required'}), 400
        if msg == 'invalid_amounts':
            return jsonify({'error': 'invalid gross_amount/fee_amount'}), 400
        if msg == 'gross_amount_must_be_positive':
            return jsonify({'error': 'gross_amount must be > 0'}), 400
        if msg == 'fee_amount_must_be_non_negative':
            return jsonify({'error': 'fee_amount must be >= 0'}), 400
        if msg == 'fee_amount_exceeds_gross':
            return jsonify({'error': 'fee_amount cannot exceed gross_amount'}), 400
        if msg.startswith('invalid_safe_type:'):
            which = msg.split(':', 1)[1]
            if which == 'clearing':
                return jsonify({'error': 'clearing_safe_box must be of type clearing'}), 400
            if which == 'bank':
                return jsonify({'error': 'bank_safe_box must be of type bank'}), 400
            return jsonify({'error': 'invalid_safe_type'}), 400
        if msg == 'safe_box_missing_account':
            return jsonify({'error': 'Safe box must be linked to an account'}), 400
        if msg == 'fee_account_id_required':
            return jsonify({'error': 'fee_account_id is required for fee_amount > 0'}), 400
        if msg == 'no_due_amount':
            return jsonify({
                'error': 'no_due_amount',
                'message': 'لا يوجد مبلغ مستحق للتسوية في هذه الخزينة — قد تكون جميع الدفعات تمت تسويتها مسبقاً.',
                'due_amount': 0.0,
            }), 400
        if msg.startswith('exceeds_due_amount:'):
            due_str = msg.split(':', 1)[1]
            return jsonify({
                'error': 'exceeds_due_amount',
                'message': f'المبلغ المطلوب يتجاوز المبلغ المستحق للتسوية ({due_str} ر.س)',
                'due_amount': float(due_str),
                'gross_amount': round(float(data.get('gross_amount') or data.get('amount') or 0.0), 2),
            }), 400
        if msg == 'insufficient_clearing_balance':
            try:
                clearing_safe_box_id = data.get('clearing_safe_box_id') or data.get('from_safe_box_id')
                clearing_safe_box = SafeBox.query.get(clearing_safe_box_id)
                clearing_account = getattr(clearing_safe_box, 'account', None)
                if clearing_account and getattr(clearing_account, 'id', None) is not None:
                    live = live_balances_by_account_ids([int(clearing_account.id)]).get(int(clearing_account.id))
                    clearing_balance = float((live or {}).get('cash') or 0.0)
                else:
                    clearing_balance = 0.0
            except Exception:
                clearing_balance = 0.0
            gross_amount = float(data.get('gross_amount') or data.get('amount') or 0.0)
            return jsonify({
                'error': 'Clearing balance is insufficient for settlement',
                'clearing_balance': round(clearing_balance, 2),
                'gross_amount': round(gross_amount, 2),
            }), 400

        if msg == 'fee_not_allowed_when_commission_timing_invoice':
            # Preserve richer error payload for client UX
            try:
                clearing_safe_box = SafeBox.query.get(clearing_safe_box_id)
            except Exception:
                clearing_safe_box = None
            methods_payload = []
            try:
                if clearing_safe_box:
                    matched = (
                        PaymentMethod.query
                        .filter_by(default_safe_box_id=clearing_safe_box.id, is_active=True)
                        .all()
                    )
                    for pm in matched:
                        try:
                            t = str(getattr(pm, 'commission_timing', 'invoice') or 'invoice').strip().lower()
                        except Exception:
                            t = 'invoice'
                        if t not in {'invoice', 'settlement'}:
                            t = 'invoice'
                        methods_payload.append({'id': pm.id, 'name': pm.name, 'commission_timing': t})
            except Exception:
                methods_payload = []

            return jsonify({
                'error': 'fee_not_allowed_when_commission_timing_invoice',
                'message': (
                    'لا يمكن إرسال عمولة (fee) في التسوية لأن سياسة العمولة لهذه الخزينة '
                    'تسجل العمولة ضمن الفاتورة (commission_timing=invoice) أو توجد سياسات متضاربة. '
                    'لمنع خصم العمولة مرتين: اجعل fee=0 أو غيّر سياسة وسيلة الدفع إلى settlement '
                    'أو استخدم خزينة مستحقات منفصلة لكل سياسة.'
                ),
                'clearing_safe_box_id': clearing_safe_box.id if clearing_safe_box else clearing_safe_box_id,
                'fee_amount': round(float(data.get('fee_amount') or data.get('fee') or 0.0), 2),
                'payment_methods': methods_payload,
            }), 400

        return jsonify({'error': 'validation_error', 'message': msg}), 400

    except Exception as exc:
        db.session.rollback()
        return jsonify({'error': f'Failed to create clearing settlement: {str(exc)}'}), 500


# =========================================================================
# Per-Transaction Clearing Settlement (one voucher per invoice payment)
# =========================================================================


@api.route('/clearing/settlements/per-transaction', methods=['POST'])
@require_permission('vouchers.create')
def create_per_transaction_clearing_settlement():
    """Create individual clearing settlement vouchers — one per unsettled
    invoice payment in a clearing safe box.

    Body:
      - clearing_safe_box_id: int (required)
      - bank_safe_box_id: int (required)
      - commission_rate: float (optional, default from PM)
      - commission_fixed: float (optional, default from PM)
      - fee_account_id: int (optional, default from PM)
      - settlement_date: ISO string (optional)
      - created_by: str (optional)
    """
    data = request.get_json(silent=True) or {}

    clearing_safe_box_id = data.get('clearing_safe_box_id') or data.get('from_safe_box_id')
    bank_safe_box_id = data.get('bank_safe_box_id') or data.get('to_safe_box_id')
    created_by = data.get('created_by', 'system')

    if not clearing_safe_box_id or not bank_safe_box_id:
        return jsonify({'error': 'clearing_safe_box_id and bank_safe_box_id are required'}), 400

    clearing_sb = SafeBox.query.get(clearing_safe_box_id)
    bank_sb = SafeBox.query.get(bank_safe_box_id)
    if not clearing_sb or not clearing_sb.is_active:
        return jsonify({'error': 'Clearing safe box not found or inactive'}), 404
    if not bank_sb or not bank_sb.is_active:
        return jsonify({'error': 'Bank safe box not found or inactive'}), 404
    if (clearing_sb.safe_type or '').strip().lower() != 'clearing':
        return jsonify({'error': 'Source must be a clearing safe box'}), 400
    if (bank_sb.safe_type or '').strip().lower() != 'bank':
        return jsonify({'error': 'Target must be a bank safe box'}), 400

    # Resolve commission parameters from payment method
    matched_pm = (
        PaymentMethod.query
        .filter_by(default_safe_box_id=clearing_safe_box_id, is_active=True)
        .first()
    )
    rate = float(data.get('commission_rate') if 'commission_rate' in data
                 else (getattr(matched_pm, 'commission_rate', 0.0) or 0.0) if matched_pm else 0.0)
    fixed = float(data.get('commission_fixed') if 'commission_fixed' in data
                  else (getattr(matched_pm, 'commission_fixed_amount', 0.0) or 0.0) if matched_pm else 0.0)

    fee_account_id = data.get('fee_account_id')
    if fee_account_id is None and matched_pm:
        fee_account_id = getattr(matched_pm, 'fee_expense_account_id', None)

    # Check commission_timing — if 'invoice', fee must be 0
    timing = 'invoice'
    if matched_pm:
        timing = str(getattr(matched_pm, 'commission_timing', 'invoice') or 'invoice').strip().lower()

    # Parse settlement date
    settlement_date_raw = data.get('settlement_date') or data.get('date')
    settlement_dt = datetime.now()
    if settlement_date_raw:
        try:
            if isinstance(settlement_date_raw, str) and len(settlement_date_raw) == 10:
                settlement_dt = datetime.fromisoformat(settlement_date_raw + 'T00:00:00')
            else:
                settlement_dt = datetime.fromisoformat(settlement_date_raw)
        except Exception:
            return jsonify({'error': 'invalid settlement_date'}), 400

    # Find unsettled invoice payments in this clearing safe box
    # An invoice_payment SafeBoxTransaction is "unsettled" if no clearing_settlement
    # voucher has created a corresponding 'out' transaction referencing it.
    try:
        unsettled_txs = (
            SafeBoxTransaction.query
            .filter_by(
                safe_box_id=clearing_safe_box_id,
                ref_type='invoice_payment',
                direction='in',
            )
            .order_by(SafeBoxTransaction.created_at.asc())
            .all()
        )
    except Exception as exc:
        return jsonify({'error': f'Failed to query transactions: {exc}'}), 500

    # ----------------------------------------------------------------
    # Determine which payments are still pending using the same FIFO
    # hybrid approach as the pending-transactions GET endpoint.
    # This correctly handles both per-tx and bulk settlements.
    # ----------------------------------------------------------------

    # (a) Per-tx settled IDs
    settled_ip_ids = set()
    try:
        settled_txs = (
            db.session.query(SafeBoxTransaction.notes)
            .join(Voucher, Voucher.id == SafeBoxTransaction.ref_id)
            .filter(
                SafeBoxTransaction.safe_box_id == clearing_safe_box_id,
                SafeBoxTransaction.ref_type.in_(['voucher', 'voucher_reversal']),
                Voucher.reference_type == 'clearing_settlement',
                SafeBoxTransaction.notes.isnot(None),
            )
            .all()
        )
        for (note_val,) in settled_txs:
            if note_val and note_val.startswith('per_tx:ip_'):
                try:
                    settled_ip_ids.add(int(note_val.split('per_tx:ip_')[1]))
                except Exception:
                    pass
    except Exception:
        pass

    # (b) Aggregate settled total from clearing_settlement vouchers
    aggregate_settled = 0.0
    try:
        settled_signed = func.coalesce(
            func.sum(
                case(
                    (SafeBoxTransaction.direction == 'out', SafeBoxTransaction.amount_cash),
                    else_=-SafeBoxTransaction.amount_cash,
                )
            ),
            0.0,
        )
        aggregate_settled = float(
            db.session.query(settled_signed)
            .join(Voucher, Voucher.id == SafeBoxTransaction.ref_id)
            .filter(
                SafeBoxTransaction.safe_box_id == clearing_safe_box_id,
                SafeBoxTransaction.ref_type.in_(['voucher', 'voucher_reversal']),
                Voucher.reference_type == 'clearing_settlement',
            )
            .scalar()
            or 0.0
        )
    except Exception:
        pass

    # (c) FIFO walk: consume bulk-settled amount across non-per-tx payments
    remaining_bulk_settled = max(aggregate_settled, 0.0)
    pending = []
    for tx in unsettled_txs:
        ip_id = tx.invoice_payment_id or tx.id
        if ip_id in settled_ip_ids:
            remaining_bulk_settled -= round(float(tx.amount_cash or 0.0), 2)
            continue
        tx_amount = round(float(tx.amount_cash or 0.0), 2)
        if remaining_bulk_settled >= tx_amount - 0.005:
            remaining_bulk_settled -= tx_amount
            continue
        pending.append(tx)

    if not pending:
        return jsonify({
            'success': True,
            'message': 'لا توجد معاملات معلّقة للتسوية',
            'settled_count': 0,
            'vouchers': [],
        }), 200

    # Process each transaction
    results = []
    errors = []
    for tx in pending:
        try:
            gross = round(float(tx.amount_cash or 0.0), 2)
            if gross <= 0.01:
                continue

            # Compute fee
            fee = 0.0
            if timing == 'settlement':
                fee = round((gross * rate / 100.0) + fixed, 2)

            ref_num = f"PERTX-IP{tx.invoice_payment_id or tx.id}-{settlement_dt.strftime('%Y%m%d')}"

            # Build description with invoice info
            inv_info = ''
            if tx.invoice_id:
                try:
                    inv = Invoice.query.get(tx.invoice_id)
                    if inv:
                        inv_info = f' (فاتورة {inv.invoice_number})'
                except Exception:
                    pass

            desc = (
                f'تسوية فردية: {clearing_sb.name} → {bank_sb.name}'
                f' — مبلغ {gross:.2f}{inv_info}'
            )

            result = _create_clearing_settlement_voucher(
                clearing_safe_box_id=clearing_sb.id,
                bank_safe_box_id=bank_sb.id,
                gross_amount=gross,
                fee_amount=fee,
                settlement_dt=settlement_dt,
                reference_number=ref_num,
                created_by=created_by,
                fee_account_id=fee_account_id if fee > 0 else None,
                description_override=desc,
                notes=f'per_tx:ip_{tx.invoice_payment_id or tx.id}',
                ensure_unique_reference=True,
            )

            if result.get('skipped'):
                continue

            results.append({
                'invoice_payment_id': tx.invoice_payment_id,
                'invoice_id': tx.invoice_id,
                'gross': gross,
                'fee': fee,
                'voucher_number': result.get('voucher', {}).get('voucher_number'),
            })
        except Exception as exc:
            errors.append({
                'tx_id': tx.id,
                'invoice_payment_id': tx.invoice_payment_id,
                'error': str(exc),
            })
            db.session.rollback()

    if results:
        try:
            db.session.commit()
        except Exception as exc:
            db.session.rollback()
            return jsonify({'error': f'Failed to commit: {exc}'}), 500

    return jsonify({
        'success': True,
        'settled_count': len(results),
        'settlements': results,
        'errors': errors if errors else None,
    }), 201


@api.route('/clearing/settlements/pending-transactions', methods=['GET'])
@require_permission('vouchers.create')
def get_pending_settlement_transactions():
    """List unsettled invoice payment transactions in a clearing safe box.

    Query params:
      - clearing_safe_box_id: int (required)
    """
    clearing_safe_box_id = request.args.get('clearing_safe_box_id', type=int)
    if not clearing_safe_box_id:
        return jsonify({'error': 'clearing_safe_box_id is required'}), 400

    clearing_sb = SafeBox.query.get(clearing_safe_box_id)
    if not clearing_sb:
        return jsonify({'error': 'Safe box not found'}), 404

    try:
        # Source payments from InvoicePayment (always authoritative) rather than
        # SafeBoxTransaction, because historical SBTs may carry the wrong
        # safe_box_id (multi-payment invoice routing bug fixed Apr 2026).
        all_ips = (
            InvoicePayment.query
            .join(PaymentMethod, PaymentMethod.id == InvoicePayment.payment_method_id)
            .filter(PaymentMethod.default_safe_box_id == clearing_safe_box_id)
            .order_by(InvoicePayment.created_at.asc())
            .all()
        )
    except Exception as exc:
        return jsonify({'error': str(exc)}), 500

    # ----------------------------------------------------------------
    # Determine which invoice-payment transactions are still pending.
    #
    # Uses SettlementLine amounts (supports partial settlements) to
    # compute per-IP remaining balance.  An IP is pending when:
    #   remaining = IP.amount - sum(SL.amount_settled) > 0
    # ----------------------------------------------------------------

    all_ip_ids = [ip.id for ip in all_ips]

    # Sum settled amount per IP from SettlementLine table.
    settled_by_ip = {}  # ip_id → total amount already settled
    try:
        settled_by_ip = get_settled_amounts(all_ip_ids)
    except Exception:
        pass

    # Also check legacy per_tx notes on Voucher (treat as fully settled).
    legacy_settled_ip_ids = set()
    try:
        clearing_account_id = getattr(clearing_sb, 'account_id', None)
        per_tx_q = (
            db.session.query(Voucher.notes)
            .filter(
                Voucher.reference_type == 'clearing_settlement',
                Voucher.notes.isnot(None),
                Voucher.notes.like('%per_tx:ip_%'),
            )
        )
        if clearing_account_id:
            per_tx_q = per_tx_q.join(
                VoucherAccountLine, VoucherAccountLine.voucher_id == Voucher.id
            ).filter(VoucherAccountLine.account_id == clearing_account_id)
        for (note_val,) in per_tx_q.distinct().all():
            if note_val and 'per_tx:ip_' in note_val:
                try:
                    legacy_settled_ip_ids.add(int(note_val.split('per_tx:ip_')[1].split()[0]))
                except Exception:
                    pass
    except Exception:
        pass

    # Build pending list: IPs with remaining unsettled balance.
    due_amount = _compute_clearing_due_amount(clearing_safe_box_id)

    # ── Transfer-out FIFO attribution ────────────────────────────────────────
    # If some voucher_out rows are transfer outflows (no SettlementLine backing),
    # we must "consume" the oldest IPs first so they don't falsely appear pending.
    #
    # net_voucher_out = voucher OUT − reversal IN  (reversals undo cancelled outs)
    # transfer_out_unaccounted = net_voucher_out − (SettlementLine + legacy)
    # This remainder is attributed FIFO-first to IPs so they are hidden from the list.
    try:
        total_voucher_out = (
            db.session.query(func.coalesce(func.sum(SafeBoxTransaction.amount_cash), 0.0))
            .filter(
                SafeBoxTransaction.safe_box_id == clearing_safe_box_id,
                SafeBoxTransaction.ref_type == 'voucher',
                SafeBoxTransaction.direction == 'out',
            )
            .scalar()
        ) or 0.0
        total_voucher_out = round(float(total_voucher_out), 2)

        # Subtract reversal-ins: they undo previously-counted voucher-outs
        total_reversal_in = (
            db.session.query(func.coalesce(func.sum(SafeBoxTransaction.amount_cash), 0.0))
            .filter(
                SafeBoxTransaction.safe_box_id == clearing_safe_box_id,
                SafeBoxTransaction.ref_type == 'voucher_reversal',
                SafeBoxTransaction.direction == 'in',
            )
            .scalar()
        ) or 0.0
        net_voucher_out = max(0.0, round(total_voucher_out - float(total_reversal_in), 2))

        # Total already covered by SettlementLine records
        sl_covered = round(sum(settled_by_ip.values()), 2)

        # Legacy-settled IPs: treated as fully covered
        legacy_covered = 0.0
        for ip in all_ips:
            if ip.id in legacy_settled_ip_ids:
                legacy_covered += float(ip.amount or 0)
        legacy_covered = round(legacy_covered, 2)

        # Unaccounted outflow = net settlement-outs that consumed IPs without SettlementLine
        transfer_out_unaccounted = max(0.0, round(net_voucher_out - sl_covered - legacy_covered, 2))

        # ── FIFO cap ─────────────────────────────────────────────────────────
        # transfer_out_unaccounted can be inflated by "ghost credits" — voucher
        # outs that settled non-IP items (e.g. direct invoice JEs from before
        # the PaymentMethod routing system was in place).  If we use the raw
        # figure, FIFO consumes genuinely-pending IPs, making them invisible.
        #
        # Correct cap:  FIFO may only consume up to:
        #   non_sl_ip_total − due_amount
        # where non_sl_ip_total = sum of remaining IP balances with no SL record.
        # That equals the IPs truly settled historically without SL,
        # leaving due_amount worth of IPs visible as pending.
        non_sl_ip_total = round(sum(
            max(0.0, round(float(ip.amount or 0), 2) - round(settled_by_ip.get(ip.id, 0.0), 2))
            for ip in all_ips
            if ip.id not in legacy_settled_ip_ids
        ), 2)
        fifo_cap = max(0.0, round(non_sl_ip_total - max(0.0, due_amount), 2))
        transfer_out_unaccounted = min(transfer_out_unaccounted, fifo_cap)
        # ─────────────────────────────────────────────────────────────────────
    except Exception:
        transfer_out_unaccounted = 0.0

    # Extra credit per IP consumed by transfer-out (FIFO applied below)
    transfer_credit_by_ip = {}  # ip_id → extra amount consumed by transfer-out
    if transfer_out_unaccounted > 0.005:
        remaining_credit = transfer_out_unaccounted
        for ip in all_ips:
            if ip.id in legacy_settled_ip_ids or remaining_credit <= 0.005:
                break
            ip_amount = round(float(ip.amount or 0.0), 2)
            already_settled = round(settled_by_ip.get(ip.id, 0.0), 2)
            available = round(ip_amount - already_settled, 2)
            if available <= 0.005:
                continue
            consumed = min(available, remaining_credit)
            transfer_credit_by_ip[ip.id] = round(consumed, 2)
            remaining_credit = round(remaining_credit - consumed, 2)
    # ────────────────────────────────────────────────────────────────────────
    # Compute how much transfer_out_unaccounted remains after IP FIFO attribution.
    # This remainder covers safe_transfer-in items (inter-safe corrections).
    transfer_out_remaining_after_ips = max(0.0, round(
        transfer_out_unaccounted - sum(transfer_credit_by_ip.values()), 2
    ))

    pending = []
    for ip in all_ips:  # already ordered by created_at asc
        if ip.id in legacy_settled_ip_ids:
            continue
        ip_amount = round(float(ip.amount or 0.0), 2)
        settled = round(settled_by_ip.get(ip.id, 0.0) + transfer_credit_by_ip.get(ip.id, 0.0), 2)
        remaining = round(ip_amount - settled, 2)
        if remaining <= 0.005:
            continue
        invoice_number = None
        invoice_id = ip.invoice_id
        if invoice_id:
            try:
                inv = Invoice.query.get(invoice_id)
                if inv:
                    invoice_number = inv.invoice_number
            except Exception:
                pass
        pending.append({
            'tx_id': ip.id,
            'invoice_payment_id': ip.id,
            'invoice_id': invoice_id,
            'invoice_number': invoice_number,
            'amount': remaining,
            'date': ip.created_at.isoformat() if ip.created_at else None,
            'type': 'invoice_payment',
        })

    # tx_count_for_fee: number of pending invoice-payment transactions only.
    # Transfer-in items below are NOT counted since they don't carry a
    # per-transaction fee in the normal commission model.
    tx_count_for_fee = len(pending)

    # Also include safe-box transfer-in items as pending.
    # These arise when an operator corrects a routing error by transferring
    # from one clearing safe to another (e.g. تابي → تمارا).  The destination
    # safe receives an SBT in/voucher with no invoice_payment_id.
    #
    # Reversals: a voucher_reversal SBT shares the same ref_id as the original
    # transfer SBT it cancels.  We match by ref_id to exclude fully-reversed
    # transfers rather than proportionally reducing all of them.
    try:
        transfer_in_sbts = (
            SafeBoxTransaction.query
            .filter(
                SafeBoxTransaction.safe_box_id == clearing_safe_box_id,
                SafeBoxTransaction.ref_type == 'voucher',
                SafeBoxTransaction.direction == 'in',
                SafeBoxTransaction.invoice_payment_id.is_(None),
            )
            .order_by(SafeBoxTransaction.created_at.asc())
            .all()
        )

        if transfer_in_sbts:
            # Build a set of ref_ids that have been reversed (voucher_reversal out, no IP).
            # A ref_id in this set means the transfer was cancelled and should be excluded.
            reversal_out_sbts = (
                SafeBoxTransaction.query
                .filter(
                    SafeBoxTransaction.safe_box_id == clearing_safe_box_id,
                    SafeBoxTransaction.ref_type == 'voucher_reversal',
                    SafeBoxTransaction.direction == 'out',
                    SafeBoxTransaction.invoice_payment_id.is_(None),
                )
                .all()
            )
            reversed_ref_ids = set()
            reversal_by_ref = {}  # ref_id → total reversed amount
            for r in reversal_out_sbts:
                rid = r.ref_id
                if rid is not None:
                    reversed_ref_ids.add(rid)
                    reversal_by_ref[rid] = reversal_by_ref.get(rid, 0.0) + float(r.amount_cash or 0)

            remaining_transfer_credit = transfer_out_remaining_after_ips
            for tx in transfer_in_sbts:
                tx_amount = float(tx.amount_cash or 0)
                if tx.ref_id is not None and tx.ref_id in reversed_ref_ids:
                    # Partially or fully reversed: compute net remaining
                    reversed_amt = reversal_by_ref.get(tx.ref_id, tx_amount)
                    tx_remaining = max(0.0, round(tx_amount - reversed_amt, 2))
                else:
                    tx_remaining = round(tx_amount, 2)

                # Apply unaccounted outflow credit FIFO to safe_transfer items too
                if remaining_transfer_credit > 0.005 and tx_remaining > 0.005:
                    consumed = min(tx_remaining, remaining_transfer_credit)
                    tx_remaining = round(tx_remaining - consumed, 2)
                    remaining_transfer_credit = round(remaining_transfer_credit - consumed, 2)

                if tx_remaining <= 0.005:
                    continue
                pending.append({
                    'tx_id': f'transfer_{tx.id}',
                    'invoice_payment_id': None,
                    'invoice_id': None,
                    'invoice_number': None,
                    'amount': tx_remaining,
                    'date': tx.created_at.isoformat() if tx.created_at else None,
                    'type': 'safe_transfer',
                    'ref_id': tx.ref_id,
                    'note': 'تحويل من خزنة مقاصة أخرى',
                })
    except Exception:
        pass

    return jsonify({
        'clearing_safe_box_id': clearing_safe_box_id,
        'pending_count': len(pending),
        'due_amount': round(due_amount, 2),
        'tx_count_for_fee': tx_count_for_fee,
        'transactions': pending,
    }), 200


@api.route('/clearing/settlements/auto-run', methods=['POST'])
@require_permission('vouchers.create')
def run_auto_clearing_settlements_now():
    """Run the clearing auto-settlement scheduler immediately.

    This is intended for manual operational triggering and verification.
    The actual settlement logic remains centralized in the scheduler.
    """
    try:
        from clearing_settlement_scheduler import get_clearing_settlement_scheduler

        scheduler = get_clearing_settlement_scheduler(current_app._get_current_object())
        diag = scheduler.process_due_settlements()

        settled_count = diag.get('settled_count', 0)
        per_tx_count = diag.get('per_tx_settled_count', 0)
        enabled_methods = diag.get('enabled_methods', 0)
        skipped = diag.get('skipped', [])

        total_settled = settled_count + per_tx_count
        if total_settled > 0:
            message = f'تم إنشاء {total_settled} سند تسوية تلقائية'
        elif enabled_methods == 0:
            message = 'لا توجد وسائل دفع مفعّلة للتسوية التلقائية'
        else:
            message = 'لا توجد مستحقات مؤهلة للتسوية الآن'

        return jsonify({
            'success': True,
            'enabled_methods': int(enabled_methods),
            'settled_count': settled_count,
            'per_tx_settled_count': per_tx_count,
            'message': message,
            'skipped': skipped,
        }), 200
    except Exception as exc:
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': f'failed_to_run_auto_settlement: {exc}',
        }), 500


@require_permission('vouchers.create')
def create_bnpl_settlement():
    """Create a BNPL settlement voucher and update balances.

    Best practice flow:
    - Credit: BNPL receivable (gross)
    - Debit: Bank (net)
    - Debit: BNPL commission expense (fee)

    Body:
      - bnpl_safe_box_id: int (Tabby/Tamara safe box)
      - bank_safe_box_id: int (bank safe box)
      - gross_amount: float
      - fee_amount: float (optional, default 0)
      - settlement_date: ISO datetime/date (optional)
      - reference_number: str (optional)
      - created_by: str (optional)
      - fee_account_id: int (optional; if omitted uses 5113/5114 based on provider)
      - provider: 'tabby'|'tamara' (optional; if omitted inferred from BNPL account)
    """
    data = request.get_json(silent=True) or {}

    bnpl_safe_box_id = data.get('bnpl_safe_box_id') or data.get('from_safe_box_id')
    bank_safe_box_id = data.get('bank_safe_box_id') or data.get('to_safe_box_id')
    created_by = data.get('created_by', 'system')
    reference_number = data.get('reference_number')
    provider = (data.get('provider') or '').strip().lower() or None

    try:
        gross_amount = float(data.get('gross_amount') or data.get('amount') or 0.0)
        fee_amount = float(data.get('fee_amount') or data.get('fee') or 0.0)
    except (TypeError, ValueError):
        return jsonify({'error': 'invalid gross_amount/fee_amount'}), 400

    if not bnpl_safe_box_id or not bank_safe_box_id:
        return jsonify({'error': 'bnpl_safe_box_id and bank_safe_box_id are required'}), 400

    if gross_amount <= 0:
        return jsonify({'error': 'gross_amount must be > 0'}), 400

    if fee_amount < 0:
        return jsonify({'error': 'fee_amount must be >= 0'}), 400

    net_amount = round(gross_amount - fee_amount, 2)
    if net_amount < 0:
        return jsonify({'error': 'fee_amount cannot exceed gross_amount'}), 400

    # Parse settlement date
    settlement_date_raw = data.get('settlement_date') or data.get('date')
    settlement_dt = datetime.now()
    if settlement_date_raw:
        try:
            # Accept YYYY-MM-DD or full ISO
            if isinstance(settlement_date_raw, str) and len(settlement_date_raw) == 10:
                settlement_dt = datetime.fromisoformat(settlement_date_raw + 'T00:00:00')
            else:
                settlement_dt = datetime.fromisoformat(settlement_date_raw)
        except Exception:
            return jsonify({'error': 'invalid settlement_date'}), 400

    bnpl_safe_box = SafeBox.query.get(bnpl_safe_box_id)
    if not bnpl_safe_box or not bnpl_safe_box.is_active:
        return jsonify({'error': 'BNPL safe box not found or inactive'}), 404

    bank_safe_box = SafeBox.query.get(bank_safe_box_id)
    if not bank_safe_box or not bank_safe_box.is_active:
        return jsonify({'error': 'Bank safe box not found or inactive'}), 404

    # BNPL receivable safe can be represented as bank (legacy) or clearing (preferred)
    if (bnpl_safe_box.safe_type or '').strip().lower() not in ('bank', 'clearing'):
        return jsonify({'error': 'BNPL safe box must be of type bank or clearing'}), 400

    if (bank_safe_box.safe_type or '').strip().lower() != 'bank':
        return jsonify({'error': 'bank_safe_box must be of type bank'}), 400

    bnpl_account = bnpl_safe_box.account
    bank_account = bank_safe_box.account
    if not bnpl_account or not bank_account:
        return jsonify({'error': 'Safe box must be linked to an account'}), 400

    # Infer provider if missing
    if not provider:
        bank_name = (getattr(bnpl_account, 'bank_name', None) or getattr(bnpl_safe_box, 'bank_name', None) or '').lower()
        account_name = (getattr(bnpl_account, 'name', '') or '').lower()
        if 'tabby' in bank_name or 'تابي' in bank_name or 'tabby' in account_name or 'تابي' in account_name:
            provider = 'tabby'
        elif 'tamara' in bank_name or 'تمارا' in bank_name or 'tamara' in account_name or 'تمارا' in account_name:
            provider = 'tamara'

    # Resolve fee account
    fee_account = None
    fee_account_id = data.get('fee_account_id')
    if fee_amount > 0:
        if fee_account_id:
            fee_account = Account.query.get(fee_account_id)
            if not fee_account:
                return jsonify({'error': 'fee_account_id not found'}), 404
        else:
            if provider == 'tabby':
                fee_account = Account.query.filter_by(account_number='5113').first()
            elif provider == 'tamara':
                fee_account = Account.query.filter_by(account_number='5114').first()

        if not fee_account:
            return jsonify({
                'error': 'fee_account is required for fee_amount > 0',
                'hint': 'Provide fee_account_id or ensure accounts 5113/5114 exist'
            }), 400

    # Balance check: prevent settling more than receivable tracked in system
    bnpl_balance = float(getattr(bnpl_account, 'balance_cash', 0.0) or 0.0)
    if bnpl_balance < gross_amount:
        return jsonify({
            'error': 'BNPL balance is insufficient for settlement',
            'bnpl_balance': round(bnpl_balance, 2),
            'gross_amount': round(gross_amount, 2)
        }), 400

    # Create adjustment voucher + lines and a journal entry for audit.
    try:
        voucher_number = generate_voucher_number('adjustment', voucher_date=settlement_dt)

        provider_label = 'تابي' if provider == 'tabby' else ('تمارا' if provider == 'tamara' else 'BNPL')
        description = (
            f'تسوية {provider_label}: {bnpl_safe_box.name} → {bank_safe_box.name} '
            f'(إجمالي {gross_amount:.2f}، عمولة {fee_amount:.2f}، صافي {net_amount:.2f})'
        )

        voucher = Voucher(
            voucher_number=voucher_number,
            voucher_type='adjustment',
            date=settlement_dt,
            description=description,
            reference_type='bnpl_settlement',
            reference_number=reference_number,
            notes=(data.get('notes') or '').strip() or None,
            created_by=created_by,
            status='approved',
            approved_by=created_by,
            approved_at=datetime.now(),
            amount_cash=round(gross_amount, 2),
            amount_gold=0.0,
        )
        db.session.add(voucher)
        db.session.flush()

        lines = []
        if net_amount > 0:
            lines.append(VoucherAccountLine(
                voucher_id=voucher.id,
                account_id=bank_account.id,
                line_type='debit',
                amount_type='cash',
                amount=round(net_amount, 2),
                description=f'إيداع صافي تسوية {provider_label} إلى {bank_safe_box.name}',
            ))

        if fee_amount > 0:
            lines.append(VoucherAccountLine(
                voucher_id=voucher.id,
                account_id=fee_account.id,
                line_type='debit',
                amount_type='cash',
                amount=round(fee_amount, 2),
                description=f'عمولة {provider_label}',
            ))

        lines.append(VoucherAccountLine(
            voucher_id=voucher.id,
            account_id=bnpl_account.id,
            line_type='credit',
            amount_type='cash',
            amount=round(gross_amount, 2),
            description=f'إقفال مستحقات {provider_label}',
        ))

        for line in lines:
            db.session.add(line)

        db.session.flush()

        # Create journal entry for audit linkage (does not post balances)
        journal_entry = create_journal_entry_from_voucher(voucher)
        if journal_entry:
            voucher.journal_entry_id = journal_entry.id

        # Update balances immediately (system tracks balances outside posting)
        bnpl_account.update_balance(cash_amount=-gross_amount)
        bank_account.update_balance(cash_amount=net_amount)
        if fee_account:
            fee_account.update_balance(cash_amount=fee_amount)

        # Ledger: create SafeBoxTransaction rows for the safe-box-targeting lines.
        _append_safe_transactions_for_voucher(voucher, created_by=created_by)

        db.session.commit()

        return jsonify({
            'success': True,
            'voucher': voucher.to_dict(),
            'balances': {
                'bnpl_account_cash': round(float(getattr(bnpl_account, 'balance_cash', 0.0) or 0.0), 2),
                'bank_account_cash': round(float(getattr(bank_account, 'balance_cash', 0.0) or 0.0), 2),
                **({'fee_account_cash': round(float(getattr(fee_account, 'balance_cash', 0.0) or 0.0), 2)} if fee_account else {}),
            }
        }), 201

    except Exception as exc:
        db.session.rollback()
        return jsonify({'error': f'Failed to create BNPL settlement: {str(exc)}'}), 500


# ============================================================================
# Weight Closing Helpers & Office Reservations
# ============================================================================


def _upsert_weight_closing_order(invoice: Invoice, close_price_per_gram: float, settings=None):
    if not invoice:
        raise ValueError('invoice is required')

    settings = settings or _load_weight_closing_settings()
    main_karat = settings.get('main_karat') or get_main_karat()
    close_price = _coerce_float(close_price_per_gram, 0.0)
    total_weight_main_karat = round(_invoice_weight_in_main_karat(invoice), 6)
    total_cash_value = round(total_weight_main_karat * close_price, 2)

    order = WeightClosingOrder.query.filter_by(invoice_id=invoice.id).first()
    if order:
        order.main_karat = main_karat
        order.close_price_per_gram = close_price
        order.price_source = settings.get('price_source', order.price_source)
        order.gold_value_cash = total_cash_value
        order.total_cash_value = total_cash_value
        order.total_weight_main_karat = total_weight_main_karat
        order.remaining_weight_main_karat = max(
            total_weight_main_karat - (order.executed_weight_main_karat or 0.0),
            0.0,
        )
    else:
        order = WeightClosingOrder(
            invoice_id=invoice.id,
            order_number=_generate_weight_closing_order_number(settings.get('order_number_prefix', 'WCO')),
            status='open',
            main_karat=main_karat,
            price_source=settings.get('price_source', 'manual'),
            close_price_per_gram=close_price,
            gold_value_cash=total_cash_value,
            total_cash_value=total_cash_value,
            total_weight_main_karat=total_weight_main_karat,
            executed_weight_main_karat=0.0,
            remaining_weight_main_karat=total_weight_main_karat,
        )
        db.session.add(order)
        db.session.flush()

    invoice.weight_closing_status = order.status
    invoice.weight_closing_main_karat = main_karat
    invoice.weight_closing_total_weight = total_weight_main_karat
    invoice.weight_closing_executed_weight = order.executed_weight_main_karat or 0.0
    invoice.weight_closing_remaining_weight = order.remaining_weight_main_karat or 0.0
    invoice.weight_closing_close_price = close_price
    invoice.weight_closing_order_number = order.order_number
    invoice.weight_closing_price_source = order.price_source
    db.session.add(invoice)
    db.session.flush()
    return order


def _auto_consume_weight_closing(
    source_invoice_id: int = None,
    *,
    weight_override=None,
    price_per_gram=None,
    cash_amount=None,
    execution_type: str = 'purchase_scrap',
    journal_entry_id=None,
    notes=None,
):
    invoice = Invoice.query.get(source_invoice_id) if source_invoice_id else None

    requested_weight = _coerce_float(weight_override, None)
    execution_price = _coerce_float(price_per_gram, None)

    if requested_weight is None:
        if cash_amount is not None:
            if execution_price is None or execution_price <= 0:
                price_snapshot = get_current_gold_price()
                execution_price = price_snapshot.get('price_per_gram_24k', 0.0)
            grams_24k = (cash_amount or 0.0) / execution_price if execution_price else 0.0
            requested_weight = convert_to_main_karat(grams_24k, 24)
        elif invoice:
            requested_weight = _invoice_weight_in_main_karat(invoice)
        else:
            requested_weight = 0.0

    requested_weight = max(requested_weight or 0.0, 0.0)

    summary = {
        'weight_requested': requested_weight,
        'weight_consumed': 0.0,
        'executions_created': 0,
        'orders_updated': [],
        'orders_closed': [],
        'difference_value_total': 0.0,
        'difference_weight_total': 0.0,
        'cash_requested': round(cash_amount or 0.0, 2),
        'cash_consumed': 0.0,
    }

    if requested_weight <= 0:
        return summary

    orders = (
        WeightClosingOrder.query.filter(WeightClosingOrder.status.in_(['open', 'partially_closed']))
        .order_by(WeightClosingOrder.created_at.asc())
        .all()
    )

    remaining = requested_weight
    cash_spent = 0.0

    for order in orders:
        if remaining <= 0:
            break

        available = max((order.total_weight_main_karat or 0.0) - (order.executed_weight_main_karat or 0.0), 0.0)
        if available <= 0:
            order.status = 'closed'
            summary['orders_closed'].append(order.id)
            continue

        chunk = min(available, remaining)
        exec_price = execution_price if execution_price is not None else order.close_price_per_gram
        exec_price = _coerce_float(exec_price, 0.0)

        # إنشاء قيد محاسبي للتنفيذ إذا كان هناك journal_entry_id
        # ملاحظة: تنفيذ مكاتب التسكير (office_reservation) يجب ألا يمر على حساب الجسر.
        if journal_entry_id and invoice and execution_type != 'office_reservation':
            karat_line = InvoiceKaratLine.query.filter_by(invoice_id=invoice.id).first()
            execution_karat = karat_line.karat if karat_line else get_main_karat()

            # نوع الذهب يُحدَّد من فاتورة البيع الأصلية لهذا الأمر (order)، لا من
            # الفاتورة المُسوِّية — فهو ما يحدد أي مخزون (جديد/كسر) يُستهلَك فعلياً.
            _order_gold_kind = order.invoice.gold_type if order.invoice else 'new'
            inventory_account_id = _get_inventory_account_by_karat(execution_karat, kind=_order_gold_kind)

            bridge_account_id = (
                Account.query.filter_by(account_number='1710').first()
                or Account.query.filter_by(account_number='1290').first()
            )
            if not bridge_account_id:
                bridge_account_id = Account.query.filter_by(name='جسر مشتريات الكسر والتسكير').first()
            bridge_id = bridge_account_id.id if bridge_account_id else None

            if bridge_id:
                weight_in_karat = convert_from_main_karat(chunk, execution_karat)

                karat_debit = f'debit_{execution_karat}k'
                karat_credit = f'credit_{execution_karat}k'

                # الوزن يجب أن يذهب لحساب المذكرة (7xxxx)، لا للحساب المالي (1xxx).
                inventory_memo_acc_id = None
                try:
                    inv_obj = Account.query.get(inventory_account_id)
                    if inv_obj and inv_obj.memo_account_id:
                        inventory_memo_acc_id = inv_obj.memo_account_id
                except Exception:
                    inventory_memo_acc_id = None
                if not inventory_memo_acc_id:
                    inventory_memo_acc_id = get_account_id_by_number('7521')

                if inventory_memo_acc_id:
                    create_dual_journal_entry(
                        journal_entry_id=journal_entry_id,
                        account_id=inventory_memo_acc_id,
                        description=f'تنفيذ تسكير عيار {execution_karat}',
                        **{karat_debit: weight_in_karat}
                    )
                else:
                    print(f"⚠️ Skipping weight debit in weight closing: no memo account for inventory {inventory_account_id}")

                create_dual_journal_entry(
                    journal_entry_id=journal_entry_id,
                    account_id=bridge_id,
                    description=f'إخراج من جسر التسكير عيار {execution_karat}',
                    **{karat_credit: weight_in_karat}
                )

        chunk_24k = convert_from_main_karat(chunk, 24)
        chunk_cash_value = round(chunk_24k * exec_price, 2) if exec_price else 0.0
        cash_spent += chunk_cash_value

        # ─── قيد تكلفة المبيعات (COGS): د/521 × ه/مخزون مالي ────────────────────
        # يُسجَّل عند كل تنفيذ تسكير (ما عدا "expense" و"office_reservation").
        # office_reservation: الوزن يُتابَع عبر خزينة المكتب، لا عبر COGS مباشرة.
        if journal_entry_id and chunk_cash_value > 0 and execution_type not in ('expense', 'office_reservation'):
            _cogs_account = Account.query.filter_by(account_number='521').first()
            if _cogs_account:
                _karat_ln = (
                    InvoiceKaratLine.query.filter_by(invoice_id=invoice.id).first()
                    if invoice else None
                )
                _exec_karat_cogs = int(_karat_ln.karat) if _karat_ln else get_main_karat()
                _order_gold_kind_cogs = order.invoice.gold_type if order.invoice else 'new'
                _inv_fin_id = _get_inventory_account_by_karat(_exec_karat_cogs, kind=_order_gold_kind_cogs)
                if _inv_fin_id:
                    create_dual_journal_entry(
                        journal_entry_id=journal_entry_id,
                        account_id=_cogs_account.id,
                        cash_debit=chunk_cash_value,
                        description=(
                            f'تكلفة مبيعات ذهب – {round(chunk, 4)} غ عيار {_exec_karat_cogs}'
                        ),
                    )
                    create_dual_journal_entry(
                        journal_entry_id=journal_entry_id,
                        account_id=_inv_fin_id,
                        cash_credit=chunk_cash_value,
                        description=(
                            f'إخراج من مخزون مالي لتكلفة المبيعات – عيار {_exec_karat_cogs}'
                        ),
                    )
        # ─────────────────────────────────────────────────────────────────────────

        difference_value = 0.0
        difference_weight = 0.0
        reference_price = order.close_price_per_gram or 0.0

        if exec_price and reference_price:
            difference_value = round((exec_price - reference_price) * chunk_24k, 2)
            if reference_price > 0:
                baseline_grams_24k = chunk_cash_value / reference_price if reference_price else 0.0
                baseline_weight_main = convert_to_main_karat(baseline_grams_24k, 24)
                difference_weight = round(baseline_weight_main - chunk, 6)

        execution = WeightClosingExecution(
            order_id=order.id,
            source_invoice_id=invoice.id if invoice else None,
            execution_type=execution_type,
            weight_main_karat=chunk,
            price_per_gram=exec_price,
            difference_value=difference_value,
            difference_weight=difference_weight,
            journal_entry_id=journal_entry_id,
            notes=notes,
        )
        db.session.add(execution)

        order.executed_weight_main_karat = (order.executed_weight_main_karat or 0.0) + chunk
        order.remaining_weight_main_karat = max((order.total_weight_main_karat or 0.0) - order.executed_weight_main_karat, 0.0)
        if order.remaining_weight_main_karat <= 0.0001:
            order.status = 'closed'
            summary['orders_closed'].append(order.id)
        else:
            order.status = 'partially_closed'

        order.invoice.weight_closing_executed_weight = order.executed_weight_main_karat
        order.invoice.weight_closing_remaining_weight = order.remaining_weight_main_karat
        order.invoice.weight_closing_status = order.status

        remaining -= chunk
        summary['executions_created'] += 1
        summary['weight_consumed'] += chunk
        summary['difference_value_total'] += difference_value
        summary['difference_weight_total'] += difference_weight
        summary['orders_updated'].append(order.id)

    summary['cash_consumed'] = round(cash_spent, 2)
    db.session.flush()
    return summary


@api.route('/weight-closing/cash-settlement', methods=['POST'])
@require_permission('journal.post')
def create_weight_closing_cash_settlement():
    """Consume open weight-closing orders using a cash amount and live gold price."""
    data = request.get_json(silent=True) or {}
    cash_amount = _coerce_float(data.get('cash_amount'))
    if cash_amount <= 0:
        return jsonify({'error': 'cash_amount must be greater than zero'}), 400

    execution_price = _coerce_float(data.get('price_per_gram'), None)
    if execution_price is None or execution_price <= 0:
        price_snapshot = get_current_gold_price()
        execution_price = price_snapshot.get('price_per_gram_24k', 0.0)

    if execution_price <= 0:
        return jsonify({'error': 'Unable to determine gold price per gram'}), 400

    summary = _auto_consume_weight_closing(
        data.get('source_invoice_id'),
        price_per_gram=execution_price,
        cash_amount=cash_amount,
        execution_type=data.get('execution_type', 'expense'),
        journal_entry_id=data.get('journal_entry_id'),
        notes=data.get('notes'),
    )
    summary['price_per_gram'] = execution_price
    return jsonify(summary)


@api.route('/weight-closing/execute-profile', methods=['POST'])
@require_permission('journal.post')
def execute_weight_closing_profile():
    data = request.get_json(silent=True) or {}
    profile_key = data.get('profile_key')
    if not profile_key:
        return jsonify({'error': 'profile_key مطلوب'}), 400

    ensure_weight_closing_support_accounts()

    try:
        profile = resolve_weight_profile(profile_key)
    except ValueError as exc:
        return jsonify({'error': str(exc)}), 400

    financial_account = profile.get('financial_account')
    if not financial_account:
        return jsonify({'error': 'الحساب المالي للبروفايل غير متوفر'}), 400

    settings = _load_weight_closing_settings()

    def _resolve_cash_account_from_safebox_id(safe_box_id: int):
        if not safe_box_id or safe_box_id <= 0:
            return None
        safe_box = SafeBox.query.get(int(safe_box_id))
        if not safe_box or not safe_box.is_active:
            return None
        if (safe_box.safe_type or '').strip().lower() not in {'cash', 'bank'}:
            return None
        return Account.query.get(safe_box.account_id) if safe_box.account_id else None

    # SafeBox selection chain:
    # 1) explicit override in request payload
    # 2) supplier.default_safe_box_id (when supplier_id provided)
    # 3) settings.weight_closing_settings.cash_safe_box_id
    # 4) legacy settings.cash_account_id (id or account_number-like)
    supplier = None
    supplier_id = data.get('supplier_id')
    try:
        supplier_id_int = int(supplier_id) if supplier_id not in (None, '', False) else None
    except Exception:
        supplier_id_int = None
    if supplier_id_int:
        supplier = Supplier.query.get(supplier_id_int)

    override_safe_box_id = data.get('cash_safe_box_id')
    try:
        override_safe_box_id_int = int(override_safe_box_id) if override_safe_box_id not in (None, '', False) else None
    except Exception:
        override_safe_box_id_int = None

    chosen_cash_safe_box_id = None
    cash_account = None
    if override_safe_box_id_int:
        cash_account = _resolve_cash_account_from_safebox_id(override_safe_box_id_int)
        if not cash_account:
            return jsonify({
                'error': 'الخزينة النقدية المختارة غير صالحة',
                'details': f"cash_safe_box_id={override_safe_box_id_int}",
            }), 400
        chosen_cash_safe_box_id = override_safe_box_id_int
    else:
        supplier_safe_box_id = getattr(supplier, 'default_safe_box_id', None) if supplier else None
        if supplier_safe_box_id:
            cash_account = _resolve_cash_account_from_safebox_id(int(supplier_safe_box_id))
            if cash_account:
                chosen_cash_safe_box_id = int(supplier_safe_box_id)

        if not cash_account:
            settings_safe_box_id = settings.get('cash_safe_box_id')
            if settings_safe_box_id:
                cash_account = _resolve_cash_account_from_safebox_id(int(settings_safe_box_id))
                if cash_account:
                    chosen_cash_safe_box_id = int(settings_safe_box_id)

        if not cash_account:
            cash_account_setting = settings.get('cash_account_id', 1100)
            cash_account = _resolve_account_from_id_or_number(cash_account_setting)

    if not cash_account:
        return jsonify({
            'error': 'تعذر تحديد حساب الصندوق/البنك للتسوية',
            'details': {
                'supplier_id': supplier_id_int,
                'supplier_default_safe_box_id': getattr(supplier, 'default_safe_box_id', None) if supplier else None,
                'settings_cash_safe_box_id': settings.get('cash_safe_box_id'),
                'cash_account_id': settings.get('cash_account_id', 1100),
            },
        }), 400

    price_per_gram = _coerce_float(data.get('price_per_gram'), None)
    price_strategy = profile['meta'].get('price_strategy', 'manual')
    if price_strategy in ('live_or_manual', 'live_only'):
        if price_per_gram is None or price_per_gram <= 0:
            snapshot = get_current_gold_price()
            price_per_gram = snapshot.get('price_per_gram_24k', 0.0)
    if price_per_gram is None or price_per_gram <= 0:
        return jsonify({'error': 'price_per_gram غير صالح'}), 400

    cash_amount = _coerce_float(data.get('cash_amount'))
    weight_main = _coerce_float(data.get('weight_main_karat'))
    if weight_main <= 0 and data.get('weight_grams'):
        karat = int(data.get('karat') or get_main_karat() or 21)
        weight_main = convert_to_main_karat(_coerce_float(data.get('weight_grams')), karat)

    if cash_amount <= 0 and weight_main > 0:
        grams_24k = convert_from_main_karat(weight_main, 24)
        cash_amount = round(grams_24k * price_per_gram, 2)

    if weight_main <= 0 and cash_amount > 0 and price_per_gram > 0:
        grams_24k = cash_amount / price_per_gram
        weight_main = convert_to_main_karat(grams_24k, 24)

    if profile['meta'].get('requires_cash_amount') and cash_amount <= 0:
        return jsonify({'error': 'هذا البروفايل يتطلب cash_amount أكبر من صفر'}), 400
    if profile['meta'].get('requires_weight') and weight_main <= 0:
        return jsonify({'error': 'هذا البروفايل يتطلب إدخال وزن'}), 400

    now = datetime.now()
    description = data.get('notes') or profile['meta'].get('display_name') or profile_key
    journal_entry = JournalEntry(
        entry_number=_generate_journal_entry_number('WXP'),
        date=now,
        description=f'تنفيذ بروفايل {profile_key}: {description}',
        reference_type='weight_profile',
        reference_id=None,
        is_posted=True,
        posted_at=now,
        posted_by='system',
    )
    db.session.add(journal_entry)
    db.session.flush()

    if cash_amount > 0:
        create_dual_journal_entry(
            journal_entry_id=journal_entry.id,
            account_id=financial_account.id,
            cash_debit=cash_amount,
            description=description,
        )
        create_dual_journal_entry(
            journal_entry_id=journal_entry.id,
            account_id=cash_account.id,
            cash_credit=cash_amount,
            description=description,
        )

    memo_debit_account = Account.query.get(financial_account.memo_account_id) if financial_account.memo_account_id else None
    default_memo_cash_account = Account.query.filter_by(account_number='71100').first()
    memo_credit_account = default_memo_cash_account
    if memo_debit_account and memo_credit_account and weight_main > 0:
        _record_memo_weight_transfer(
            journal_entry.id,
            debit_account_id=memo_debit_account.id,
            credit_account_id=memo_credit_account.id,
            weight_main_karat=weight_main,
        )

    verify_dual_balance(journal_entry.id)

    consumption = _auto_consume_weight_closing(
        weight_override=weight_main if weight_main > 0 else None,
        price_per_gram=price_per_gram,
        cash_amount=cash_amount,
        execution_type=profile['meta'].get('execution_type', 'expense'),
        journal_entry_id=journal_entry.id,
        notes=description,
    )
    consumption['price_per_gram'] = price_per_gram

    db.session.commit()

    return jsonify(
        {
            'profile': {
                'key': profile_key,
                'display_name': profile['meta'].get('display_name', profile_key),
            },
            'cash_safe_box_id': chosen_cash_safe_box_id,
            'cash_amount': cash_amount,
            'weight_main_karat': weight_main,
            'price_per_gram': price_per_gram,
            'journal_entry': {
                'id': journal_entry.id,
                'entry_number': journal_entry.entry_number,
                'date': journal_entry.date.isoformat(),
            },
            'weight_consumption': consumption,
        }
    )


def _serialize_office_reservation(reservation: OfficeReservation):
    payload = reservation.to_dict()
    payload['office'] = reservation.office.to_dict() if reservation.office else None
    return payload


@api.route('/office-reservations', methods=['GET'])
@require_permission('journal.post')
def list_office_reservations():
    query = OfficeReservation.query.options(joinedload(OfficeReservation.office))

    office_id = request.args.get('office_id', type=int)
    status = request.args.get('status')
    payment_status = request.args.get('payment_status')
    date_from = request.args.get('date_from')
    date_to = request.args.get('date_to')

    if office_id:
        query = query.filter(OfficeReservation.office_id == office_id)
    if status:
        query = query.filter(OfficeReservation.status == status)
    if payment_status:
        query = query.filter(OfficeReservation.payment_status == payment_status)
    if date_from:
        try:
            query = query.filter(OfficeReservation.reservation_date >= datetime.fromisoformat(date_from))
        except ValueError:
            return jsonify({'error': 'date_from must be ISO format'}), 400
    if date_to:
        try:
            query = query.filter(OfficeReservation.reservation_date <= datetime.fromisoformat(date_to))
        except ValueError:
            return jsonify({'error': 'date_to must be ISO format'}), 400

    order_by = request.args.get('order_by', 'reservation_date')
    order_direction = request.args.get('order_direction', 'desc').lower()
    order_map = {
        'reservation_date': OfficeReservation.reservation_date,
        'total_amount': OfficeReservation.total_amount,
        'paid_amount': OfficeReservation.paid_amount,
        'weight_main_karat': OfficeReservation.weight_main_karat,
    }
    sort_column = order_map.get(order_by, OfficeReservation.reservation_date)
    if order_direction == 'asc':
        query = query.order_by(sort_column.asc())
    else:
        query = query.order_by(sort_column.desc())

    limit = request.args.get('limit', type=int)
    page = request.args.get('page', type=int) or 1
    per_page = request.args.get('per_page', type=int) or limit or 25

    pagination = query.paginate(page=page, per_page=per_page, error_out=False)
    data = [_serialize_office_reservation(reservation) for reservation in pagination.items]

    return jsonify(
        {
            'data': data,
            'pagination': {
                'page': pagination.page,
                'per_page': pagination.per_page,
                'total': pagination.total,
                'pages': pagination.pages,
            },
        }
    )


@api.route('/office-reservations/<int:reservation_id>', methods=['GET'])
@require_permission('journal.post')
def get_office_reservation(reservation_id):
    reservation = OfficeReservation.query.options(joinedload(OfficeReservation.office)).get(reservation_id)
    if not reservation:
        return jsonify({'error': 'الحجز غير موجود'}), 404
    return jsonify(_serialize_office_reservation(reservation))


@api.route('/office-reservations', methods=['POST'])
@require_permission('journal.post')
def create_office_reservation():
    data = request.get_json(silent=True) or {}
    office_id = data.get('office_id')
    if not office_id:
        return jsonify({'error': 'office_id مطلوب'}), 400

    office = Office.query.get(office_id)
    if not office:
        return jsonify({'error': 'المكتب غير موجود'}), 404
    ensure_office_account(office)
    if not office.account_category_id:
        return jsonify({'error': 'المكتب لا يملك حساباً محاسبياً مرتبطاً'}), 400

    weight_grams = _coerce_float(data.get('weight') or data.get('weight_grams'))
    if weight_grams <= 0:
        return jsonify({'error': 'الوزن يجب أن يكون أكبر من صفر'}), 400

    price_per_gram = _coerce_float(data.get('price_per_gram'))
    if price_per_gram <= 0:
        return jsonify({'error': 'price_per_gram مطلوب'}), 400

    execution_price = _coerce_float(data.get('execution_price_per_gram'), price_per_gram)
    karat = int(data.get('karat') or get_main_karat())
    if karat not in (18, 21, 22, 24):
        return jsonify({'error': 'karat غير مدعوم. القيم المسموحة: 18, 21, 22, 24'}), 400
    weight_main_karat = round(convert_to_main_karat(weight_grams, karat), 6)
    total_amount = _coerce_float(data.get('total_amount'), round(weight_grams * price_per_gram, 2))

    # Important: treat explicit 0 as 0 (do NOT fall back to total_amount).
    if 'paid_amount' in data:
        paid_amount = _coerce_float(data.get('paid_amount'), 0.0)
    else:
        paid_amount = float(total_amount)

    payment_status = data.get('payment_status')
    if not payment_status:
        if paid_amount >= total_amount and total_amount > 0:
            payment_status = 'paid'
        elif paid_amount > 0:
            payment_status = 'partial'
        else:
            payment_status = 'pending'

    settings = _load_weight_closing_settings()

    try:
        reservation_date = datetime.fromisoformat(data.get('reservation_date')) if data.get('reservation_date') else datetime.now()
    except ValueError:
        return jsonify({'error': 'reservation_date يجب أن يكون بصيغة ISO'}), 400

    # ── guard: duplicate reservation within 24 hours ─────────────────────────
    if not data.get('force', False):
        cutoff = datetime.now() - timedelta(hours=24)
        dup = OfficeReservation.query.filter(
            OfficeReservation.office_id == office_id,
            OfficeReservation.weight_grams == weight_grams,
            OfficeReservation.price_per_gram == price_per_gram,
            OfficeReservation.status.in_(['approved', 'completed']),
            OfficeReservation.created_at >= cutoff,
        ).first()
        if dup:
            return jsonify({
                'error': 'duplicate_reservation',
                'message': (
                    f'يوجد حجز مشابه لنفس المكتب بنفس الوزن والسعر خلال آخر 24 ساعة '
                    f'(رقم الحجز: {dup.reservation_code}). '
                    'إذا كان هذا مقصوداً أرسل "force": true في الطلب.'
                ),
                'existing_reservation_id': dup.id,
                'existing_reservation_code': dup.reservation_code,
            }), 409

    try:
        supplier = ensure_office_supplier(office)
        supplier_override = data.get('supplier_id')
        if supplier_override and supplier_override != supplier.id:
            return jsonify({'error': 'لا يمكن تحديد مورد مختلف عن مورد المكتب'}), 400
        reservation = OfficeReservation(
            office_id=office.id,
            reservation_code=_generate_reservation_code(settings.get('reservation_code_prefix', 'RES')),
            reservation_date=reservation_date,
            karat=karat,
            weight_grams=weight_grams,
            weight_main_karat=weight_main_karat,
            price_per_gram=price_per_gram,
            execution_price_per_gram=execution_price,
            total_amount=total_amount,
            paid_amount=paid_amount,
            payment_status=payment_status,
            # Auto-approve on save: no separate approval step.
            status='approved',
            contact_person=data.get('contact_person'),
            contact_phone=data.get('contact_phone'),
            notes=data.get('notes'),
            weight_consumed_main_karat=0.0,
            weight_remaining_main_karat=weight_main_karat,
            purchase_invoice_id=None,
        )
        db.session.add(reservation)
        db.session.flush()
        voucher = None
        if paid_amount > 0:
            # Create a real Payment Voucher (سند صرف) for the paid amount.
            # This reflects money leaving the safe immediately, even if the gold is not received yet.
            resolved_payment_safe_box_id = (
                _normalize_fk_ref(data.get('safe_box_id'))
                or _normalize_fk_ref(data.get('cash_safe_box_id'))
                or _normalize_fk_ref(settings.get('cash_safe_box_id'))
            )

            safe_box = None
            cash_account = None
            if resolved_payment_safe_box_id is not None:
                safe_box = SafeBox.query.get(int(resolved_payment_safe_box_id))
                if not safe_box or not getattr(safe_box, 'is_active', True):
                    db.session.rollback()
                    return jsonify({'error': 'الخزينة المحددة غير موجودة/غير فعالة'}), 400
                if safe_box.safe_type not in ('cash', 'bank'):
                    db.session.rollback()
                    return jsonify({'error': 'الخزينة المحددة ليست خزينة نقد/بنك'}), 400
                cash_account = Account.query.get(safe_box.account_id)
                if not cash_account:
                    db.session.rollback()
                    return jsonify({'error': 'لا يمكن تسجيل الدفعة لأن حساب الخزينة غير موجود'}), 400
            else:
                # Backward-compatible fallback: allow posting against the configured cash account number/id.
                cash_account_setting = settings.get('cash_account_id', 1100)
                cash_account = _resolve_account_from_id_or_number(cash_account_setting)
                if not cash_account:
                    db.session.rollback()
                    return jsonify({'error': 'لا يمكن تسجيل الدفعة لأن حساب الصندوق غير موجود/غير مضبوط'}), 400

            voucher_number = generate_voucher_number('payment', voucher_date=reservation_date)
            voucher = Voucher(
                voucher_number=voucher_number,
                voucher_type='payment',
                date=reservation_date,
                party_type='supplier',
                supplier_id=supplier.id,
                description=f'عربون/دفعة حجز مكتب {office.name} ({reservation.reservation_code})',
                reference_type='office_reservation',
                reference_id=reservation.id,
                reference_number=str(reservation.reservation_code),
                created_by=str(data.get('created_by') or 'system'),
                status='approved',
                approved_by=str(data.get('created_by') or 'system'),
                approved_at=datetime.now(),
                amount_cash=round(float(paid_amount), 2),
                amount_gold=0.0,
            )
            db.session.add(voucher)
            db.session.flush()

            db.session.add(
                VoucherAccountLine(
                    voucher_id=voucher.id,
                    account_id=office.account_category_id,
                    line_type='debit',
                    amount_type='cash',
                    amount=round(float(paid_amount), 2),
                    description='دفعة حجز مكتب (مدين)',
                )
            )
            db.session.add(
                VoucherAccountLine(
                    voucher_id=voucher.id,
                    account_id=cash_account.id,
                    line_type='credit',
                    amount_type='cash',
                    amount=round(float(paid_amount), 2),
                    description='خروج نقدية من الصندوق (دائن)',
                )
            )
            db.session.flush()

            voucher_entry = create_journal_entry_from_voucher(voucher)
            if voucher_entry:
                voucher.journal_entry_id = voucher_entry.id
            _append_safe_transactions_for_voucher(voucher, created_by=voucher.created_by)

        # ── قيد الإنشاء الوزني: ذهب يغادر المخزون إلى المكتب ───────────────
        # يُسجَّل دائماً عند إنشاء الحجز بغض النظر عن حالة الدفع.
        # Dr. حساب وزني المكتب (مفكرة account_category_id) / Cr. مخزون كسر وزني (71310)
        #
        # NOTE (2026-06-23): كان هذا يحلّ الحساب عبر supplier.default_safe_box.account_id
        # -- مسار مستقل تماماً عن الجانب النقدي (الذي يستخدم office.account_category_id
        # مباشرة)، فينتج حسابين مختلفين لنفس المكتب (شوهد فعلياً: نقدي->1072،
        # وزني->1074، بينما 1072.memo_account_id=1213 الحساب الرسمي لم يُستخدَم
        # إطلاقاً). الإصلاح: استخدام نفس سلسلة المرجع account_category_id ->
        # memo_account_id المعتمدة في كل مكان آخر بالنظام (32 موضعاً في هذا
        # الملف)، مع الإبقاء على المسار القديم كـfallback فقط لمكتب لم يُضبط
        # له memo_account_id بعد، لا كمسار أساسي.
        _office_weight_acc_id = None
        try:
            _office_financial_acc = getattr(office, 'account_category', None)
            if _office_financial_acc and getattr(_office_financial_acc, 'memo_account_id', None):
                _office_weight_acc_id = _office_financial_acc.memo_account_id
        except Exception:
            pass

        if not _office_weight_acc_id:
            try:
                _gold_safe = getattr(supplier, 'default_safe_box', None)
                if _gold_safe and getattr(_gold_safe, 'safe_type', None) == 'gold':
                    _office_weight_acc_id = getattr(_gold_safe, 'account_id', None)
            except Exception:
                pass

        _inv_weight_acc = Account.query.filter_by(account_number='71310').first()
        _inv_weight_acc_id = _inv_weight_acc.id if _inv_weight_acc else None

        if _office_weight_acc_id and _inv_weight_acc_id and weight_grams > 0:
            _wgt_entry = JournalEntry(
                entry_number=_generate_journal_entry_number('WGT'),
                date=reservation_date,
                description=f'إرسال ذهب للحجز ({reservation.reservation_code}) - مكتب {office.name}',
                reference_type='office_reservation',
                reference_id=reservation.id,
                is_posted=True,
                posted_at=reservation_date,
                posted_by=str(data.get('created_by') or 'system'),
            )
            db.session.add(_wgt_entry)
            db.session.flush()

            _k_dr = f'debit_{karat}k'
            _k_cr = f'credit_{karat}k'
            db.session.add(JournalEntryLine(
                journal_entry_id=_wgt_entry.id,
                account_id=_office_weight_acc_id,
                description=f'ذهب بحيازة مكتب التسكير عيار {karat}',
                **{_k_dr: weight_grams},
            ))
            db.session.add(JournalEntryLine(
                journal_entry_id=_wgt_entry.id,
                account_id=_inv_weight_acc_id,
                description=f'خروج ذهب كسر للتسكير عيار {karat}',
                **{_k_cr: weight_grams},
            ))
            db.session.flush()

            # Mirror onto SafeBoxTransaction -- this entry is_posted=True
            # already, but without this the office's gold safe-box card
            # (and the transfer-between-safes availability check) never
            # see this inflow; they read SafeBoxTransaction, not the GL.
            try:
                _rebuild_safe_box_transactions_for_journal_entry(
                    _wgt_entry,
                    [l for l in _wgt_entry.lines if not getattr(l, 'is_deleted', False)],
                    created_by=str(data.get('created_by') or 'system'),
                )
            except Exception:
                pass

        office.total_reservations = (office.total_reservations or 0) + 1
        office.total_weight_purchased = (office.total_weight_purchased or 0.0) + weight_main_karat
        office.total_amount_paid = (office.total_amount_paid or 0.0) + paid_amount
        db.session.add(office)

        db.session.commit()

        response = _serialize_office_reservation(reservation)
        response['purchase_invoice_id'] = reservation.purchase_invoice_id
        # Echo payment safe box (if provided via request or settings) for UI/debugging.
        payment_sb = _normalize_fk_ref(data.get('safe_box_id')) or _normalize_fk_ref(data.get('cash_safe_box_id'))
        if payment_sb is not None:
            response['payment_safe_box_id'] = int(payment_sb)

        # Include voucher info (if any) so UI/support can trace the payment.
        try:
            if voucher is not None:
                response['payment_voucher_id'] = int(voucher.id)
                response['payment_voucher_number'] = str(voucher.voucher_number)
        except Exception:
            pass
        return jsonify(response), 201

    except Exception as exc:
        db.session.rollback()
        print(f"❌ Failed to create office reservation: {exc}")
        return jsonify({'error': f'فشل إنشاء الحجز: {exc}'}), 500


@api.route('/office-reservations/<int:reservation_id>/settle', methods=['POST'])
@require_permission('journal.post')
def settle_office_reservation(reservation_id: int):
    """Convert an office reservation (fixing/booking) into a purchase invoice at execution time.

    Behavior:
    - Creates the purchase invoice + karat line.
    - Creates the gold journal entry (bridge vs office) and consumes weight closing orders.
    - Links any prior payment vouchers that referenced the reservation to the created invoice.
    """
    reservation = OfficeReservation.query.get(reservation_id)
    if not reservation:
        return jsonify({'error': 'الحجز غير موجود'}), 404

    if reservation.purchase_invoice_id:
        # Already settled.
        return jsonify(_serialize_office_reservation(reservation)), 200

    data = request.get_json(silent=True) or {}

    office = Office.query.get(reservation.office_id)
    if not office:
        return jsonify({'error': 'المكتب غير موجود'}), 404
    ensure_office_account(office)
    if not office.account_category_id:
        return jsonify({'error': 'المكتب لا يملك حساباً محاسبياً مرتبطاً'}), 400

    supplier = ensure_office_supplier(office)

    try:
        settlement_date = (
            datetime.fromisoformat(data.get('settlement_date'))
            if data.get('settlement_date')
            else datetime.now()
        )
    except ValueError:
        return jsonify({'error': 'settlement_date يجب أن يكون بصيغة ISO'}), 400

    execution_price = _coerce_float(
        data.get('execution_price_per_gram'),
        _coerce_float(getattr(reservation, 'execution_price_per_gram', None), _coerce_float(reservation.price_per_gram, 0.0)),
    )
    if execution_price <= 0:
        return jsonify({'error': 'execution_price_per_gram غير صالح'}), 400

    settings = _load_weight_closing_settings()

    try:
        legacy_supplier_purchase = 'شراء' + ' من ' + 'مورد'
        next_invoice_type_id = _next_invoice_type_id(['شراء', legacy_supplier_purchase])

        total_amount = float(getattr(reservation, 'total_amount', 0.0) or 0.0)
        paid_amount = float(getattr(reservation, 'paid_amount', 0.0) or 0.0)
        if total_amount <= 0:
            total_amount = round(float(reservation.weight_grams or 0.0) * float(reservation.price_per_gram or 0.0), 2)

        invoice_status = 'unpaid'
        if paid_amount >= total_amount and total_amount > 0:
            invoice_status = 'paid'
        elif paid_amount > 0:
            invoice_status = 'partially_paid'

        purchase_invoice = Invoice(
            invoice_type_id=next_invoice_type_id,
            supplier_id=supplier.id,
            office_id=office.id,
            date=settlement_date,
            total=total_amount,
            invoice_type='شراء',
            status=invoice_status,
            total_weight=float(reservation.weight_main_karat or 0.0),
            gold_subtotal=total_amount,
            wage_subtotal=0.0,
            gold_tax_total=0.0,
            wage_tax_total=0.0,
            amount_paid=paid_amount,
            gold_type='scrap',
        )
        db.session.add(purchase_invoice)
        db.session.flush()

        db.session.add(
            InvoiceKaratLine(
                invoice_id=purchase_invoice.id,
                karat=int(reservation.karat or get_main_karat()),
                weight_grams=float(reservation.weight_grams or 0.0),
                gold_value_cash=total_amount,
                manufacturing_wage_cash=0.0,
            )
        )

        _upsert_weight_closing_order(purchase_invoice, execution_price, settings=settings)

        reservation.purchase_invoice_id = purchase_invoice.id
        db.session.add(reservation)

        # Relink prior payment vouchers from reservation -> invoice for better traceability.
        try:
            linked = Voucher.query.filter_by(reference_type='office_reservation', reference_id=reservation.id).all()
            for v in linked:
                v.reference_type = 'invoice'
                v.reference_id = purchase_invoice.id
                v.reference_number = str(purchase_invoice.id)
                db.session.add(v)
        except Exception:
            pass

        gold_entry = JournalEntry(
            entry_number=_generate_journal_entry_number('WGT'),
            date=settlement_date,
            description=f'تنفيذ حجز ذهب ({reservation.reservation_code}) - مكتب {office.name}',
            reference_type='office_reservation',
            reference_id=reservation.id,
            is_posted=True,
            posted_at=settlement_date,
            posted_by=str(data.get('created_by') or 'system'),
        )
        db.session.add(gold_entry)
        db.session.flush()

        # حساب المشتريات (512 كسر / 511 جديد) — مدين نقداً
        _purchases_key = 'purchases_gold_scrap' if getattr(reservation, 'gold_type', 'scrap') == 'scrap' else 'purchases_gold_new'
        purchases_acc_id = (
            get_account_id_for_mapping('شراء من عميل', _purchases_key)
            or get_account_id_for_mapping('شراء من عميل', 'purchases_gold')
            or get_account_id_by_number('512')
            or get_account_id_by_number('511')
        )
        if not purchases_acc_id:
            db.session.rollback()
            return jsonify({'error': 'تعذر تحديد حساب المشتريات (511/512) لتسوية الحجز'}), 500

        karat = int(reservation.karat or get_main_karat())
        if karat not in (18, 21, 22, 24):
            karat = int(get_main_karat() or 21)
        if karat not in (18, 21, 22, 24):
            karat = 21

        weight_grams = float(reservation.weight_grams or 0.0)
        if weight_grams <= 0:
            db.session.rollback()
            return jsonify({'error': 'وزن الحجز غير صالح'}), 400

        # مدين: مشتريات ذهب (512/511) — تكلفة الشراء من المكتب
        create_dual_journal_entry(
            journal_entry_id=gold_entry.id,
            account_id=purchases_acc_id,
            cash_debit=total_amount,
            description=f'شراء ذهب تسكير عيار {karat} - مشتريات',
        )
        # دائن: حساب مورد المكتب — الدفع لاحقاً من خزينة المكتب
        create_dual_journal_entry(
            journal_entry_id=gold_entry.id,
            account_id=office.account_category_id,
            cash_credit=total_amount,
            supplier_id=supplier.id,
            description=f'مستحق لمكتب التسكير عيار {karat} - يُسدَّد من خزينة المكتب',
        )
        verify_dual_balance(gold_entry.id)

        consumption = _auto_consume_weight_closing(
            purchase_invoice.id,
            weight_override=float(reservation.weight_main_karat or 0.0),
            price_per_gram=execution_price,
            execution_type='office_reservation',
            journal_entry_id=gold_entry.id,
            notes=f'Office reservation #{reservation.reservation_code}',
        )

        weight_main_karat = float(reservation.weight_main_karat or 0.0)
        weight_consumed = float(consumption.get('weight_consumed') or 0.0)

        # In this workflow, settlement represents a real purchase/receipt of gold.
        # Weight-closing consumption is an internal matching mechanism and should not block execution.
        reservation.weight_consumed_main_karat = weight_main_karat
        reservation.weight_remaining_main_karat = 0.0
        reservation.executions_created = int(consumption.get('executions_created') or 0)
        reservation.status = 'completed'
        db.session.add(reservation)

        db.session.commit()

        response = _serialize_office_reservation(reservation)
        response['weight_consumption'] = consumption
        response['purchase_invoice_id'] = reservation.purchase_invoice_id
        response['journal_entry'] = {
            'id': gold_entry.id,
            'entry_number': gold_entry.entry_number,
            'date': gold_entry.date.isoformat() if gold_entry.date else settlement_date.isoformat(),
        }
        try:
            eps = 0.0001
            if weight_consumed + eps < weight_main_karat:
                response['weight_closing_warning'] = {
                    'message': 'تم تنفيذ الحجز، لكن لم يتم ربط/استهلاك وزن تسكير كافي (لا توجد أوامر تسكير مفتوحة كفاية).',
                    'weight_requested': round(weight_main_karat, 6),
                    'weight_consumed': round(weight_consumed, 6),
                }
        except Exception:
            pass
        return jsonify(response), 200

    except Exception as exc:
        db.session.rollback()
        print(f"❌ Failed to settle office reservation: {exc}")
        return jsonify({'error': f'فشل تنفيذ الحجز: {exc}'}), 500


@api.route('/office-reservations/<int:reservation_id>/cancel', methods=['POST'])
@require_permission('journal.post')
def cancel_office_reservation(reservation_id: int):
    """Cancel an office reservation.

    This is intentionally conservative:
    - You cannot cancel a reservation after settlement (purchase_invoice_id exists).
    - You cannot cancel if any payment was recorded (paid_amount > 0 or payment voucher exists),
      because that would require a financial reversal workflow.
    """
    reservation = OfficeReservation.query.options(joinedload(OfficeReservation.office)).get(reservation_id)
    if not reservation:
        return jsonify({'error': 'الحجز غير موجود'}), 404

    if reservation.purchase_invoice_id:
        return jsonify({'error': 'لا يمكن إلغاء حجز تم تنفيذه'}), 400

    if (reservation.status or '').lower() == 'cancelled':
        return jsonify(_serialize_office_reservation(reservation)), 200

    paid_amount = float(getattr(reservation, 'paid_amount', 0.0) or 0.0)
    if paid_amount > 0:
        return jsonify({'error': 'لا يمكن إلغاء حجز عليه دفعات. قم بعمل سند عكس/استرجاع أولاً'}), 400

    try:
        linked_voucher = Voucher.query.filter_by(
            reference_type='office_reservation',
            reference_id=reservation.id,
        ).first()
    except Exception:
        linked_voucher = None

    if linked_voucher is not None:
        return jsonify({'error': 'لا يمكن إلغاء حجز مرتبط بسند دفع. قم بإلغاء السند أولاً'}), 400

    # ── قيد عكسي للوزن: إعادة الذهب من المكتب إلى مخزون الكسر ──────────
    try:
        wgt_je = (
            JournalEntry.query
            .filter_by(reference_type='office_reservation', reference_id=reservation.id)
            .filter(JournalEntry.entry_number.like('WGT-%'))
            .filter(JournalEntry.is_deleted.is_(False))
            .first()
        )
        if wgt_je:
            orig_lines = JournalEntryLine.query.filter_by(journal_entry_id=wgt_je.id).all()
            rev_entry = JournalEntry(
                entry_number=_generate_journal_entry_number('WGT'),
                date=datetime.now(),
                description=f'إلغاء حجز ({reservation.reservation_code}) — قيد عكسي',
                reference_type='office_reservation',
                reference_id=reservation.id,
                is_posted=True,
                posted_at=datetime.now(),
                posted_by='cancel',
            )
            db.session.add(rev_entry)
            db.session.flush()

            affected_account_ids = set()
            karats = (18, 21, 22, 24)
            for orig in orig_lines:
                rev_kwargs = {'journal_entry_id': rev_entry.id, 'account_id': orig.account_id, 'description': orig.description}
                for k in karats:
                    d = getattr(orig, f'debit_{k}k') or 0.0
                    c = getattr(orig, f'credit_{k}k') or 0.0
                    if d:
                        rev_kwargs[f'credit_{k}k'] = d
                    if c:
                        rev_kwargs[f'debit_{k}k'] = c
                db.session.add(JournalEntryLine(**rev_kwargs))
                affected_account_ids.add(orig.account_id)

            db.session.flush()
            if affected_account_ids:
                _recalculate_account_balances_for_accounts(list(affected_account_ids))
    except Exception as _exc:
        import traceback; traceback.print_exc()
        db.session.rollback()
        return jsonify({'error': f'فشل إنشاء القيد العكسي: {_exc}'}), 500

    reservation.status = 'cancelled'
    db.session.add(reservation)
    db.session.commit()

    return jsonify(_serialize_office_reservation(reservation)), 200


# ═══════════════════════════════════════════════════════════════
# 🔥 النظام المزدوج: التقارير الوزنية
# ═══════════════════════════════════════════════════════════════

@api.route('/dual_system/income_statement', methods=['GET'])
@require_permission('reports.financial')
def get_weight_based_income_statement():
    """
    قائمة الدخل بالوزن المعادل
    تحسب الإيرادات والمصروفات بالجرام المعادل بناءً على أسعار الذهب
    وقت المعاملة (gold_price_snapshot)
    """
    try:
        start_date_str = request.args.get('start_date')
        end_date_str = request.args.get('end_date')
        
        # التحقق من التواريخ
        if not start_date_str or not end_date_str:
            return jsonify({'error': 'يجب تحديد تاريخ البداية والنهاية'}), 400
        
        start_date = datetime.strptime(start_date_str, '%Y-%m-%d')
        end_date = datetime.strptime(end_date_str, '%Y-%m-%d') + timedelta(days=1)

        # سعر الذهب المباشر (عيار 24) لتحويل النقد إلى وزن عند الحاجة
        latest_gold_price = GoldPrice.query.order_by(GoldPrice.date.desc()).first()
        live_gold_price_per_gram_24k = 0.0
        if latest_gold_price and latest_gold_price.price:
            live_gold_price_per_gram_24k = (latest_gold_price.price / 31.1035) * 3.75
        if live_gold_price_per_gram_24k <= 0:
            live_gold_price_per_gram_24k = 400.0  # fallback يمنع القسمة على صفر

        def cash_to_weight(net_cash: float, price_snapshot: float) -> float:
            price = price_snapshot or live_gold_price_per_gram_24k
            if price and price > 0:
                return net_cash / price
            return 0.0

        # سعر الذهب المباشر (عيار 24) لاستخدامه في تحويل النقد إلى وزن للمصنعية
        latest_gold_price = GoldPrice.query.order_by(GoldPrice.date.desc()).first()
        live_gold_price_per_gram_24k = 0.0
        if latest_gold_price and latest_gold_price.price:
            live_gold_price_per_gram_24k = (latest_gold_price.price / 31.1035) * 3.75
        if live_gold_price_per_gram_24k <= 0:
            live_gold_price_per_gram_24k = 400.0  # قيمة احتياطية لضمان عدم القسمة على صفر

        def cash_to_weight(net_cash: float, price_snapshot: float) -> float:
            price = price_snapshot or live_gold_price_per_gram_24k
            if price and price > 0:
                return net_cash / price
            return 0.0
        main_karat_value = get_main_karat() or 21
        
        # سعر الذهب المباشر (عيار 24) لتحويل الربح النقدي إلى وزن
        latest_gold_price = GoldPrice.query.order_by(GoldPrice.date.desc()).first()
        live_gold_price_per_gram_24k = 0.0
        gold_price_source = 'not_available'
        gold_price_updated_at = None
        if latest_gold_price and latest_gold_price.price:
            live_gold_price_per_gram_24k = (latest_gold_price.price / 31.1035) * 3.75
            gold_price_source = 'database'
            gold_price_updated_at = latest_gold_price.date.isoformat() if latest_gold_price.date else None
        if live_gold_price_per_gram_24k <= 0:
            live_gold_price_per_gram_24k = 400.0  # fallback value
            gold_price_source = 'fallback'
        
        # جلب قيود اليومية المرحّلة فقط في الفترة المحددة (مع استبعاد المحذوف)
        entries = db.session.query(JournalEntryLine).join(JournalEntry).filter(
            JournalEntry.date >= start_date,
            JournalEntry.date < end_date,
            or_(JournalEntry.is_posted == True, JournalEntry.is_posted.is_(None)),
            JournalEntry.is_deleted == False,
            JournalEntryLine.is_deleted == False
        ).all()
        
        # حسابات الإيرادات النقدية (لتحويلها إلى وزن بالسعر المباشر)
        revenue_accounts_cash = db.session.query(Account).filter(
            Account.account_number.like('4%'),
            ~Account.account_number.like('7%')
        ).all()
        revenue_cash_ids = {acc.id for acc in revenue_accounts_cash}

        # محوّل نقد → وزن باستخدام snapshot القيد أو السعر الحالي
        def cash_to_weight(net_cash: float, price_snapshot: float) -> float:
            price = price_snapshot or live_gold_price_per_gram_24k
            if price and price > 0:
                return net_cash / price
            return 0.0

        revenues_weight = defaultdict(float)

        for line in entries:
            if line.account_id in revenue_cash_ids:
                net_cash = (line.cash_credit or 0.0) - (line.cash_debit or 0.0)
                weight = cash_to_weight(net_cash, line.gold_price_snapshot)
                revenues_weight[line.account_id] += weight

        # ─────────────────────────────────────────────
        # الوزن الفعلي المباع من الفواتير (بيع/مرتجع بيع)
        # ─────────────────────────────────────────────
        actual_sold_weight = 0.0

        sale_invoice_types = ['بيع', 'مرتجع بيع']
        sale_invoices = (
            Invoice.query
            .filter(
                Invoice.date >= start_date,
                Invoice.date < end_date,
                Invoice.is_posted == True,
                Invoice.invoice_type.in_(sale_invoice_types)
            )
            .options(joinedload(Invoice.karat_lines), joinedload(Invoice.items))
            .all()
        )

        for inv in sale_invoices:
            direction = 1.0
            inv_type = (inv.invoice_type or '').strip()
            if 'مرتجع' in inv_type and 'بيع' in inv_type:
                direction = -1.0

            # v2: الوزن يُحسب من karat_lines/items بدون ضرب في qty
            weight_value = _invoice_weight_mk_v2(inv)

            if weight_value:
                actual_sold_weight += direction * float(weight_value)

        # مصروفات أجور المصنعية → تحويل من النقد إلى وزن بالسعر المباشر للسطر
        manufacturing_wage_acc_id = (
            get_account_id_for_mapping('بيع', 'manufacturing_wage')
            or _ensure_manufacturing_wage_expense_account()
            or get_account_id_by_number('51')
        )
        manufacturing_wage_weight = 0.0
        manufacturing_wage_details = []

        if manufacturing_wage_acc_id:
            for line in entries:
                if line.account_id == manufacturing_wage_acc_id:
                    net_cash = (line.cash_debit or 0.0) - (line.cash_credit or 0.0)
                    weight = cash_to_weight(net_cash, line.gold_price_snapshot)
                    if weight:
                        manufacturing_wage_weight += weight
                        manufacturing_wage_details.append({
                            'account_code': line.account.account_number if line.account else None,
                            'account_name': line.account.name if line.account else 'أجور مصنعية',
                            'weight_grams': round(weight, 6),
                            'price_snapshot': round(line.gold_price_snapshot, 2) if line.gold_price_snapshot else None
                        })

        # بناء التقرير
        revenue_details = []
        total_revenue_weight = 0.0
        
        for acc_id, weight in revenues_weight.items():
            if weight != 0:
                account = db.session.query(Account).get(acc_id)
                revenue_details.append({
                    'account_code': account.account_number,
                    'account_name': account.name,
                    'weight_grams': round(weight, 6)
                })
                total_revenue_weight += weight
        
        # تكلفة المبيعات الوزنية = الوزن الفعلي المباع
        total_cost_of_sales_weight = actual_sold_weight
        cost_of_sales_details = [{
            'account_code': 'actual_sold_weight',
            'account_name': 'الوزن الفعلي المباع (من الفواتير المرحّلة)',
            'weight_grams': round(actual_sold_weight, 6)
        }]
        
        # المصروفات الوزنية (حالياً: أجور المصنعية محولة للوزن)
        operating_expense_details = manufacturing_wage_details
        total_operating_expense_weight = manufacturing_wage_weight
        
        # حساب ربح الفواتير النقدي وتحويله إلى وزن بالعيار الرئيسي
        profit_cash_total = (
            db.session.query(func.coalesce(func.sum(Invoice.profit_cash), 0.0))
            .filter(
                Invoice.date >= start_date,
                Invoice.date < end_date,
                Invoice.is_posted == True,
                Invoice.invoice_type.in_(['بيع', 'مرتجع بيع'])
            )
            .scalar()
            or 0.0
        )

        profit_weight_grams_24k = (profit_cash_total / live_gold_price_per_gram_24k) if live_gold_price_per_gram_24k > 0 else 0.0
        profit_weight_main_karat = convert_to_main_karat(profit_weight_grams_24k, 24) if profit_weight_grams_24k else 0.0
        # صافي الوزن لحسابات المذكرة (غير مستخدم حالياً في العرض، يُترك للحفاظ على التوافق)
        memo_net_weight = total_revenue_weight - total_operating_expense_weight
        
        # حساب الربح الإجمالي والصافي
        gross_profit_weight = total_revenue_weight - total_cost_of_sales_weight
        net_profit_weight = gross_profit_weight - total_operating_expense_weight
        
        # حساب هامش الربح
        profit_margin_pct = (net_profit_weight / total_revenue_weight * 100) if total_revenue_weight > 0 else 0.0
        
        return jsonify({
            'start_date': start_date_str,
            'end_date': end_date_str,
            'report_type': 'weight_based_income_statement',
            
            # 1️⃣ صافي المبيعات وزن (الإيرادات)
            'net_sales_weight': {
                'total_weight_grams': round(total_revenue_weight, 6),
                'details': sorted(revenue_details, key=lambda x: x['account_code']),
                'note': 'صافي المبيعات بالوزن (من حسابات الإيرادات الوزنية 74xxx)'
            },
            
            # 2️⃣ الوزن المباع (تكلفة المبيعات الوزنية)
            'sold_weight': {
                'total_weight_grams': round(total_cost_of_sales_weight, 6),
                'details': sorted(cost_of_sales_details, key=lambda x: x['account_code']),
                'note': 'الوزن الفعلي المباع من الفواتير المرحّلة (بيع / مرتجع بيع)'
            },
            
            # 3️⃣ الربح الإجمالي الوزني
            'gross_profit_weight': {
                'total_weight_grams': round(gross_profit_weight, 6),
                'note': 'الربح الإجمالي الوزني = صافي المبيعات - الوزن المباع'
            },
            
            # 4️⃣ المصاريف الوزنية (أجور المصنعية + المصاريف التشغيلية)
            'operating_expenses_weight': {
                'total_weight_grams': round(total_operating_expense_weight, 6),
                'details': sorted(operating_expense_details, key=lambda x: x['account_code']),
                'note': 'المصاريف الوزنية (أجور المصنعية والمصاريف التشغيلية)'
            },
            
            # 5️⃣ صافي الربح الوزني
            'net_profit_weight': {
                'total_weight_grams': round(net_profit_weight, 6),
                'note': 'صافي الربح الوزني = الربح الإجمالي - المصاريف الوزنية'
            },
            
            # 6️⃣ هامش الربح
            'profit_margin': {
                'percentage': round(profit_margin_pct, 2),
                'note': 'هامش الربح % = (صافي الربح ÷ صافي المبيعات) × 100'
            },
            
            # معلومات السعر
            'pricing_info': {
                'live_gold_price_per_gram_24k': round(live_gold_price_per_gram_24k, 2) if live_gold_price_per_gram_24k else None,
                'source': gold_price_source,
                'updated_at': gold_price_updated_at,
                'main_karat_reference': main_karat_value
            }
        }), 200
        
    except Exception as e:
        print(f"❌ Error generating weight-based income statement: {e}")
        return jsonify({'error': f'فشل إنشاء قائمة الدخل الوزنية: {str(e)}'}), 500


@api.route('/release-wage-weight', methods=['POST'])
@require_permission('journal.create')
def release_wage_weight():
    data = request.get_json(silent=True) or {}
    grams_raw = data.get('grams')
    note = data.get('note') or data.get('description') or 'تحرير وزن أجور المصنعية'
    karat_value = data.get('karat') or data.get('main_karat') or get_main_karat()

    try:
        grams_value = float(normalize_number(str(grams_raw))) if grams_raw not in (None, '') else 0.0
    except Exception:
        grams_value = 0.0

    if grams_value <= 0:
        return jsonify({'error': 'Invalid weight value'}), 400

    try:
        journal_entry = create_wage_weight_release_journal(
            weight_grams=grams_value,
            note=note,
            karat=karat_value
        )
    except ValueError as exc:
        db.session.rollback()
        return jsonify({'error': str(exc)}), 400
    except Exception as exc:
        db.session.rollback()
        print(f"❌ Error releasing wage weight: {exc}")
        return jsonify({'error': 'فشل تحرير وزن الأجور'}), 500

    return jsonify({
        'status': 'ok',
        'journal_entry_id': journal_entry.id,
        'entry_number': journal_entry.entry_number,
        'weight_grams': round(grams_value, 6)
    }), 201


@api.route('/dual_system/account_statement', methods=['GET'])
@require_permission('reports.financial')
def get_dual_account_statement():
    """
    كشف حساب مزدوج: يعرض النقد والوزن معاً
    """
    try:
        account_id = request.args.get('account_id', type=int)
        start_date_str = request.args.get('start_date')
        end_date_str = request.args.get('end_date')
        
        if not account_id:
            return jsonify({'error': 'يجب تحديد رقم الحساب'}), 400
        
        account = db.session.query(Account).get(account_id)
        if not account:
            return jsonify({'error': 'الحساب غير موجود'}), 404
        
        # بناء الاستعلام
        query = db.session.query(JournalEntryLine).join(JournalEntry).filter(
            JournalEntryLine.account_id == account_id,
            JournalEntry.is_posted == True
        )
        
        if start_date_str:
            start_date = datetime.strptime(start_date_str, '%Y-%m-%d')
            query = query.filter(JournalEntry.date >= start_date)
        
        if end_date_str:
            end_date = datetime.strptime(end_date_str, '%Y-%m-%d')
            query = query.filter(JournalEntry.date <= end_date)
        
        lines = query.order_by(JournalEntry.date, JournalEntry.id).all()
        
        # حساب الأرصدة الجارية
        balance_cash = 0.0
        balance_weight = 0.0
        
        transactions = []
        for line in lines:
            balance_cash += line.cash_debit - line.cash_credit
            balance_weight += line.debit_weight - line.credit_weight
            
            transactions.append({
                'date': line.journal_entry.date.strftime('%Y-%m-%d'),
                'entry_number': line.journal_entry.entry_number,
                'description': line.journal_entry.description,
                'cash_debit': round(line.cash_debit, 2),
                'cash_credit': round(line.cash_credit, 2),
                'weight_debit': round(line.debit_weight, 6),
                'weight_credit': round(line.credit_weight, 6),
                'balance_cash': round(balance_cash, 2),
                'balance_weight': round(balance_weight, 6),
                'gold_price_snapshot': round(line.gold_price_snapshot, 2) if line.gold_price_snapshot else None
            })
        
        return jsonify({
            'account': {
                'id': account.id,
                'code': account.account_number,
                'name': account.name,
                'has_memo_account': account.memo_account_id is not None
            },
            'start_date': start_date_str,
            'end_date': end_date_str,
            'transactions': transactions,
            'final_balance_cash': round(balance_cash, 2),
            'final_balance_weight': round(balance_weight, 6)
        }), 200
        
    except Exception as e:
        print(f"❌ Error generating dual account statement: {e}")
        return jsonify({'error': f'فشل إنشاء كشف الحساب المزدوج: {str(e)}'}), 500


# ═══════════════════════════════════════════════════════════════
# 📊 قائمة الدخل التقليدية (نقدية)
# ═══════════════════════════════════════════════════════════════

@api.route('/reports/income_statement', methods=['GET'])
@require_permission('reports.financial')
def get_income_statement():
    """
    قائمة الدخل (نقدية فقط)

    ملاحظة: تم حذف المؤشرات/الأقسام الوزنية من هذا التقرير لتجنب خلط
    مؤشرات الوزن مع قائمة الدخل المالية.
    """
    try:
        start_date_str = request.args.get('start_date')
        end_date_str = request.args.get('end_date')
        
        if not start_date_str or not end_date_str:
            return jsonify({'error': 'يجب تحديد تاريخ البداية والنهاية'}), 400
        
        start_date = datetime.strptime(start_date_str, '%Y-%m-%d')
        end_date = datetime.strptime(end_date_str, '%Y-%m-%d') + timedelta(days=1)

        # جلب قيود اليومية المرحّلة فقط
        entries = db.session.query(JournalEntryLine).join(JournalEntry).filter(
            JournalEntry.date >= start_date,
            JournalEntry.date < end_date,
            or_(JournalEntry.is_posted == True, JournalEntry.is_posted.is_(None))
        ).all()
        
        # حسابات الإيرادات (4xxx) والمصروفات (5xxx)
        revenue_accounts = db.session.query(Account).filter(
            Account.account_number.like('4%'),
            ~Account.account_number.like('7%')  # استبعاد حسابات المذكرة
        ).all()
        
        # تشمل المصروفات 5xxx (تكلفة/مصاريف) و6xxx (تشغيلية)، مع استبعاد 7xxx (مذكرة)
        expense_accounts = db.session.query(Account).filter(
            or_(
                Account.account_number.like('5%'),
                Account.account_number.like('6%')
            ),
            ~Account.account_number.like('7%')
        ).all()
        
        revenue_ids = {acc.id for acc in revenue_accounts}
        expense_ids = {acc.id for acc in expense_accounts}
        
        # حساب الإيرادات والمصروفات - النظام المالي
        revenues = defaultdict(float)
        expenses = defaultdict(float)
        
        for line in entries:
            # النظام المالي
            if line.account_id in revenue_ids:
                # الإيرادات: الدائن - المدين
                net_amount = line.cash_credit - line.cash_debit
                revenues[line.account_id] += net_amount
            elif line.account_id in expense_ids:
                # المصروفات: المدين - الدائن
                net_amount = line.cash_debit - line.cash_credit
                expenses[line.account_id] += net_amount
        
        # بناء التقرير
        revenue_details = []
        total_revenue = 0.0
        
        for acc_id, amount in revenues.items():
            if amount != 0:
                account = db.session.query(Account).get(acc_id)
                revenue_details.append({
                    'account_code': account.account_number,
                    'account_name': account.name,
                    'amount': round(amount, 2)
                })
                total_revenue += amount
        
        expense_details = []
        total_expense = 0.0

        for acc_id, amount in expenses.items():
            if amount != 0:
                account = db.session.query(Account).get(acc_id)
                expense_details.append({
                    'account_code': account.account_number,
                    'account_name': account.name,
                    'account_id': acc_id,
                    'amount': round(amount, 2)
                })
                total_expense += amount

        # تحديد حساب مصروفات المصنعية وإخراجها بشكل صريح
        # 
        # ⚠️ ملاحظة هيكلية: حساب 51 (أجور مصنعية)
        # - حالياً: 51 (رقم مكون من خانتين)
        # - محاسبياً أدق: 510 أو 511 (ثلاث خانات)
        # - السبب: تفادي التباس مع مجموعات أو parsing مستقبلي
        # - ليس خطأ، لكن تحسين هيكلي طويل المدى
        # - التغيير يتطلب: تعديل دليل الحسابات + migration للبيانات القديمة
        # ─────────────────────────────────────────────
        manufacturing_wage_acc_id = (
            get_account_id_for_mapping('بيع', 'manufacturing_wage')
            or _ensure_manufacturing_wage_expense_account()
            or get_account_id_by_number('51')  # يُفضل استبداله بـ 510 أو 511 مستقبلاً
        )

        manufacturing_wage_amount = 0.0
        manufacturing_wage_detail = None
        if manufacturing_wage_acc_id:
            for detail in expense_details:
                if detail.get('account_id') == manufacturing_wage_acc_id:
                    manufacturing_wage_amount = detail['amount']
                    manufacturing_wage_detail = detail
                    break

        # تقسيم المصروفات إلى تكلفة مبيعات ومصاريف تشغيلية (باستثناء مصروف المصنعية حتى نظهره مستقلاً)
        # 
        # ⚠️ ملاحظة مهمة عن COGS النقدي (5xxx):
        # - يجب تسجيل قيد تكلفة البضاعة المباعة عند كل عملية بيع
        # - يُحسب من متوسط تكلفة المخزون النقدية
        # - إذا ظهر total_cogs = 0، فهذا يعني عدم وجود قيود COGS (خطأ محاسبي)
        # - القيد الصحيح عند البيع:
        #   مدين: 501 (تكلفة بضاعة مباعة) - بمتوسط التكلفة
        #   دائن: 140 (مخزون) - نقدياً
        # ─────────────────────────────────────────────
        cost_of_goods_details = []
        operating_expense_details = []
        total_cogs = 0.0
        total_operating = 0.0

        # تشمل حسابات تكلفة المبيعات الشائعة 50xx و 52x، مع استثناء 51xx لأنها مصاريف تشغيلية وليست تكلفة مبيعات
        cost_prefixes = ('50', '52', '520')

        for detail in expense_details:
            if manufacturing_wage_detail and detail is manufacturing_wage_detail:
                # سيتم التعامل معه كمصروف مصنعية منفصل أدناه
                continue

            code = detail['account_code'] or ''
            if code.startswith(cost_prefixes):
                cost_of_goods_details.append(detail)
                total_cogs += detail['amount']
            else:
                operating_expense_details.append(detail)
                total_operating += detail['amount']

        # إضافة مصروف المصنعية إلى المصاريف التشغيلية الإجمالية (مع عرضه بشكل مستقل)
        operating_expenses_total = total_operating + manufacturing_wage_amount

        gross_profit = total_revenue - total_cogs
        net_income = gross_profit - operating_expenses_total
        
        # حساب النسب المئوية
        net_margin_pct = (net_income / total_revenue * 100) if total_revenue != 0 else 0.0
        
        return jsonify({
            'start_date': start_date_str,
            'end_date': end_date_str,
            'report_type': 'income_statement',
            'summary': {
                # المؤشرات المالية (نقدي)
                'net_revenue': round(total_revenue, 2),
                'gross_profit': round(gross_profit, 2),
                'operating_expenses': round(operating_expenses_total, 2),
                'operating_expenses_excl_wage': round(total_operating, 2),
                'manufacturing_wage_expense': round(manufacturing_wage_amount, 2),
                'net_profit': round(net_income, 2),
                'net_margin_pct': round(net_margin_pct, 2),
            },
            'series': [],  # يمكن إضافة بيانات السلاسل الزمنية لاحقاً
            'revenues': {
                'details': sorted(revenue_details, key=lambda x: x['account_code']),
                'total': round(total_revenue, 2)
            },
            'expenses': {
                'details': sorted(expense_details, key=lambda x: x['account_code']),
                'total': round(total_expense, 2)
            },
            'cost_of_goods_sold': {
                'details': sorted(cost_of_goods_details, key=lambda x: x['account_code']),
                'total': round(total_cogs, 2)
            },
            'gross_profit': round(gross_profit, 2),
            'operating_expenses': {
                'details': sorted(operating_expense_details, key=lambda x: x['account_code']),
                'total': round(total_operating, 2),
                'manufacturing_wage': manufacturing_wage_detail or {
                    'account_code': None,
                    'account_name': 'مصروفات أجور المصنعية',
                    'amount': round(manufacturing_wage_amount, 2),
                }
            },
            'manufacturing_wage_expense': {
                'amount': round(manufacturing_wage_amount, 2),
                'account': manufacturing_wage_detail['account_code'] if manufacturing_wage_detail else None,
                'name': manufacturing_wage_detail['account_name'] if manufacturing_wage_detail else 'مصروفات أجور المصنعية'
            },
            'expense_breakdown': sorted(
                ([manufacturing_wage_detail] if manufacturing_wage_detail else []) + operating_expense_details,
                key=lambda x: abs(x.get('amount', 0)),
                reverse=True
            )[:5],
            'net_income': round(net_income, 2)
        }), 200
        
    except Exception as e:
        print(f"❌ Error generating income statement: {e}")
        return jsonify({'error': f'فشل إنشاء قائمة الدخل: {str(e)}'}), 500


# ══════════════════════════════════════════════════════════════════════════════
# 📊  تقرير ربح الجرام (طريقة طبقية)
#
#  الطبقة ① ربح المتاجرة = (متوسط بيع/جم − متوسط شراء/جم) × الوزن المباع
#  الطبقة ② إيرادات إضافية (وزنية + نقدية) من حسابات مفعّل عليها العلم
#  الطبقة ③ مصاريف وزنية مباشرة من حسابات مفعّل عليها العلم
#  الطبقة ④ مصاريف نقدية محوّلة لوزن من حسابات مفعّل عليها العلم
#
#  صافي الربح الوزني = ① + ② − ③ − ④
# ══════════════════════════════════════════════════════════════════════════════

@api.route('/reports/gram_profit', methods=['GET'])
@require_permission('reports.financial')
def get_gram_profit_report():
    """
    تقرير ربح الجرام الذهبي — آلية طبقية.
    """
    try:
        start_date_str = request.args.get('start_date')
        end_date_str = request.args.get('end_date')

        if not start_date_str or not end_date_str:
            return jsonify({'error': 'يجب تحديد start_date و end_date'}), 400

        start_dt = datetime.strptime(start_date_str, '%Y-%m-%d')
        end_dt = datetime.strptime(end_date_str, '%Y-%m-%d') + timedelta(days=1)

        main_karat = get_main_karat()  # 21 عادةً

        def _to_main(weight, karat):
            try:
                return float(weight or 0.0) * float(karat) / float(main_karat)
            except Exception:
                return 0.0

        def _inv_weight_in_main_karat(inv):
            """حساب وزن الفاتورة بالعيار الرئيسي."""
            total = 0.0
            kl = getattr(inv, 'karat_lines', None) or []
            if kl:
                for line in kl:
                    w = float(getattr(line, 'weight_grams', 0) or 0)
                    k = float(getattr(line, 'karat', main_karat) or main_karat)
                    if w > 0:
                        total += w * k / main_karat
                if total > 0:
                    return total
            inv_items = getattr(inv, 'items', None) or []
            if inv_items:
                for ii in inv_items:
                    w = float(getattr(ii, 'weight', 0) or 0)
                    k = float(getattr(ii, 'karat', 0) or 0)
                    if w > 0 and k > 0:
                        total += w * k / main_karat
                    else:
                        item_obj = getattr(ii, 'item', None)
                        if item_obj:
                            total += float(item_obj.weight_in_main_karat() or 0)
                if total > 0:
                    return total
            return float(inv.total_weight or 0.0)

        _inv_eager = (
            joinedload(Invoice.karat_lines),
            joinedload(Invoice.items).joinedload(InvoiceItem.item),
        )

        # ══════════════════════════════════════════════════════════════════
        # الطبقة ① — ربح المتاجرة (من الفواتير فقط)
        # ══════════════════════════════════════════════════════════════════

        # ── المبيعات ──
        sell_invoices = (
            Invoice.query
            .filter(Invoice.invoice_type.in_(['بيع', 'sell']))
            .filter(Invoice.date >= start_dt, Invoice.date < end_dt)
            .filter(func.coalesce(Invoice.is_posted, False) == True)
            .options(*_inv_eager)
            .all()
        )
        sell_return_invoices = (
            Invoice.query
            .filter(Invoice.invoice_type.in_(['مرتجع بيع']))
            .filter(Invoice.date >= start_dt, Invoice.date < end_dt)
            .filter(func.coalesce(Invoice.is_posted, False) == True)
            .options(*_inv_eager)
            .all()
        )

        total_sales_cash = 0.0
        total_weight_sold = 0.0
        for inv in sell_invoices:
            total_sales_cash += float(inv.total or 0.0)
            total_weight_sold += _inv_weight_in_main_karat(inv)
        for inv in sell_return_invoices:
            total_sales_cash -= float(inv.total or 0.0)
            total_weight_sold -= _inv_weight_in_main_karat(inv)

        avg_sell_per_gram = (
            total_sales_cash / total_weight_sold if total_weight_sold > 0 else 0.0
        )

        # ── المشتريات (لحساب avg_buy) ──
        customer_buy_invoices = (
            Invoice.query
            .filter(Invoice.invoice_type == 'شراء من عميل')
            .filter(Invoice.date >= start_dt, Invoice.date < end_dt)
            .filter(func.coalesce(Invoice.is_posted, False) == True)
            .options(*_inv_eager)
            .all()
        )
        customer_buy_returns = (
            Invoice.query
            .filter(Invoice.invoice_type == 'مرتجع شراء')
            .filter(Invoice.date >= start_dt, Invoice.date < end_dt)
            .filter(func.coalesce(Invoice.is_posted, False) == True)
            .options(*_inv_eager)
            .all()
        )
        settlement_buy_invoices = (
            Invoice.query
            .filter(Invoice.invoice_type.in_(['شراء', 'buy']))
            .filter(func.coalesce(Invoice.gold_type, '') == 'scrap')
            .filter(Invoice.date >= start_dt, Invoice.date < end_dt)
            .filter(func.coalesce(Invoice.is_posted, False) == True)
            .options(*_inv_eager)
            .all()
        )
        supplier_buy_invoices = (
            Invoice.query
            .filter(Invoice.invoice_type.in_(['شراء', 'buy']))
            .filter(or_(
                func.coalesce(Invoice.gold_type, '') != 'scrap',
                Invoice.gold_type.is_(None),
            ))
            .filter(Invoice.date >= start_dt, Invoice.date < end_dt)
            .filter(func.coalesce(Invoice.is_posted, False) == True)
            .options(*_inv_eager)
            .all()
        )
        supplier_buy_returns = (
            Invoice.query
            .filter(Invoice.invoice_type == 'مرتجع شراء (مورد)')
            .filter(Invoice.date >= start_dt, Invoice.date < end_dt)
            .filter(func.coalesce(Invoice.is_posted, False) == True)
            .options(*_inv_eager)
            .all()
        )

        total_purchases_cash = 0.0
        total_weight_purchased = 0.0
        for inv in customer_buy_invoices:
            total_purchases_cash += float(inv.total or 0.0)
            total_weight_purchased += _inv_weight_in_main_karat(inv)
        for inv in customer_buy_returns:
            total_purchases_cash -= float(inv.total or 0.0)
            total_weight_purchased -= _inv_weight_in_main_karat(inv)

        settlement_purchases_cash = 0.0
        settlement_weight_purchased = 0.0
        for inv in settlement_buy_invoices:
            settlement_purchases_cash += float(inv.total or 0.0)
            settlement_weight_purchased += _inv_weight_in_main_karat(inv)

        supplier_purchases_cash = 0.0
        supplier_weight_purchased = 0.0
        for inv in supplier_buy_invoices:
            supplier_purchases_cash += float(inv.total or 0.0)
            supplier_weight_purchased += _inv_weight_in_main_karat(inv)
        for inv in supplier_buy_returns:
            supplier_purchases_cash -= float(inv.total or 0.0)
            supplier_weight_purchased -= _inv_weight_in_main_karat(inv)

        cash_for_gold_purchases = total_purchases_cash + settlement_purchases_cash
        cash_for_gold_weight = total_weight_purchased + settlement_weight_purchased
        total_all_purchases_cash = cash_for_gold_purchases + supplier_purchases_cash
        total_all_weight_purchased = cash_for_gold_weight + supplier_weight_purchased

        # متوسط الشراء: عملاء + تسويات فقط (بدون موردين مصنّعة)
        avg_buy_per_gram = (
            cash_for_gold_purchases / cash_for_gold_weight
            if cash_for_gold_weight > 0 else 0.0
        )

        margin_per_gram = avg_sell_per_gram - avg_buy_per_gram
        trading_profit_cash = margin_per_gram * total_weight_sold
        trading_profit_weight = (
            trading_profit_cash / avg_buy_per_gram if avg_buy_per_gram > 0 else 0.0
        )

        # ══════════════════════════════════════════════════════════════════
        # الطبقات ② ③ ④ — من القيود اليومية على حسابات include_in_gram_profit
        # (مع وراثة: تفعيل الأب يشمل جميع أبنائه تلقائياً)
        # ══════════════════════════════════════════════════════════════════

        directly_flagged = (
            Account.query
            .filter(Account.include_in_gram_profit == True)
            .filter(func.coalesce(Account.exclude_from_gram_profit, False) == False)
            .all()
        )

        # جمع الأبناء لكل حساب مُفعّل (بحث تكراري)
        flagged_ids = {acc.id for acc in directly_flagged}

        # الحسابات المستثناة صراحةً (exclude_from_gram_profit=True)
        excluded_ids = {
            acc.id for acc in
            Account.query.filter(func.coalesce(Account.exclude_from_gram_profit, False) == True).all()
        }

        def _collect_descendants(parent_ids):
            if not parent_ids:
                return
            children = Account.query.filter(Account.parent_id.in_(parent_ids)).all()
            new_ids = set()
            for ch in children:
                if ch.id not in flagged_ids and ch.id not in excluded_ids:
                    flagged_ids.add(ch.id)
                    new_ids.add(ch.id)
            _collect_descendants(new_ids)

        _collect_descendants(flagged_ids.copy())

        # ── تضمين تلقائي للحسابات الوزنية التشغيلية (74xx / 75xx) ─────────────
        # نستثني مجموعتي المقابلات التجارية لأنهما محسوبتان في الطبقة ①:
        #   741xx = مقابلات المبيعات الوزنية  (Layer ① → trading_profit)
        #   751xx = مقابلات تكلفة المبيعات الوزنية (Layer ① → avg_buy)
        # ونستثني أيضاً أي حساب عليه exclude_from_gram_profit=True
        _counterpart_parent_accs = Account.query.filter(
            Account.account_number.in_(['741', '751'])
        ).all()
        _counterpart_group_ids = {a.id for a in _counterpart_parent_accs}

        weight_memo_accs = (
            Account.query
            .filter(or_(
                Account.account_number.like('74%'),
                Account.account_number.like('75%'),
            ))
            .filter(Account.id.notin_(_counterpart_group_ids))
            .filter(or_(
                Account.parent_id.is_(None),
                Account.parent_id.notin_(_counterpart_group_ids),
            ))
            .filter(func.coalesce(Account.exclude_from_gram_profit, False) == False)
            .all()
        )
        for _wma in weight_memo_accs:
            if _wma.id not in excluded_ids:
                flagged_ids.add(_wma.id)
        # ────────────────────────────────────────────────────────────────────────

        # إزالة المستثنيين صراحةً من النهائية
        flagged_ids -= excluded_ids

        flagged_accounts = Account.query.filter(Account.id.in_(flagged_ids)).all() if flagged_ids else []

        revenue_account_ids = set()
        expense_account_ids = set()
        for acc in flagged_accounts:
            num = str(acc.account_number or '')
            # 4xxx = إيرادات مالية، 74xx = إيرادات وزنية (مذكرة)
            if num.startswith('4') or num.startswith('74'):
                revenue_account_ids.add(acc.id)
            # 5xxx/6xxx = مصاريف مالية، 75xx = مصاريف وزنية (مذكرة)
            elif num.startswith('5') or num.startswith('6') or num.startswith('75'):
                expense_account_ids.add(acc.id)

        all_flagged_ids = revenue_account_ids | expense_account_ids

        # جلب جميع سطور القيود على هذه الحسابات في الفترة
        flagged_lines = []
        if all_flagged_ids:
            flagged_lines = (
                db.session.query(JournalEntryLine)
                .join(JournalEntry)
                .filter(JournalEntryLine.account_id.in_(all_flagged_ids))
                .filter(JournalEntry.date >= start_dt, JournalEntry.date < end_dt)
                .filter(func.coalesce(JournalEntry.is_posted, False) == True)
                .filter(func.coalesce(JournalEntry.is_deleted, False) == False)
                .filter(func.coalesce(JournalEntryLine.is_deleted, False) == False)
                .all()
            )

        # بناء خريطة account_id → Account object
        acc_map = {acc.id: acc for acc in flagged_accounts}

        # ── الطبقة ② — إيرادات إضافية ──
        extra_revenue_weight = 0.0      # إيرادات وزنية مباشرة (جم 21)
        extra_revenue_cash = 0.0        # إيرادات نقدية (ر.س)
        extra_revenue_details = []

        # ── الطبقة ③ — مصاريف وزنية مباشرة ──
        expense_weight_direct = 0.0     # مصاريف وزنية (جم 21)
        expense_weight_details = []

        # ── الطبقة ④ — مصاريف نقدية ──
        expense_cash_total = 0.0        # مصاريف نقدية (ر.س)
        expense_cash_details = []

        for line in flagged_lines:
            acc_id = line.account_id
            acc = acc_map.get(acc_id)
            if not acc:
                continue
            acc_num = str(acc.account_number or '')
            acc_name = acc.name or ''

            # دالة مساعدة: تُجمّع جميع العيارات مُطبَّعةً إلى العيار الرئيسي
            def _normalized_21k(prefix):
                total = 0.0
                for karat in (18, 21, 22, 24):
                    field = f'{prefix}_{karat}k'
                    val = float(getattr(line, field, 0) or 0)
                    if val:
                        total += val * karat / main_karat
                return total

            # حساب الوزن المباشر:
            # - حسابات مالية (4/5/6): تستخدم debit_21k / credit_21k
            # - حسابات وزنية (74/75): تجمع جميع العيارات مُطبَّعةً إلى 21k
            #   وإلا fallback إلى debit_weight / credit_weight
            if acc_num.startswith('74') or acc_num.startswith('75'):
                w_debit = _normalized_21k('debit')
                w_credit = _normalized_21k('credit')
                # fallback إلى debit_weight إذا لم تتوفر أي حقول karat
                if w_debit == 0 and w_credit == 0:
                    w_debit = float(getattr(line, 'debit_weight', 0) or 0)
                    w_credit = float(getattr(line, 'credit_weight', 0) or 0)
            else:
                w_debit = float(getattr(line, 'debit_21k', 0) or 0)
                w_credit = float(getattr(line, 'credit_21k', 0) or 0)

            # حساب النقد
            c_debit = float(line.cash_debit or 0)
            c_credit = float(line.cash_credit or 0)

            if acc_id in revenue_account_ids:
                # إيرادات: credit = زيادة
                weight_net = w_credit - w_debit
                cash_net = c_credit - c_debit

                if abs(weight_net) > 0.0001:
                    extra_revenue_weight += weight_net
                    extra_revenue_details.append({
                        'account_number': acc_num,
                        'account_name': acc_name,
                        'type': 'weight',
                        'weight_grams': round(weight_net, 6),
                    })
                if abs(cash_net) > 0.01:
                    extra_revenue_cash += cash_net
                    extra_revenue_details.append({
                        'account_number': acc_num,
                        'account_name': acc_name,
                        'type': 'cash',
                        'cash_amount': round(cash_net, 2),
                    })

            elif acc_id in expense_account_ids:
                # مصاريف: debit = زيادة
                weight_net = w_debit - w_credit
                cash_net = c_debit - c_credit

                if abs(weight_net) > 0.0001:
                    expense_weight_direct += weight_net
                    expense_weight_details.append({
                        'account_number': acc_num,
                        'account_name': acc_name,
                        'type': 'weight',
                        'weight_grams': round(weight_net, 6),
                    })
                if abs(cash_net) > 0.01:
                    expense_cash_total += cash_net
                    expense_cash_details.append({
                        'account_number': acc_num,
                        'account_name': acc_name,
                        'type': 'cash',
                        'cash_amount': round(cash_net, 2),
                    })

        # تجميع التفاصيل حسب رقم الحساب (account_number) بدل سطر لكل قيد
        def _aggregate_details(raw_list, value_key):
            merged = {}
            for entry in raw_list:
                key = entry['account_number']
                if key not in merged:
                    merged[key] = {k: v for k, v in entry.items()}
                else:
                    merged[key][value_key] = round(
                        merged[key][value_key] + entry[value_key], 6
                    )
            # أزل الإدخالات التي صارت صفراً بعد التجميع
            return [e for e in merged.values() if abs(e[value_key]) > 0.0001]

        expense_weight_details  = _aggregate_details(expense_weight_details,  'weight_grams')
        expense_cash_details    = _aggregate_details(expense_cash_details,     'cash_amount')
        extra_revenue_details_w = _aggregate_details(
            [x for x in extra_revenue_details if x['type'] == 'weight'], 'weight_grams')
        extra_revenue_details_c = _aggregate_details(
            [x for x in extra_revenue_details if x['type'] == 'cash'],   'cash_amount')
        extra_revenue_details = extra_revenue_details_w + extra_revenue_details_c

        # تحويل الإيراد النقدي إلى وزن
        extra_revenue_cash_as_weight = (
            extra_revenue_cash / avg_buy_per_gram if avg_buy_per_gram > 0 else 0.0
        )
        # تحويل المصروف النقدي إلى وزن
        expense_cash_as_weight = (
            expense_cash_total / avg_buy_per_gram if avg_buy_per_gram > 0 else 0.0
        )

        # إجمالي الطبقة ② (وزني + نقدي محوّل)
        total_extra_revenue_weight = extra_revenue_weight + extra_revenue_cash_as_weight
        # إجمالي الطبقة ③
        total_expense_weight_direct = expense_weight_direct
        # إجمالي الطبقة ④ (محوّل لوزن)
        total_expense_cash_weight = expense_cash_as_weight

        # ══════════════════════════════════════════════════════════════════
        # النتيجة النهائية
        # ══════════════════════════════════════════════════════════════════

        gross_profit = trading_profit_cash
        gross_profit_weight = trading_profit_weight

        net_profit_weight = (
            trading_profit_weight           # ① ربح المتاجرة
            + total_extra_revenue_weight    # ② إيرادات إضافية
            - total_expense_weight_direct   # ③ مصاريف وزنية
            - total_expense_cash_weight     # ④ مصاريف نقدية (محوّلة)
        )

        # ربح نقدي معادل (للعرض)
        net_profit_cash = net_profit_weight * avg_buy_per_gram if avg_buy_per_gram > 0 else 0.0

        net_margin_pct = (
            (net_profit_cash / total_sales_cash * 100) if total_sales_cash > 0 else 0.0
        )

        return jsonify({
            'start_date': start_date_str,
            'end_date': end_date_str,
            'report_type': 'gram_profit',
            'main_karat': main_karat,

            # الطبقة ① — ربح المتاجرة
            'weight_sold': round(total_weight_sold, 3),
            'weight_purchased': round(total_all_weight_purchased, 3),
            'weight_purchased_customer': round(total_weight_purchased, 3),
            'weight_purchased_supplier': round(supplier_weight_purchased, 3),
            'avg_sell_per_gram': round(avg_sell_per_gram, 2),
            'avg_buy_per_gram': round(avg_buy_per_gram, 2),
            'margin_per_gram': round(margin_per_gram, 2),
            'trading_profit_cash': round(trading_profit_cash, 2),
            'trading_profit_weight': round(trading_profit_weight, 3),
            'total_sales_cash': round(total_sales_cash, 2),
            'total_purchases_cash': round(total_all_purchases_cash, 2),
            'customer_purchases_cash': round(total_purchases_cash, 2),
            'settlement_purchases_cash': round(settlement_purchases_cash, 2),
            'settlement_weight_purchased': round(settlement_weight_purchased, 3),
            'supplier_purchases_cash': round(supplier_purchases_cash, 2),
            'supplier_weight_purchased': round(supplier_weight_purchased, 3),

            # الطبقة ② — إيرادات إضافية
            'extra_revenue_weight': round(extra_revenue_weight, 3),
            'extra_revenue_cash': round(extra_revenue_cash, 2),
            'extra_revenue_cash_as_weight': round(extra_revenue_cash_as_weight, 3),
            'total_extra_revenue_weight': round(total_extra_revenue_weight, 3),
            'extra_revenue_details': extra_revenue_details,

            # الطبقة ③ — مصاريف وزنية مباشرة
            'expense_weight_direct': round(total_expense_weight_direct, 3),
            'expense_weight_details': expense_weight_details,

            # الطبقة ④ — مصاريف نقدية (محوّلة)
            'expense_cash_total': round(expense_cash_total, 2),
            'expense_cash_as_weight': round(total_expense_cash_weight, 3),
            'expense_cash_details': expense_cash_details,

            # النتيجة النهائية
            'gross_profit': round(gross_profit, 2),
            'gross_profit_weight': round(gross_profit_weight, 3),
            'net_profit': round(net_profit_cash, 2),
            'net_profit_weight': round(net_profit_weight, 3),
            'net_margin_pct': round(net_margin_pct, 2),

            # حقول توافقية (backward compat)
            'manufacturing_wages': round(expense_cash_total, 2),
            'other_expenses': 0.0,
            'total_operating_expenses': round(expense_cash_total + expense_weight_direct * avg_buy_per_gram, 2),
            'profit_after_wages': round(net_profit_cash, 2),
            'profit_after_wages_weight': round(net_profit_weight, 3),
        }), 200

    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': f'فشل حساب ربح الجرام: {str(e)}'}), 500


# ==================== 🆕 Dual Chart of Accounts Endpoints ====================

@api.route('/reports/bridge-balance-monitor', methods=['GET'])
@require_permission('reports.financial')
def get_bridge_balance_monitor():
    """
    🆕 تقرير مراقبة رصيد حساب الجسر
    
    القاعدة الذهبية: رصيد حساب الجسر يجب أن يكون = صفر دائماً
    
    هذا التقرير:
    1. يعرض جميع حسابات الجسر في النظام
    2. يحدد أي حساب جسر به رصيد غير صفري
    3. يوفر تفاصيل للتحقيق في الخلل المحاسبي
    
    Returns:
    - bridge_accounts: قائمة حسابات الجسر مع أرصدتها
    - alerts: تحذيرات لأي حساب به رصيد غير صفري
    - status: 'balanced' أو 'unbalanced'
    """
    try:
        # البحث عن حسابات الجسر
        # 1. من الإعدادات المحاسبية
        bridge_mapping = AccountingMapping.query.filter(
            or_(
                AccountingMapping.mapping_key == 'supplier_bridge',
                AccountingMapping.mapping_key == 'customer_bridge',
                AccountingMapping.mapping_key.like('%bridge%')
            )
        ).all()
        
        bridge_account_ids = set()
        for mapping in bridge_mapping:
            if mapping.account_id:
                bridge_account_ids.add(mapping.account_id)
        
        # 2. من أسماء الحسابات التي تحتوي على "جسر"
        bridge_accounts_by_name = Account.query.filter(
            or_(
                Account.name.like('%جسر%'),
                Account.name.like('%bridge%'),
                Account.account_number.like('%999%')  # نمط شائع لحسابات الجسر
            )
        ).all()
        
        for acc in bridge_accounts_by_name:
            bridge_account_ids.add(acc.id)
        
        # جمع البيانات
        accounts_data = []
        alerts = []
        total_imbalance = 0.0
        
        for acc_id in bridge_account_ids:
            account = Account.query.get(acc_id)
            if not account:
                continue
            
            balance = account.balance_cash or 0.0
            
            # التحقق من التوازن (هامش خطأ 0.01)
            is_balanced = abs(balance) <= 0.01
            
            account_info = {
                'account_id': account.id,
                'account_number': account.account_number,
                'account_name': account.name,
                'balance': round(balance, 2),
                'is_balanced': is_balanced,
                'status': '✅ متوازن' if is_balanced else '⚠️ غير متوازن'
            }
            
            accounts_data.append(account_info)
            
            if not is_balanced:
                total_imbalance += abs(balance)
                alerts.append({
                    'severity': 'warning' if abs(balance) < 10 else 'error',
                    'account_number': account.account_number,
                    'account_name': account.name,
                    'balance': round(balance, 2),
                    'message': f'حساب الجسر {account.account_number} ({account.name}) به رصيد غير صفري: {balance:.2f} ريال',
                    'recommendation': 'يرجى مراجعة القيود المحاسبية للفواتير المرتبطة بهذا الحساب'
                })
        
        overall_status = 'balanced' if len(alerts) == 0 else 'unbalanced'
        
        return jsonify({
            'status': overall_status,
            'summary': {
                'total_bridge_accounts': len(accounts_data),
                'balanced_accounts': sum(1 for acc in accounts_data if acc['is_balanced']),
                'unbalanced_accounts': sum(1 for acc in accounts_data if not acc['is_balanced']),
                'total_imbalance': round(total_imbalance, 2)
            },
            'bridge_accounts': accounts_data,
            'alerts': alerts,
            'notes': [
                '📌 القاعدة الذهبية: رصيد حساب الجسر = صفر دائماً',
                '⚠️ أي رصيد غير صفري يشير إلى خلل محاسبي',
                '🔍 يجب التحقيق في القيود المرتبطة بالحسابات غير المتوازنة',
                '💡 هامش الخطأ المسموح: ±0.01 ريال (للفواصل العشرية)'
            ]
        }), 200
        
    except Exception as e:
        print(f"❌ Error generating bridge balance monitor: {e}")
        return jsonify({'error': f'فشل إنشاء تقرير مراقبة حساب الجسر: {str(e)}'}), 500


@api.route('/reports/trial-balance/cash', methods=['GET'])
@require_permission('reports.financial')
def get_cash_trial_balance():
    """
    ميزان المراجعة المالي (النقدي)
    
    يعرض أرصدة الحسابات من الشجرة المالية فقط (transaction_type='cash')
    
    Query Parameters:
    - date: تاريخ نهاية التقرير (YYYY-MM-DD) - افتراضي: اليوم
    
    Returns:
    - accounts: قائمة الحسابات مع أرصدتها
    - totals: إجماليات المدين والدائن والرصيد
    """
    try:
        end_date_str = request.args.get('date')
        if end_date_str:
            end_date = datetime.fromisoformat(end_date_str).date()
        else:
            end_date = datetime.now().date()
        
        # جلب جميع الحسابات النقدية
        cash_accounts = Account.query.filter_by(transaction_type='cash').order_by(Account.account_number).all()
        
        accounts_data = []
        total_debit = 0.0
        total_credit = 0.0
        
        for account in cash_accounts:
            # حساب الرصيد من القيود حتى التاريخ المحدد
            lines = JournalEntryLine.query.join(JournalEntry).filter(
                JournalEntryLine.account_id == account.id,
                JournalEntry.date <= end_date
            ).all()
            
            debit_sum = sum(line.cash_debit or 0 for line in lines)
            credit_sum = sum(line.cash_credit or 0 for line in lines)
            balance = debit_sum - credit_sum
            
            # عرض فقط الحسابات التي لها رصيد أو حركة
            if abs(balance) > 0.001 or abs(debit_sum) > 0.001 or abs(credit_sum) > 0.001:
                accounts_data.append({
                    'account_number': account.account_number,
                    'account_name': account.name,
                    'account_type': account.type,
                    'debit': round(debit_sum, 2),
                    'credit': round(credit_sum, 2),
                    'balance': round(balance, 2)
                })
                
                if balance > 0:
                    total_debit += balance
                else:
                    total_credit += abs(balance)
        
        return jsonify({
            'report_type': 'trial_balance_cash',
            'date': end_date.isoformat(),
            'accounts': accounts_data,
            'totals': {
                'total_debit': round(total_debit, 2),
                'total_credit': round(total_credit, 2),
                'difference': round(total_debit - total_credit, 2)
            }
        }), 200
        
    except Exception as e:
        print(f"❌ Error generating cash trial balance: {e}")
        return jsonify({'error': f'فشل إنشاء ميزان المراجعة النقدي: {str(e)}'}), 500


@api.route('/reports/trial-balance/gold', methods=['GET'])
@require_permission('reports.financial')
def get_gold_trial_balance():
    """
    ميزان المراجعة الوزني (الذهب)
    
    يعرض أرصدة الحسابات من الشجرة الوزنية فقط (transaction_type='gold')
    
    Query Parameters:
    - date: تاريخ نهاية التقرير (YYYY-MM-DD) - افتراضي: اليوم
    - karat: العيار المطلوب (18, 21, 22, 24) - افتراضي: جميع الأعيرة محولة للعيار الرئيسي
    
    Returns:
    - accounts: قائمة الحسابات مع أرصدتها الوزنية
    - totals: إجماليات المدين والدائن بالجرامات
    """
    try:
        from config import MAIN_KARAT
        
        end_date_str = request.args.get('date')
        if end_date_str:
            end_date = datetime.fromisoformat(end_date_str).date()
        else:
            end_date = datetime.now().date()
        
        karat_filter = request.args.get('karat')
        main_karat = MAIN_KARAT or 21
        
        # جلب جميع الحسابات الوزنية
        gold_accounts = Account.query.filter_by(transaction_type='gold').order_by(Account.account_number).all()
        
        accounts_data = []
        total_debit = 0.0
        total_credit = 0.0
        
        for account in gold_accounts:
            # حساب الرصيد من القيود حتى التاريخ المحدد
            lines = JournalEntryLine.query.join(JournalEntry).filter(
                JournalEntryLine.account_id == account.id,
                JournalEntry.date <= end_date
            ).all()
            
            # جمع الأوزان من جميع الأعيرة (محولة للعيار الرئيسي)
            debit_18k = sum(line.debit_18k or 0 for line in lines) * (18 / main_karat)
            debit_21k = sum(line.debit_21k or 0 for line in lines) * (21 / main_karat)
            debit_22k = sum(line.debit_22k or 0 for line in lines) * (22 / main_karat)
            debit_24k = sum(line.debit_24k or 0 for line in lines) * (24 / main_karat)
            
            credit_18k = sum(line.credit_18k or 0 for line in lines) * (18 / main_karat)
            credit_21k = sum(line.credit_21k or 0 for line in lines) * (21 / main_karat)
            credit_22k = sum(line.credit_22k or 0 for line in lines) * (22 / main_karat)
            credit_24k = sum(line.credit_24k or 0 for line in lines) * (24 / main_karat)
            
            total_debit_weight = debit_18k + debit_21k + debit_22k + debit_24k
            total_credit_weight = credit_18k + credit_21k + credit_22k + credit_24k
            balance_weight = total_debit_weight - total_credit_weight
            
            # عرض فقط الحسابات التي لها رصيد أو حركة
            if abs(balance_weight) > 0.001 or abs(total_debit_weight) > 0.001 or abs(total_credit_weight) > 0.001:
                accounts_data.append({
                    'account_number': account.account_number,
                    'account_name': account.name,
                    'account_type': account.type,
                    'debit_grams': round(total_debit_weight, 3),
                    'credit_grams': round(total_credit_weight, 3),
                    'balance_grams': round(balance_weight, 3),
                    'main_karat': main_karat
                })
                
                if balance_weight > 0:
                    total_debit += balance_weight
                else:
                    total_credit += abs(balance_weight)
        
        return jsonify({
            'report_type': 'trial_balance_gold',
            'date': end_date.isoformat(),
            'main_karat': main_karat,
            'accounts': accounts_data,
            'totals': {
                'total_debit_grams': round(total_debit, 3),
                'total_credit_grams': round(total_credit, 3),
                'difference_grams': round(total_debit - total_credit, 3)
            }
        }), 200
        
    except Exception as e:
        print(f"❌ Error generating gold trial balance: {e}")
        return jsonify({'error': f'فشل إنشاء ميزان المراجعة الوزني: {str(e)}'}), 500


@api.route('/reports/inventory_reconciliation', methods=['GET'])
@require_permission('reports.financial')
def get_inventory_reconciliation_report():
    """تقرير مطابقة المخزون المالي مع المخزون الوزني.

    يقارن بين:
    - حسابات المخزون المالية 13xx (قيمة بالريال)
    - وحسابات المخزون الوزنية 7131xx (وزن بالجرام محوّل للعيار الرئيسي)

    ويعرض لكل زوج (مالي ↔ وزني):
    - الرصيد المالي (ريال)
    - الرصيد الوزني (جرام)
    - نسبة القيمة لكل جرام (ريال/جرام) إن أمكن
    """
    try:
        from config import MAIN_KARAT

        end_date_str = request.args.get('date')
        if end_date_str:
            end_date = datetime.fromisoformat(end_date_str).date()
        else:
            end_date = datetime.now().date()

        main_karat = MAIN_KARAT or 21

        # 1) حساب أرصدة المخزون المالية 13xx
        financial_accounts = Account.query.filter(
            Account.account_number.like('13%'),
            Account.transaction_type.in_(['cash', 'both']),
        ).order_by(Account.account_number).all()

        financial_balances = {}
        for acc in financial_accounts:
            lines = (
                JournalEntryLine.query
                .join(JournalEntry)
                .filter(
                    JournalEntryLine.account_id == acc.id,
                    JournalEntry.date <= end_date,
                )
                .all()
            )

            debit_cash = sum(line.cash_debit or 0 for line in lines)
            credit_cash = sum(line.cash_credit or 0 for line in lines)
            balance_cash = debit_cash - credit_cash

            financial_balances[acc.account_number] = {
                'account': acc,
                'balance_cash': balance_cash,
            }

        # 2) حساب أرصدة المخزون الوزنية 7131xx (وزن محوَّل للعيار الرئيسي)
        gold_accounts = Account.query.filter(
            Account.account_number.like('7131%'),
            Account.transaction_type == 'gold',
        ).order_by(Account.account_number).all()

        gold_balances = {}
        for acc in gold_accounts:
            lines = (
                JournalEntryLine.query
                .join(JournalEntry)
                .filter(
                    JournalEntryLine.account_id == acc.id,
                    JournalEntry.date <= end_date,
                )
                .all()
            )

            debit_18k = sum(line.debit_18k or 0 for line in lines) * (18 / main_karat)
            debit_21k = sum(line.debit_21k or 0 for line in lines) * (21 / main_karat)
            debit_22k = sum(line.debit_22k or 0 for line in lines) * (22 / main_karat)
            debit_24k = sum(line.debit_24k or 0 for line in lines) * (24 / main_karat)

            credit_18k = sum(line.credit_18k or 0 for line in lines) * (18 / main_karat)
            credit_21k = sum(line.credit_21k or 0 for line in lines) * (21 / main_karat)
            credit_22k = sum(line.credit_22k or 0 for line in lines) * (22 / main_karat)
            credit_24k = sum(line.credit_24k or 0 for line in lines) * (24 / main_karat)

            total_debit_weight = debit_18k + debit_21k + debit_22k + debit_24k
            total_credit_weight = credit_18k + credit_21k + credit_22k + credit_24k
            balance_weight = total_debit_weight - total_credit_weight

            gold_balances[acc.account_number] = {
                'account': acc,
                'balance_grams': balance_weight,
            }

        # 3) مطابقة 1310 ↔ 71310, 1320 ↔ 71320, 1340 ↔ 71330 ... الخ
        rows = []
        all_numbers = sorted(set(list(financial_balances.keys()) + list(gold_balances.keys())))

        for number in all_numbers:
            fin = financial_balances.get(number)
            # نظير وزني متوقع بإضافة 7 في البداية (إن لم يكن 7131xx مباشرة)
            expected_gold_number = None
            if number.startswith('13') and not number.startswith('7131'):
                # مثال: 1310 → 71310
                expected_gold_number = '7' + number
            else:
                expected_gold_number = number

            gold = gold_balances.get(expected_gold_number)

            balance_cash = fin['balance_cash'] if fin else 0.0
            balance_grams = gold['balance_grams'] if gold else 0.0

            price_per_gram = None
            if balance_grams and abs(balance_grams) > 0.0001:
                price_per_gram = balance_cash / balance_grams

            rows.append({
                'financial_account': fin['account'].account_number if fin else number,
                'financial_name': fin['account'].name if fin else None,
                'gold_account': gold['account'].account_number if gold else expected_gold_number,
                'gold_name': gold['account'].name if gold else None,
                'balance_cash': round(float(balance_cash or 0.0), 2),
                'balance_grams': round(float(balance_grams or 0.0), 3),
                'price_per_gram': round(float(price_per_gram), 2) if price_per_gram is not None else None,
            })

        return jsonify({
            'report_type': 'inventory_reconciliation',
            'date': end_date.isoformat(),
            'main_karat': main_karat,
            'rows': rows,
        }), 200

    except Exception as e:
        print(f"❌ Error generating inventory reconciliation report: {e}")
        return jsonify({'error': f'فشل إنشاء تقرير مطابقة المخزون: {str(e)}'}), 500


@api.route('/reports/gold-weight-trial-balance', methods=['GET'])
@require_permission('reports.financial')
def get_gold_weight_trial_balance_by_safe_box():
    """ميزان مراجعة الأوزان (مطابقة الخزائن ↔ الحسابات الوزنية المرتبطة).

    الهدف:
    - جرد أرصدة كل خزنة ذهب من دفتر الخزينة (SafeBoxTransaction)
    - مقارنة الرصيد مع الحساب الوزني المرتبط (عادةً 7xxx) من القيود اليومية
    - إظهار الفرق (Variance) لاكتشاف أي تعديل يدوي على الحساب دون دفتر الخزنة (أو العكس)

    Query Parameters:
    - date: تاريخ نهاية التقرير (YYYY-MM-DD) - افتراضي: اليوم

    Returns:
    - rows: لكل خزنة: رصيد الخزنة، رصيد الحساب، والفرق لكل عيار + إجمالي محول للعيار الرئيسي
    """
    try:
        from config import MAIN_KARAT

        end_date_str = request.args.get('date')
        if end_date_str:
            end_date = datetime.fromisoformat(end_date_str).date()
        else:
            end_date = datetime.now().date()

        main_karat = float(MAIN_KARAT or 21)
        end_dt = datetime.combine(end_date, time.max)

        def _to_float(v):
            try:
                return float(v or 0.0)
            except Exception:
                return 0.0

        def _normalize_to_main(weight: float, karat: int) -> float:
            k = float(karat)
            if main_karat <= 0:
                return float(weight or 0.0)
            return float(weight or 0.0) * (k / main_karat)

        def _total_main_from_by_karat(by_karat: dict) -> float:
            return (
                _normalize_to_main(_to_float(by_karat.get('18k')), 18)
                + _normalize_to_main(_to_float(by_karat.get('21k')), 21)
                + _normalize_to_main(_to_float(by_karat.get('22k')), 22)
                + _normalize_to_main(_to_float(by_karat.get('24k')), 24)
            )

        def _safe_ledger_balance_by_karat(safe_id: int) -> dict:
            # Use SQL aggregates for performance.
            sign = case(
                (SafeBoxTransaction.direction == 'in', 1.0),
                else_=-1.0,
            )
            sums = (
                db.session.query(
                    func.coalesce(func.sum(SafeBoxTransaction.weight_18k * sign), 0.0).label('b18'),
                    func.coalesce(func.sum(SafeBoxTransaction.weight_21k * sign), 0.0).label('b21'),
                    func.coalesce(func.sum(SafeBoxTransaction.weight_22k * sign), 0.0).label('b22'),
                    func.coalesce(func.sum(SafeBoxTransaction.weight_24k * sign), 0.0).label('b24'),
                )
                .filter(SafeBoxTransaction.safe_box_id == safe_id)
                .filter(SafeBoxTransaction.created_at <= end_dt)
                .first()
            )

            by_karat = {
                '18k': round(_to_float(getattr(sums, 'b18', 0.0)), 3),
                '21k': round(_to_float(getattr(sums, 'b21', 0.0)), 3),
                '22k': round(_to_float(getattr(sums, 'b22', 0.0)), 3),
                '24k': round(_to_float(getattr(sums, 'b24', 0.0)), 3),
            }
            return {
                'by_karat': by_karat,
                'total_main_karat': round(_total_main_from_by_karat(by_karat), 3),
                'main_karat': int(main_karat),
            }

        def _account_balance_by_karat(account_id: int) -> dict:
            if not account_id:
                by_karat = {'18k': 0.0, '21k': 0.0, '22k': 0.0, '24k': 0.0}
                return {
                    'by_karat': by_karat,
                    'total_main_karat': 0.0,
                    'main_karat': int(main_karat),
                }

            sums = (
                db.session.query(
                    func.coalesce(func.sum(JournalEntryLine.debit_18k), 0.0).label('d18'),
                    func.coalesce(func.sum(JournalEntryLine.credit_18k), 0.0).label('c18'),
                    func.coalesce(func.sum(JournalEntryLine.debit_21k), 0.0).label('d21'),
                    func.coalesce(func.sum(JournalEntryLine.credit_21k), 0.0).label('c21'),
                    func.coalesce(func.sum(JournalEntryLine.debit_22k), 0.0).label('d22'),
                    func.coalesce(func.sum(JournalEntryLine.credit_22k), 0.0).label('c22'),
                    func.coalesce(func.sum(JournalEntryLine.debit_24k), 0.0).label('d24'),
                    func.coalesce(func.sum(JournalEntryLine.credit_24k), 0.0).label('c24'),
                )
                .join(JournalEntry)
                .filter(JournalEntryLine.account_id == account_id)
                .filter(JournalEntry.date <= end_date)
                .first()
            )

            b18 = _to_float(getattr(sums, 'd18', 0.0)) - _to_float(getattr(sums, 'c18', 0.0))
            b21 = _to_float(getattr(sums, 'd21', 0.0)) - _to_float(getattr(sums, 'c21', 0.0))
            b22 = _to_float(getattr(sums, 'd22', 0.0)) - _to_float(getattr(sums, 'c22', 0.0))
            b24 = _to_float(getattr(sums, 'd24', 0.0)) - _to_float(getattr(sums, 'c24', 0.0))

            by_karat = {
                '18k': round(b18, 3),
                '21k': round(b21, 3),
                '22k': round(b22, 3),
                '24k': round(b24, 3),
            }
            return {
                'by_karat': by_karat,
                'total_main_karat': round(_total_main_from_by_karat(by_karat), 3),
                'main_karat': int(main_karat),
            }

        def _variance(a: dict, b: dict) -> dict:
            by_karat = {
                '18k': round(_to_float(a.get('18k')) - _to_float(b.get('18k')), 3),
                '21k': round(_to_float(a.get('21k')) - _to_float(b.get('21k')), 3),
                '22k': round(_to_float(a.get('22k')) - _to_float(b.get('22k')), 3),
                '24k': round(_to_float(a.get('24k')) - _to_float(b.get('24k')), 3),
            }
            total_main = round(_total_main_from_by_karat(by_karat), 3)
            return {
                'by_karat': by_karat,
                'total_main_karat': total_main,
                'main_karat': int(main_karat),
            }

        safes = (
            SafeBox.query
            .filter(SafeBox.safe_type == 'gold')
            .order_by(SafeBox.is_active.desc(), SafeBox.name.asc())
            .all()
        )

        rows = []
        balanced_count = 0
        total_variance_main = 0.0

        for sb in safes:
            safe_bal = _safe_ledger_balance_by_karat(int(sb.id))
            acc = Account.query.get(sb.account_id) if sb.account_id else None
            acc_bal = _account_balance_by_karat(int(sb.account_id) if sb.account_id else 0)

            var = _variance(safe_bal['by_karat'], acc_bal['by_karat'])

            # Consider balanced when variance is within a tiny tolerance.
            tol = 0.0005
            is_balanced = (
                abs(_to_float(var.get('total_main_karat'))) < tol
                and all(abs(_to_float(v)) < tol for v in (var.get('by_karat') or {}).values())
            )

            if is_balanced:
                balanced_count += 1
            total_variance_main += abs(_to_float(var.get('total_main_karat')))

            rows.append({
                'safe_box': {
                    'id': sb.id,
                    'name': sb.name,
                    'safe_type': sb.safe_type,
                    'karat': sb.karat,
                    'is_active': bool(sb.is_active),
                    'account_id': sb.account_id,
                    'account_number': acc.account_number if acc else None,
                    'account_name': acc.name if acc else None,
                },
                'safe_balance': safe_bal,
                'account_balance': acc_bal,
                'variance': var,
                'is_balanced': bool(is_balanced),
            })

        return jsonify({
            'report_type': 'gold_weight_trial_balance',
            'date': end_date.isoformat(),
            'main_karat': int(main_karat),
            'rows': rows,
            'summary': {
                'total_safe_boxes': len(rows),
                'balanced_safe_boxes': balanced_count,
                'unbalanced_safe_boxes': len(rows) - balanced_count,
                'total_abs_variance_main_karat': round(float(total_variance_main), 3),
            },
        }), 200

    except ValueError:
        return jsonify({'error': 'صيغة التاريخ غير صحيحة. استخدم YYYY-MM-DD'}), 400
    except Exception as e:
        print(f"❌ Error generating gold weight trial balance by safe box: {e}")
        return jsonify({'error': f'فشل إنشاء ميزان مراجعة الأوزان: {str(e)}'}), 500


@api.route('/reports/income-statement/cash', methods=['GET'])
@require_permission('reports.financial')
def get_cash_income_statement():
    """
    قائمة الدخل المالية (النقدي)
    
    تعرض الإيرادات والمصروفات من الشجرة المالية فقط
    
    Query Parameters:
    - start_date: تاريخ البداية (YYYY-MM-DD)
    - end_date: تاريخ النهاية (YYYY-MM-DD)
    
    Returns:
    - revenues: الإيرادات (حسابات 40x)
    - expenses: المصروفات (حسابات 50x)
    - net_income: صافي الربح بالريال
    """
    try:
        start_date_str = request.args.get('start_date')
        end_date_str = request.args.get('end_date')

        if not start_date_str or not end_date_str:
            return jsonify({'error': 'يجب تحديد تاريخ البداية والنهاية'}), 400

        start_date = datetime.fromisoformat(start_date_str).date()
        end_date = datetime.fromisoformat(end_date_str).date()

        # ---------- صافي المبيعات النقدية ----------
        revenue_accounts = Account.query.filter(
            Account.transaction_type.in_(['cash', 'both']),
            Account.account_number.like('4%')
        ).all()

        revenues_data = []
        total_revenue = 0.0
        for account in revenue_accounts:
            lines = JournalEntryLine.query.join(JournalEntry).filter(
                JournalEntryLine.account_id == account.id,
                JournalEntry.date >= start_date,
                JournalEntry.date <= end_date
            ).all()

            credit_sum = sum(line.cash_credit or 0 for line in lines)
            debit_sum = sum(line.cash_debit or 0 for line in lines)
            net_revenue = credit_sum - debit_sum

            if abs(net_revenue) > 0.01:
                revenues_data.append({
                    'account_number': account.account_number,
                    'account_name': account.name,
                    'amount': round(net_revenue, 2)
                })
                total_revenue += net_revenue

        # ---------- تكلفة المبيعات النقدية (بدون المصنعية) ----------
        # نجمع أوزان الأصناف المباعه من karat lines، ثم نضرب كل عيار في متوسط سعر الشراء لذلك العيار
        sold_weights = {}
        cost_of_sales_details = []
        total_cost_of_sales = 0.0

        for karat in (18, 21, 22, 24):
            sold_weight = db.session.query(func.coalesce(func.sum(InvoiceKaratLine.weight_grams), 0.0)).join(Invoice).filter(
                InvoiceKaratLine.karat == str(karat),
                Invoice.date >= start_date,
                Invoice.date <= end_date,
                Invoice.is_posted == True,
                Invoice.invoice_type.in_(['بيع'])
            ).scalar() or 0.0

            if sold_weight and sold_weight > 0:
                avg_cost = get_inventory_average_cost(karat) or 0.0
                cost = round(sold_weight * avg_cost, 2)
                sold_weights[str(karat)] = sold_weight
                cost_of_sales_details.append({
                    'karat': str(karat),
                    'weight_grams': round(sold_weight, 3),
                    'avg_cost_per_gram': round(avg_cost, 2),
                    'cost': cost
                })
                total_cost_of_sales += cost

        # ---------- المصاريف: أجور المصنعية + المصاريف التشغيلية ----------
        # حساب أجور المصنعية المسجلة كمصروف (الحساب المخصص أو الحساب العام 51)
        manufacturing_wage_expense_acc_id = (
            get_account_id_for_mapping('بيع', 'manufacturing_wage')
            or _ensure_manufacturing_wage_expense_account()
            or get_account_id_for_mapping('بيع', 'operating_expenses')
            or get_account_id_by_number('51')
        )

        manufacturing_wage_amount = 0.0
        manufacturing_wage_details = []
        if manufacturing_wage_expense_acc_id:
            lines = JournalEntryLine.query.join(JournalEntry).filter(
                JournalEntryLine.account_id == manufacturing_wage_expense_acc_id,
                JournalEntry.date >= start_date,
                JournalEntry.date <= end_date
            ).all()
            debit_sum = sum(line.cash_debit or 0 for line in lines)
            credit_sum = sum(line.cash_credit or 0 for line in lines)
            manufacturing_wage_amount = round(debit_sum - credit_sum, 2)
            if abs(manufacturing_wage_amount) > 0.01:
                acc = Account.query.get(manufacturing_wage_expense_acc_id)
                manufacturing_wage_details.append({
                    'account_number': acc.account_number if acc else None,
                    'account_name': acc.name if acc else 'مصروفات مصنعية',
                    'amount': manufacturing_wage_amount
                })

        # حساب المصاريف التشغيلية (حسابات 5x) باستثناء تكلفة المبيعات (50x) وأي حساب مصروف مصنعية تم احتسابه أعلاه
        expense_accounts = Account.query.filter(
            Account.transaction_type.in_(['cash', 'both']),
            Account.account_number.like('5%')
        ).all()

        operating_expenses_details = []
        total_operating_expenses = 0.0
        for account in expense_accounts:
            # استبعد حساب 50x (تكلفة المبيعات) لأننا حسبناها أعلاه
            if (account.account_number or '').startswith('50'):
                continue
            if manufacturing_wage_expense_acc_id and account.id == manufacturing_wage_expense_acc_id:
                # تم حسابه بالفعل
                continue

            lines = JournalEntryLine.query.join(JournalEntry).filter(
                JournalEntryLine.account_id == account.id,
                JournalEntry.date >= start_date,
                JournalEntry.date <= end_date
            ).all()
            debit_sum = sum(line.cash_debit or 0 for line in lines)
            credit_sum = sum(line.cash_credit or 0 for line in lines)
            net_exp = round(debit_sum - credit_sum, 2)
            if abs(net_exp) > 0.01:
                operating_expenses_details.append({
                    'account_number': account.account_number,
                    'account_name': account.name,
                    'amount': net_exp
                })
                total_operating_expenses += net_exp

        total_expenses = round((manufacturing_wage_amount or 0.0) + (total_operating_expenses or 0.0), 2)

        # ---------- المجاميع النهائية ----------
        gross_profit = round(total_revenue - total_cost_of_sales, 2)
        net_profit = round(gross_profit - total_expenses, 2)
        profit_margin_pct = round((net_profit / total_revenue * 100) if total_revenue > 0 else 0.0, 2)

        return jsonify({
            'report_type': 'income_statement_cash',
            'start_date': start_date_str,
            'end_date': end_date_str,

            # 1️⃣ صافي المبيعات
            'net_sales': {
                'total': round(total_revenue, 2),
                'details': sorted(revenues_data, key=lambda x: x['account_number'])
            },

            # 2️⃣ تكلفة المبيعات (الوزن × متوسط سعر الشراء للجرام) - بدون المصنعية
            'cost_of_sales': {
                'total': round(total_cost_of_sales, 2),
                'details': sorted(cost_of_sales_details, key=lambda x: x['karat'])
            },

            # 3️⃣ الربح النقدي (إجمالي)
            'gross_profit': {
                'total': gross_profit,
                'note': 'الربح الإجمالي = صافي المبيعات - تكلفة المبيعات'
            },

            # 4️⃣ المصاريف (أجور المصنعية + المصاريف التشغيلية)
            'expenses': {
                'manufacturing_wages': {
                    'total': manufacturing_wage_amount,
                    'details': manufacturing_wage_details
                },
                'operating_expenses': {
                    'total': round(total_operating_expenses, 2),
                    'details': sorted(operating_expenses_details, key=lambda x: x['account_number'])
                },
                'total': total_expenses
            },

            # 5️⃣ صافي الربح
            'net_profit': {
                'total': net_profit
            },

            # 6️⃣ هامش الربح
            'profit_margin_pct': profit_margin_pct
        }), 200

    except Exception as e:
        print(f"❌ Error generating cash income statement: {e}")
        return jsonify({'error': f'فشل إنشاء قائمة الدخل النقدية: {str(e)}'}), 500


@api.route('/reports/income-statement/gold', methods=['GET'])
@require_permission('reports.financial')
def get_gold_income_statement():
    """
    قائمة الدخل الوزنية (الذهب)
    
    تعرض الإيرادات والمصروفات من الشجرة الوزنية فقط
    
    Query Parameters:
    - start_date: تاريخ البداية (YYYY-MM-DD)
    - end_date: تاريخ النهاية (YYYY-MM-DD)
    
    Returns:
    - revenues: الإيرادات بالجرامات (حسابات 4Wx)
    - expenses: المصروفات بالجرامات (حسابات 5Wx)
    - net_profit_grams: صافي الربح بالجرامات
    """
    try:
        from config import MAIN_KARAT
        
        start_date_str = request.args.get('start_date')
        end_date_str = request.args.get('end_date')
        
        if not start_date_str or not end_date_str:
            return jsonify({'error': 'يجب تحديد تاريخ البداية والنهاية'}), 400
        
        start_date = datetime.fromisoformat(start_date_str).date()
        end_date = datetime.fromisoformat(end_date_str).date()
        main_karat = MAIN_KARAT or 21
        
        # جلب حسابات الإيرادات (74xx) من شجرة المذكرة
        revenue_accounts = Account.query.filter(
            Account.transaction_type == 'gold',
            Account.account_number.like('74%')
        ).all()
        
        # جلب حسابات المصروفات (75xx) من شجرة المذكرة
        expense_accounts = Account.query.filter(
            Account.transaction_type == 'gold',
            Account.account_number.like('75%')
        ).all()
        
        revenues_data = []
        total_revenue_grams = 0.0
        
        for account in revenue_accounts:
            lines = JournalEntryLine.query.join(JournalEntry).filter(
                JournalEntryLine.account_id == account.id,
                JournalEntry.date >= start_date,
                JournalEntry.date <= end_date
            ).all()
            
            # جمع الأوزان من جميع الأعيرة (محولة للعيار الرئيسي)
            credit_18k = sum(line.credit_18k or 0 for line in lines) * (18 / main_karat)
            credit_21k = sum(line.credit_21k or 0 for line in lines) * (21 / main_karat)
            credit_22k = sum(line.credit_22k or 0 for line in lines) * (22 / main_karat)
            credit_24k = sum(line.credit_24k or 0 for line in lines) * (24 / main_karat)
            
            debit_18k = sum(line.debit_18k or 0 for line in lines) * (18 / main_karat)
            debit_21k = sum(line.debit_21k or 0 for line in lines) * (21 / main_karat)
            debit_22k = sum(line.debit_22k or 0 for line in lines) * (22 / main_karat)
            debit_24k = sum(line.debit_24k or 0 for line in lines) * (24 / main_karat)
            
            total_credit = credit_18k + credit_21k + credit_22k + credit_24k
            total_debit = debit_18k + debit_21k + debit_22k + debit_24k
            net_revenue = total_credit - total_debit  # الإيرادات دائنة
            
            if abs(net_revenue) > 0.001:
                revenues_data.append({
                    'account_number': account.account_number,
                    'account_name': account.name,
                    'amount_grams': round(net_revenue, 3)
                })
                total_revenue_grams += net_revenue
        
        expenses_data = []
        total_expense_grams = 0.0
        
        for account in expense_accounts:
            lines = JournalEntryLine.query.join(JournalEntry).filter(
                JournalEntryLine.account_id == account.id,
                JournalEntry.date >= start_date,
                JournalEntry.date <= end_date
            ).all()
            
            # جمع الأوزان من جميع الأعيرة (محولة للعيار الرئيسي)
            debit_18k = sum(line.debit_18k or 0 for line in lines) * (18 / main_karat)
            debit_21k = sum(line.debit_21k or 0 for line in lines) * (21 / main_karat)
            debit_22k = sum(line.debit_22k or 0 for line in lines) * (22 / main_karat)
            debit_24k = sum(line.debit_24k or 0 for line in lines) * (24 / main_karat)
            
            credit_18k = sum(line.credit_18k or 0 for line in lines) * (18 / main_karat)
            credit_21k = sum(line.credit_21k or 0 for line in lines) * (21 / main_karat)
            credit_22k = sum(line.credit_22k or 0 for line in lines) * (22 / main_karat)
            credit_24k = sum(line.credit_24k or 0 for line in lines) * (24 / main_karat)
            
            total_debit = debit_18k + debit_21k + debit_22k + debit_24k
            total_credit = credit_18k + credit_21k + credit_22k + credit_24k
            net_expense = total_debit - total_credit  # المصروفات مدينة
            
            if abs(net_expense) > 0.001:
                expenses_data.append({
                    'account_number': account.account_number,
                    'account_name': account.name,
                    'amount_grams': round(net_expense, 3)
                })
                total_expense_grams += net_expense
        
        net_profit_grams = total_revenue_grams - total_expense_grams
        net_margin_pct = (net_profit_grams / total_revenue_grams * 100) if total_revenue_grams > 0 else 0.0
        
        return jsonify({
            'report_type': 'income_statement_gold',
            'start_date': start_date_str,
            'end_date': end_date_str,
            'main_karat': main_karat,
            'revenues': {
                'details': revenues_data,
                'total_grams': round(total_revenue_grams, 3)
            },
            'expenses': {
                'details': expenses_data,
                'total_grams': round(total_expense_grams, 3)
            },
            'net_profit_grams': round(net_profit_grams, 3),
            'net_margin_pct': round(net_margin_pct, 2)
        }), 200
        
    except Exception as e:
        print(f"❌ Error generating gold income statement: {e}")
        return jsonify({'error': f'فشل إنشاء قائمة الدخل الوزنية: {str(e)}'}), 500


@api.route('/dashboard/summary-debug', methods=['GET'])
@require_permission('admin')
def get_dashboard_summary_debug():
    """Debug endpoint: run _build_inv_summary for month and return raw result + any errors."""
    import traceback as _tb
    from datetime import datetime as _dt, timedelta as _td
    now = _dt.now()
    today_start = _dt.combine(now.date(), _dt.min.time())
    tomorrow_start = today_start + _td(days=1)
    month_start = _dt(now.year, now.month, 1)
    year_start = _dt(now.year, 1, 1)

    sale_types = {'بيع': 1, 'sell': 1, 'sale': 1, 'مرتجع بيع': -1}
    purchase_types = {'شراء': 1, 'شراء من عميل': 1, 'مرتجع شراء': -1, 'مرتجع شراء (مورد)': -1}

    def _try_summary(inv_types_dict, start, end):
        try:
            inv_types = [str(t).strip() for t in inv_types_dict.keys() if str(t).strip()]
            q = (
                Invoice.query
                .filter(Invoice.invoice_type.in_(inv_types))
                .filter(Invoice.is_posted.is_(True))
                .filter(Invoice.date >= start)
                .filter(Invoice.date < end)
            )
            rows = q.all()
            return {'docs': len(rows), 'total': sum(float(i.total or 0) for i in rows), 'error': None}
        except Exception as e:
            return {'docs': None, 'total': None, 'error': str(e), 'trace': _tb.format_exc()}

    return jsonify({
        'now': now.isoformat(),
        'month_start': month_start.isoformat(),
        'today_start': today_start.isoformat(),
        'tomorrow_start': tomorrow_start.isoformat(),
        'year_start': year_start.isoformat(),
        'today_sales': _try_summary(sale_types, today_start, tomorrow_start),
        'month_sales': _try_summary(sale_types, month_start, tomorrow_start),
        'year_sales': _try_summary(sale_types, year_start, tomorrow_start),
        'month_purchases': _try_summary(purchase_types, month_start, tomorrow_start),
    })


@api.route('/dashboard/admin', methods=['GET'])
@require_permission('reports.financial')
def get_admin_dashboard():
    """Admin dashboard aggregates for KPIs, charts, and alerts.

    Response shape (stable contract for Flutter):
      - kpis: cash_balance, gold_by_karat, gold_pure_24k, sales_today
      - series: last_7_days_sales (net_value/net_weight per day)
      - alerts: last_shift_closing (cash_diff/gold_pure_24k_diff)
    """
    from models import SafeBox, SafeBoxTransaction, Invoice, AuditLog, GoldPrice, SystemAlert

    now = datetime.now()
    today_start = datetime.combine(now.date(), datetime.min.time())
    tomorrow_start = today_start + timedelta(days=1)

    # --- Safe boxes summary (Account-derived balances; aligned with SafeBox details UI) ---
    main_karat = current_app.config.get('MAIN_KARAT', 21)
    cash_balance = 0.0
    gold_18k = 0.0
    gold_21k = 0.0
    gold_22k = 0.0
    gold_24k = 0.0

    # --- Sales today (posted only) ---
    sale_types = {
        'بيع': 1,
        'sell': 1,
        'sale': 1,
        'مرتجع بيع': -1,
    }
    today_invoices = (
        Invoice.query
        .filter(Invoice.invoice_type.in_(list(sale_types.keys())))
        .filter(Invoice.is_posted.is_(True))
        .filter(Invoice.date >= today_start)
        .filter(Invoice.date < tomorrow_start)
        .all()
    )

    sales_today_value = 0.0
    sales_today_weight = 0.0
    for inv in today_invoices:
        sign = sale_types.get(inv.invoice_type, 1)
        sales_today_value += float(inv.total or 0.0) * sign
        sales_today_weight += float(inv.total_weight or 0.0) * sign

    # --- Last 7 days sales series (posted only) ---
    start_7 = today_start - timedelta(days=6)
    series_invoices = (
        Invoice.query
        .filter(Invoice.invoice_type.in_(list(sale_types.keys())))
        .filter(Invoice.is_posted.is_(True))
        .filter(Invoice.date >= start_7)
        .filter(Invoice.date < tomorrow_start)
        .order_by(Invoice.date.asc())
        .all()
    )

    by_day = {}
    for i in range(7):
        day = (start_7 + timedelta(days=i)).date()
        key = day.isoformat()
        by_day[key] = {
            'period': key,
            'net_value': 0.0,
            'net_weight': 0.0,
            'documents': 0,
        }

    for inv in series_invoices:
        sign = sale_types.get(inv.invoice_type, 1)
        period_key = (inv.date.date() if inv.date else now.date()).isoformat()
        bucket = by_day.get(period_key)
        if bucket is None:
            continue
        bucket['documents'] += 1
        bucket['net_value'] += float(inv.total or 0.0) * sign
        bucket['net_weight'] += float(inv.total_weight or 0.0) * sign

    last_7_days_sales = list(by_day.values())

    # --- Valuation (presentation-only): pure 24k grams * raw spot per gram (24k) ---
    spot_price_24k_per_gram = None
    spot_price_timestamp = None
    try:
        latest = GoldPrice.query.order_by(GoldPrice.date.desc()).first()
        if latest and latest.price:
            spot_price_24k_per_gram = (float(latest.price) / 31.1035) * 3.75
            spot_price_timestamp = latest.date.isoformat() if latest.date else None
    except Exception:
        spot_price_24k_per_gram = None
        spot_price_timestamp = None

    inventory_value = None
    if spot_price_24k_per_gram is not None:
        try:
            inventory_value = float(gold_pure_24k) * float(spot_price_24k_per_gram)
        except Exception:
            inventory_value = None

    # --- Critical alerts (unreviewed) ---
    critical_unreviewed_count = 0
    critical_latest = None
    try:
        critical_unreviewed_count = (
            SystemAlert.query.filter(SystemAlert.severity == 'critical')
            .filter(SystemAlert.is_reviewed.is_(False))
            .count()
        )
        critical_latest = (
            SystemAlert.query.filter(SystemAlert.severity == 'critical')
            .filter(SystemAlert.is_reviewed.is_(False))
            .order_by(SystemAlert.created_at.desc())
            .first()
        )
        critical_latest = critical_latest.to_dict() if critical_latest else None
    except Exception:
        critical_unreviewed_count = 0
        critical_latest = None

    # --- Alerts: last shift closing (system-wide) ---
    last_shift_alert = None
    try:
        last_close = (
            AuditLog.query.filter_by(action='shift_closing', success=True)
            .order_by(AuditLog.timestamp.desc())
            .first()
        )
        if last_close and last_close.details:
            try:
                details = (
                    json.loads(last_close.details)
                    if isinstance(last_close.details, str)
                    else (last_close.details or {})
                )
            except Exception:
                details = {}

            cash_diff = None
            try:
                cash_diff = float(((details.get('totals') or {}).get('total_difference')))
            except Exception:
                cash_diff = None

            gold_pure_diff = None
            try:
                gold_pure_diff = float(
                    (((details.get('gold') or {}).get('pure_24k') or {}).get('difference'))
                )
            except Exception:
                gold_pure_diff = None

            last_shift_alert = {
                'entity_number': getattr(last_close, 'entity_number', None),
                'timestamp': last_close.timestamp.isoformat()
                if getattr(last_close, 'timestamp', None)
                else None,
                'user_name': getattr(last_close, 'user_name', None),
                'cash_difference': cash_diff,
                'gold_pure_24k_difference': gold_pure_diff,
            }
    except Exception:
        last_shift_alert = None

    # --- Purchases today (posted only) ---
    # Include both supplier purchases and scrap purchases from customers,
    # and include return variants used in production.
    purchase_types = {
        'شراء': 1,
        'شراء من عميل': 1,
        'مرتجع شراء': -1,
        'مرتجع شراء (مورد)': -1,
    }
    today_purchases = (
        Invoice.query
        .filter(Invoice.invoice_type.in_(list(purchase_types.keys())))
        .filter(Invoice.is_posted.is_(True))
        .filter(Invoice.date >= today_start)
        .filter(Invoice.date < tomorrow_start)
        .all()
    )

    purchases_today_value = 0.0
    purchases_today_weight = 0.0
    for inv in today_purchases:
        sign = purchase_types.get(inv.invoice_type, 1)
        purchases_today_value += float(inv.total or 0.0) * sign
        purchases_today_weight += float(inv.total_weight or 0.0) * sign

    # --- Last 7 days purchases series (posted only) ---
    purchases_series = (
        Invoice.query
        .filter(Invoice.invoice_type.in_(list(purchase_types.keys())))
        .filter(Invoice.is_posted.is_(True))
        .filter(Invoice.date >= start_7)
        .filter(Invoice.date < tomorrow_start)
        .order_by(Invoice.date.asc())
        .all()
    )

    purchases_by_day = {}
    for i in range(7):
        day = (start_7 + timedelta(days=i)).date()
        key = day.isoformat()
        purchases_by_day[key] = {
            'period': key,
            'net_value': 0.0,
            'net_weight': 0.0,
            'documents': 0,
        }

    for inv in purchases_series:
        sign = purchase_types.get(inv.invoice_type, 1)
        period_key = (inv.date.date() if inv.date else now.date()).isoformat()
        bucket = purchases_by_day.get(period_key)
        if bucket is None:
            continue
        bucket['documents'] += 1
        bucket['net_value'] += float(inv.total or 0.0) * sign
        bucket['net_weight'] += float(inv.total_weight or 0.0) * sign

    last_7_days_purchases = list(purchases_by_day.values())

    # --- Gold equivalent in main karat (from account-derived balances) ---
    gold_equivalent_main_karat = 0.0
    try:
        mk = float(main_karat or 21)
        if mk <= 0:
            mk = 21.0
        gold_equivalent_main_karat = (
            (gold_18k * (18.0 / mk))
            + gold_21k
            + (gold_22k * (22.0 / mk))
            + (gold_24k * (24.0 / mk))
        )
    except Exception:
        gold_equivalent_main_karat = 0.0

    # --- Price Intelligence: Average cost vs market price ---
    from models import Item
    avg_cost_per_gram = None
    try:
        # Calculate weighted average cost from inventory items
        items_with_cost = (
            Item.query
            .filter(Item.is_active.is_(True))
            .filter(Item.weight > 0)
            .all()
        )
        total_cost = 0.0
        total_weight_for_cost = 0.0
        for item in items_with_cost:
            item_weight = float(item.weight or 0.0)
            item_karat = int(item.karat or 21)
            # Convert to 24k equivalent for fair comparison
            weight_24k = item_weight * (item_karat / 24.0)
            # Use purchase price or calculate from gold price
            item_cost = float(item.purchase_price or 0.0)
            if item_cost > 0 and item_weight > 0:
                total_cost += item_cost
                total_weight_for_cost += weight_24k
        
        if total_weight_for_cost > 0:
            avg_cost_per_gram = total_cost / total_weight_for_cost
    except Exception:
        avg_cost_per_gram = None

    # Calculate profit margin
    profit_margin = None
    if avg_cost_per_gram and spot_price_24k_per_gram and avg_cost_per_gram > 0:
        profit_margin = ((spot_price_24k_per_gram - avg_cost_per_gram) / avg_cost_per_gram) * 100

    # --- Liquidity Coverage (7 days) ---
    from models import Customer
    payables_due_7_days = 0.0
    receivables_due_7_days = 0.0
    try:
        # Get suppliers with credit balances (we owe them)
        suppliers = Customer.query.filter(Customer.customer_type == 'مورد').all()
        for supplier in suppliers:
            balance = float(getattr(supplier, 'balance', 0) or 0)
            if balance < 0:  # Negative balance means we owe them
                payables_due_7_days += abs(balance)
        
        # Get customers with debit balances (they owe us)
        customers = Customer.query.filter(Customer.customer_type == 'عميل').all()
        for customer in customers:
            balance = float(getattr(customer, 'balance', 0) or 0)
            if balance > 0:  # Positive balance means they owe us
                receivables_due_7_days += balance
    except Exception:
        payables_due_7_days = 0.0
        receivables_due_7_days = 0.0

    liquidity_coverage_ratio = None
    if payables_due_7_days > 0:
        liquidity_coverage_ratio = (cash_balance / payables_due_7_days) * 100

    # --- Safe boxes summary ---
    # مصدر الرصيد الرسمي الوحيد: safe_box_balances_bulk (دفتر الأستاذ مباشرة)
    # -- نفس الدالة التي تستخدمها /safe-boxes/balances و/safe-boxes/<id>/balance،
    # فلا يبقى أي مكان يحسب رصيد خزينة بمنطق مستقل خاص به.
    safe_boxes_summary = []
    try:
        safe_boxes = SafeBox.query.filter(SafeBox.is_active.is_(True)).all()
        balances_by_id = safe_box_balances_bulk(safe_boxes, main_karat=main_karat)
        for sb in safe_boxes:
            bal = balances_by_id.get(sb.id) or {
                'cash': 0.0,
                'weight': {'18k': 0.0, '21k': 0.0, '22k': 0.0, '24k': 0.0, 'total': 0.0},
            }
            weight = bal['weight']
            safe_boxes_summary.append({
                'id': sb.id,
                'name': sb.name,
                'safe_type': sb.safe_type,
                'balance_cash': bal['cash'],
                # Keep legacy single-field gold balance used by older UI.
                'balance_gold_21k': weight.get('21k', 0.0),
                # New: detailed weights per karat (ledger-based) for richer UI.
                'weight_balance': {k: v for k, v in weight.items() if k != 'total'},
                'total_weight_main_karat': weight.get('total', 0.0),
                'main_karat': int(main_karat or 21),
            })
    except Exception:
        safe_boxes_summary = []

    # Roll up account-derived totals for KPIs and liquidity.
    try:
        cash_balance = 0.0
        gold_18k = gold_21k = gold_22k = gold_24k = 0.0
        for sb in safe_boxes_summary:
            st = (sb.get('safe_type') or '').strip()
            if st in ('cash', 'bank', 'check'):
                cash_balance += float(sb.get('balance_cash') or 0.0)
            if st == 'gold':
                wb = sb.get('weight_balance') if isinstance(sb.get('weight_balance'), dict) else {}
                gold_18k += float(wb.get('18k') or 0.0)
                gold_21k += float(wb.get('21k') or 0.0)
                gold_22k += float(wb.get('22k') or 0.0)
                gold_24k += float(wb.get('24k') or 0.0)
    except Exception:
        cash_balance = 0.0
        gold_18k = gold_21k = gold_22k = gold_24k = 0.0

    gold_pure_24k = (
        (gold_18k * (18.0 / 24.0))
        + (gold_21k * (21.0 / 24.0))
        + (gold_22k * (22.0 / 24.0))
        + gold_24k
    )

    try:
        mk = float(main_karat or 21)
        if mk <= 0:
            mk = 21.0
        gold_equivalent_main_karat = (
            (gold_18k * (18.0 / mk))
            + gold_21k
            + (gold_22k * (22.0 / mk))
            + (gold_24k * (24.0 / mk))
        )
    except Exception:
        gold_equivalent_main_karat = 0.0

    # --- Unposted invoices count ---
    unposted_invoices_count = 0
    try:
        unposted_invoices_count = Invoice.query.filter(Invoice.is_posted.is_(False)).count()
    except Exception:
        unposted_invoices_count = 0

    # --- Yesterday comparison ---
    yesterday_start = today_start - timedelta(days=1)
    yesterday_sales_value = 0.0
    yesterday_purchases_value = 0.0
    yesterday_sales_weight = 0.0
    yesterday_purchases_weight = 0.0
    try:
        yesterday_sales = (
            Invoice.query
            .filter(Invoice.invoice_type.in_(list(sale_types.keys())))
            .filter(Invoice.is_posted.is_(True))
            .filter(Invoice.date >= yesterday_start)
            .filter(Invoice.date < today_start)
            .all()
        )
        for inv in yesterday_sales:
            sign = sale_types.get(inv.invoice_type, 1)
            yesterday_sales_value += float(inv.total or 0.0) * sign
            yesterday_sales_weight += float(inv.total_weight or 0.0) * sign
        
        yesterday_purchases = (
            Invoice.query
            .filter(Invoice.invoice_type.in_(list(purchase_types.keys())))
            .filter(Invoice.is_posted.is_(True))
            .filter(Invoice.date >= yesterday_start)
            .filter(Invoice.date < today_start)
            .all()
        )
        for inv in yesterday_purchases:
            sign = purchase_types.get(inv.invoice_type, 1)
            yesterday_purchases_value += float(inv.total or 0.0) * sign
            yesterday_purchases_weight += float(inv.total_weight or 0.0) * sign
    except Exception:
        yesterday_sales_value = 0.0
        yesterday_purchases_value = 0.0
        yesterday_sales_weight = 0.0
        yesterday_purchases_weight = 0.0

    # Calculate change percentages
    sales_change_pct = None
    if yesterday_sales_value > 0:
        sales_change_pct = ((sales_today_value - yesterday_sales_value) / yesterday_sales_value) * 100
    
    purchases_change_pct = None
    if yesterday_purchases_value > 0:
        purchases_change_pct = ((purchases_today_value - yesterday_purchases_value) / yesterday_purchases_value) * 100

    # Weight-based change percentages (preferred for this POS)
    sales_change_pct_weight = None
    if abs(yesterday_sales_weight) > 0:
        sales_change_pct_weight = ((sales_today_weight - yesterday_sales_weight) / yesterday_sales_weight) * 100

    purchases_change_pct_weight = None
    if abs(yesterday_purchases_weight) > 0:
        purchases_change_pct_weight = ((purchases_today_weight - yesterday_purchases_weight) / yesterday_purchases_weight) * 100

    # --- Net Financial Position (Cash + Gold Value) ---
    net_financial_position = cash_balance
    if spot_price_24k_per_gram and spot_price_24k_per_gram > 0:
        net_financial_position += gold_pure_24k * spot_price_24k_per_gram

    # --- Today's Profit Margin (Sales - Purchases) ---
    today_profit = sales_today_value - purchases_today_value
    today_profit_margin_pct = None
    if sales_today_value > 0:
        today_profit_margin_pct = (today_profit / sales_today_value) * 100

    # --- Yesterday Profit (for trend comparison) ---
    yesterday_profit = yesterday_sales_value - yesterday_purchases_value
    today_profit_vs_yesterday_pct = None
    if abs(yesterday_profit) > 0.01:
        today_profit_vs_yesterday_pct = ((today_profit - yesterday_profit) / abs(yesterday_profit)) * 100

    # --- Gold Price Change from Yesterday ---
    gold_price_change_pct = None
    try:
        yesterday_price = (
            GoldPrice.query
            .filter(GoldPrice.date < now.date())
            .order_by(GoldPrice.date.desc())
            .first()
        )
        if yesterday_price and yesterday_price.price and spot_price_24k_per_gram:
            yesterday_spot = (float(yesterday_price.price) / 31.1035) * 3.75
            if yesterday_spot > 0:
                gold_price_change_pct = ((spot_price_24k_per_gram - yesterday_spot) / yesterday_spot) * 100
    except Exception:
        gold_price_change_pct = None

    # --- Safe boxes with activity pulse (last 15 minutes) ---
    fifteen_mins_ago = now - timedelta(minutes=15)
    safe_boxes_enhanced = []
    try:
        for sb_data in safe_boxes_summary:
            sb_id = sb_data['id']
            # Check for recent activity
            recent_activity = (
                SafeBoxTransaction.query
                .filter(SafeBoxTransaction.safe_box_id == sb_id)
                .filter(SafeBoxTransaction.created_at >= fifteen_mins_ago)
                .first()
            )
            sb_data['has_recent_activity'] = recent_activity is not None
            safe_boxes_enhanced.append(sb_data)
    except Exception:
        safe_boxes_enhanced = safe_boxes_summary

    # --- Sensitive Operations (Last 5 important actions) ---
    sensitive_operations = []
    try:
        noise_actions = {
            'login_success', 'login_failed', 'logout',
            'forgot_password', 'forgot_username', 'password_reset_confirm',
        }

        recent_logs = (
            AuditLog.query
            .filter(AuditLog.success.is_(True))
            .filter(~AuditLog.action.in_(list(noise_actions)))
            .order_by(AuditLog.timestamp.desc())
            .limit(8)
            .all()
        )
        for log in recent_logs:
            op_desc = {
                # Shift closing
                'shift_closing': 'إغلاق وردية',
                # Posting/unposting
                'post_invoice': 'ترحيل فاتورة',
                'post': 'ترحيل',
                'post_batch': 'ترحيل دفعة',
                'unpost': 'إلغاء ترحيل',
                # Vouchers
                'approve_voucher': 'ترحيل سند',
                'cancel_voucher': 'إلغاء سند',
                'voucher_approve': 'اعتماد سند',
                'voucher_reject': 'رفض سند',
                'voucher_unapprove': 'إلغاء اعتماد سند',
                'batch_voucher_approve': 'اعتماد دفعة سندات',
                # Safety/ops
                'delete_voucher': 'حذف سند',
                'large_discount': 'خصم كبير',
                'create_invoice': 'إنشاء فاتورة',
            }.get(log.action, log.action)
            
            sensitive_operations.append({
                'action': log.action,
                'description': op_desc,
                'user_name': getattr(log, 'user_name', None) or 'غير معروف',
                'entity_type': getattr(log, 'entity_type', None),
                'entity_number': getattr(log, 'entity_number', None),
                'timestamp': log.timestamp.isoformat() if log.timestamp else None,
                'time_ago': _time_ago(log.timestamp, now) if log.timestamp else None,
            })
    except Exception:
        sensitive_operations = []

    # --- Critical Alert Bar (compact) ---
    critical_bar = []
    try:
        # 0) Count of unreviewed critical alerts (even if latest message missing)
        try:
            ccount = int(critical_unreviewed_count or 0)
        except Exception:
            ccount = 0

        if ccount > 0:
            critical_bar.append({
                'severity': 'critical',
                'message_ar': f"{ccount} تنبيهات حرجة بانتظار المراجعة",
                'message_en': f"{ccount} critical alerts pending review",
                'entity_type': 'SystemAlert',
                'entity_number': None,
            })

        # 1) Latest unreviewed critical system alert
        if isinstance(critical_latest, dict):
            msg = (critical_latest.get('message') or critical_latest.get('title') or '').strip()
            if msg:
                critical_bar.append({
                    'severity': 'critical',
                    'message_ar': msg,
                    'message_en': msg,
                    'entity_type': critical_latest.get('entity_type'),
                    'entity_number': critical_latest.get('entity_number'),
                })

        # 2) Shift closing diffs (when present)
        if isinstance(last_shift_alert, dict):
            cash_diff = last_shift_alert.get('cash_difference')
            gold_diff = last_shift_alert.get('gold_pure_24k_difference')
            entity_num = last_shift_alert.get('entity_number')
            try:
                cash_diff_f = float(cash_diff) if cash_diff is not None else 0.0
            except Exception:
                cash_diff_f = 0.0
            try:
                gold_diff_f = float(gold_diff) if gold_diff is not None else 0.0
            except Exception:
                gold_diff_f = 0.0

            if abs(gold_diff_f) > 0.001:
                critical_bar.append({
                    'severity': 'warning',
                    'message_ar': f"⚠️ يوجد فرق وزني (+/-{gold_diff_f:.3f} جم 24K) في إغلاق {entity_num or ''}".strip(),
                    'message_en': f"Weight difference ({gold_diff_f:+.3f} g 24K) in shift closing {entity_num or ''}".strip(),
                    'entity_type': 'ShiftClosing',
                    'entity_number': entity_num,
                })

            if abs(cash_diff_f) > 0.01:
                critical_bar.append({
                    'severity': 'warning',
                    'message_ar': f"⚠️ يوجد فرق نقدي ({cash_diff_f:+.2f}) في إغلاق {entity_num or ''}".strip(),
                    'message_en': f"Cash difference ({cash_diff_f:+.2f}) in shift closing {entity_num or ''}".strip(),
                    'entity_type': 'ShiftClosing',
                    'entity_number': entity_num,
                })

        # 3) Low bank balance (optional threshold)
        threshold = None
        try:
            raw_thr = os.getenv('BANK_LOW_BALANCE_THRESHOLD', '').strip()
            if raw_thr:
                threshold = float(raw_thr)
        except Exception:
            threshold = None

        if threshold is not None:
            for sb in safe_boxes_enhanced:
                if (sb.get('safe_type') or '') != 'bank':
                    continue
                try:
                    bal = float(sb.get('balance_cash') or 0.0)
                except Exception:
                    bal = 0.0
                if bal < threshold:
                    name = sb.get('name') or 'Bank'
                    critical_bar.append({
                        'severity': 'warning',
                        'message_ar': f"⚠️ رصيد {name} تحت الحد المسموح ({bal:.2f} < {threshold:.2f})",
                        'message_en': f"{name} balance below threshold ({bal:.2f} < {threshold:.2f})",
                        'entity_type': 'SafeBox',
                        'entity_number': None,
                    })

        # 4) Unposted invoices
        try:
            up = int(unposted_invoices_count or 0)
        except Exception:
            up = 0
        if up > 0:
            critical_bar.append({
                'severity': 'warning',
                'message_ar': f"⚠️ {up} فاتورة بانتظار الترحيل",
                'message_en': f"{up} invoices pending posting",
                'entity_type': 'Invoice',
                'entity_number': None,
            })
    except Exception:
        critical_bar = []

    # --- Liquidity breakdown (Cash vs Banks) ---
    cash_in_hand = 0.0
    cash_in_banks = 0.0
    try:
        for sb_data in safe_boxes_enhanced:
            if sb_data['safe_type'] == 'cash':
                cash_in_hand += sb_data['balance_cash']
            elif sb_data['safe_type'] == 'bank':
                cash_in_banks += sb_data['balance_cash']
    except Exception:
        pass

    # --- Sales / Purchases / Expenses Summary (today / this month / this year) ---
    sales_purchases_summary = {}
    try:
        from models import JournalEntryLine as JELine, JournalEntry as JE2, Account as AccModel

        month_start = datetime(now.year, now.month, 1)
        year_start = datetime(now.year, 1, 1)

        _summary_periods = {
            'today': (today_start, tomorrow_start),
            'month': (month_start, tomorrow_start),
            'year': (year_start, tomorrow_start),
        }

        _EMPTY_INV_SUMMARY = {
            'total_value': 0.0, 'total_weight': 0.0, 'docs': 0,
            'by_user': [], 'by_karat': [],
        }

        # Pre-load AppUser list once; avoids a full-table scan on every _build_inv_summary call.
        _cached_app_users = []
        try:
            from models import AppUser
            _cached_app_users = AppUser.query.all()
        except Exception:
            pass

        def _build_inv_summary(inv_types_dict, start, end, exclude_gold_type=None):
            # Uses Invoice.query directly (same proven pattern as today_invoices/series_invoices).
            try:
                inv_types = [str(t).strip() for t in inv_types_dict.keys() if str(t).strip()]
                if not inv_types:
                    return dict(_EMPTY_INV_SUMMARY)

                q = (
                    Invoice.query
                    .filter(Invoice.invoice_type.in_(inv_types))
                    .filter(Invoice.is_posted.is_(True))
                    .filter(Invoice.date >= start)
                    .filter(Invoice.date < end)
                )

                if exclude_gold_type:
                    try:
                        if _db_has_column('invoice', 'gold_type'):
                            q = q.filter(
                                or_(Invoice.gold_type.is_(None), Invoice.gold_type != exclude_gold_type)
                            )
                    except Exception:
                        pass

                rows = q.all()
                if not rows:
                    return dict(_EMPTY_INV_SUMMARY)

                total_value = 0.0
                total_weight = 0.0
                by_user = {}
                by_karat = {}
                sign_by_id = {}
                employee_ids = set()
                posted_keys = set()

                for inv in rows:
                    sign = float(inv_types_dict.get(inv.invoice_type, 1) or 1)
                    sign_by_id[inv.id] = sign
                    total_value += float(inv.total or 0) * sign
                    total_weight += float(inv.total_weight or 0) * sign
                    if inv.employee_id:
                        try:
                            employee_ids.add(int(inv.employee_id))
                        except Exception:
                            pass
                    posted_raw = str(inv.posted_by or '').strip().lower()
                    if posted_raw:
                        posted_keys.add(posted_raw)

                # Resolve display name: employee name > posted_by username fallback
                employee_name_by_id = {}
                if employee_ids:
                    try:
                        for emp in Employee.query.filter(Employee.id.in_(list(employee_ids))).all():
                            if emp.name:
                                employee_name_by_id[emp.id] = emp.name
                    except Exception:
                        pass

                posted_by_to_name = {}
                if posted_keys:
                    try:
                        for u in _cached_app_users:
                            if not u.employee_id:
                                continue
                            emp_name = employee_name_by_id.get(u.employee_id, '')
                            if not emp_name:
                                continue
                            uk = str(u.username or '').strip().lower()
                            if uk and uk in posted_keys:
                                posted_by_to_name[uk] = emp_name
                            fk = str(u.full_name or '').strip().lower()
                            if fk and fk in posted_keys and fk not in posted_by_to_name:
                                posted_by_to_name[fk] = emp_name
                    except Exception:
                        pass

                for inv in rows:
                    sign = float(sign_by_id.get(inv.id, 1) or 1)
                    v = float(inv.total or 0) * sign
                    w = float(inv.total_weight or 0) * sign
                    if inv.employee_id and inv.employee_id in employee_name_by_id:
                        user = employee_name_by_id[inv.employee_id]
                    else:
                        pk = str(inv.posted_by or '').strip().lower()
                        user = posted_by_to_name.get(pk) or str(inv.posted_by or 'غير معروف').strip() or 'غير معروف'
                    if user not in by_user:
                        by_user[user] = {'value': 0.0, 'weight': 0.0, 'docs': 0}
                    by_user[user]['value'] += v
                    by_user[user]['weight'] += w
                    by_user[user]['docs'] += 1

                # Karat breakdown via InvoiceItem
                try:
                    inv_ids = [inv.id for inv in rows]
                    for item in InvoiceItem.query.filter(InvoiceItem.invoice_id.in_(inv_ids)).all():
                        sign = float(sign_by_id.get(item.invoice_id, 1) or 1)
                        try:
                            k = f"{int(float(item.karat))}k" if item.karat not in (None, '') else '?'
                        except Exception:
                            k = '?'
                        if k not in by_karat:
                            by_karat[k] = {'weight': 0.0, 'value': 0.0}
                        by_karat[k]['weight'] += float(item.weight or 0) * sign
                        by_karat[k]['value'] += float(item.net or 0) * sign
                except Exception:
                    pass

                return {
                    'total_value': round(total_value, 2),
                    'total_weight': round(total_weight, 3),
                    'docs': len(rows),
                    'by_user': sorted(
                        [{'user': u, 'value': round(d['value'], 2), 'weight': round(d['weight'], 3), 'docs': d['docs']} for u, d in by_user.items()],
                        key=lambda x: -x['value']
                    ),
                    'by_karat': sorted(
                        [{'karat': k, 'weight': round(d['weight'], 3), 'value': round(d['value'], 2)} for k, d in by_karat.items() if d['weight'] != 0],
                        key=lambda x: -(x['weight'] or 0)
                    ),
                }
            except Exception as _inv_err:
                import traceback
                print(f'[dashboard] _build_inv_summary error: {_inv_err}')
                traceback.print_exc()
                return dict(_EMPTY_INV_SUMMARY)

        def _build_expenses_summary(start, end):
            try:
                exp_total = 0.0
                exp_by_account: dict = {}
                exp_rows = (
                    db.session.query(JELine, AccModel)
                    .join(AccModel, JELine.account_id == AccModel.id)
                    .join(JE2, JELine.journal_entry_id == JE2.id)
                    .filter(AccModel.account_number.like('5%'))
                    .filter(JE2.is_posted.is_(True))
                    .filter(JE2.date >= start)
                    .filter(JE2.date < end)
                    .all()
                )
                for line, acc in exp_rows:
                    amt = float(line.cash_debit or 0)
                    exp_total += amt
                    name = (acc.name or acc.account_number or '?').strip()
                    exp_by_account[name] = exp_by_account.get(name, 0.0) + amt
                return {
                    'total_value': round(exp_total, 2),
                    'by_account': sorted(
                        [{'account': a, 'value': round(v, 2)} for a, v in exp_by_account.items() if v > 0],
                        key=lambda x: -x['value']
                    ),
                }
            except Exception:
                return {'total_value': 0.0, 'by_account': []}

        def _build_scrap_summary(start, end):
            """مشتريات الكسر والتسكير فقط (gold_type='scrap')."""
            try:
                scrap_inv_types = {'شراء من عميل': 1, 'شراء': 1, 'مرتجع شراء': -1}
                invs = (
                    Invoice.query
                    .filter(Invoice.invoice_type.in_(list(scrap_inv_types.keys())))
                    .filter(Invoice.gold_type == 'scrap')
                    .filter(Invoice.is_posted.is_(True))
                    .filter(Invoice.date >= start)
                    .filter(Invoice.date < end)
                    .all()
                )
                total_value = 0.0
                total_weight = 0.0
                for inv in invs:
                    sign = scrap_inv_types.get(inv.invoice_type, 1)
                    total_value += float(inv.total or 0) * sign
                    total_weight += float(inv.total_weight or 0) * sign
                # Current scrap moving average
                from models import InventoryCostingConfig as ICC
                scrap_cfg = ICC.query.filter_by(costing_type='scrap').first()
                avg_rate = float(scrap_cfg.avg_total_cost_per_gram or 0.0) if scrap_cfg else 0.0
                avg_gold = float(scrap_cfg.avg_gold_price_per_gram or 0.0) if scrap_cfg else 0.0
                cum_weight = float(scrap_cfg.total_inventory_weight or 0.0) if scrap_cfg else 0.0
                return {
                    'total_value': round(total_value, 2),
                    'total_weight': round(total_weight, 3),
                    'docs': len(invs),
                    'avg_rate': round(avg_rate, 4),
                    'avg_gold': round(avg_gold, 4),
                    'cumulative_weight': round(cum_weight, 3),
                }
            except Exception:
                return {'total_value': 0.0, 'total_weight': 0.0, 'docs': 0, 'avg_rate': 0.0, 'avg_gold': 0.0, 'cumulative_weight': 0.0}

        for period_key, (p_start, p_end) in _summary_periods.items():
            try:
                sales_purchases_summary[period_key] = {
                    'sales': _build_inv_summary(sale_types, p_start, p_end),
                    # Exclude scrap invoices to avoid double-counting:
                    # scrap is tracked separately in scrap_purchases.
                    'purchases': _build_inv_summary(purchase_types, p_start, p_end, exclude_gold_type='scrap'),
                    'expenses': _build_expenses_summary(p_start, p_end),
                    'scrap_purchases': _build_scrap_summary(p_start, p_end),
                }
            except Exception as _period_err:
                import traceback
                print(f'[dashboard] sales_purchases_summary period={period_key} error: {_period_err}')
                traceback.print_exc()
                sales_purchases_summary[period_key] = {}
    except Exception as _summary_err:
        import traceback
        print(f'[dashboard] sales_purchases_summary outer error: {_summary_err}')
        traceback.print_exc()
        sales_purchases_summary = {}

    return jsonify({
        'success': True,
        'generated_at': now.isoformat(),
        'global_snapshot': {
            'net_financial_position': round(net_financial_position, 2),
            'gold_price_24k': round(float(spot_price_24k_per_gram), 2) if spot_price_24k_per_gram else None,
            'gold_price_change_pct': round(gold_price_change_pct, 2) if gold_price_change_pct is not None else None,
            'gold_price_timestamp': spot_price_timestamp,
        },
        'kpis': {
            'cash_balance': round(cash_balance, 2),
            'gold_by_karat': {
                '18k': round(gold_18k, 3),
                '21k': round(gold_21k, 3),
                '22k': round(gold_22k, 3),
                '24k': round(gold_24k, 3),
            },
            'gold_pure_24k': round(gold_pure_24k, 3),
            'gold_equivalent_main_karat': round(gold_equivalent_main_karat, 3),
            'main_karat': main_karat,
            'sales_today': {
                'net_value': round(sales_today_value, 2),
                'net_weight': round(sales_today_weight, 3),
                'documents': len(today_invoices),
                'change_pct': round(sales_change_pct, 1) if sales_change_pct is not None else None,
                'change_pct_weight': round(sales_change_pct_weight, 1)
                if sales_change_pct_weight is not None
                else None,
            },
            'purchases_today': {
                'net_value': round(purchases_today_value, 2),
                'net_weight': round(purchases_today_weight, 3),
                'documents': len(today_purchases),
                'change_pct': round(purchases_change_pct, 1) if purchases_change_pct is not None else None,
                'change_pct_weight': round(purchases_change_pct_weight, 1)
                if purchases_change_pct_weight is not None
                else None,
            },
            'today_profit': round(today_profit, 2),
            'today_profit_margin_pct': round(today_profit_margin_pct, 1) if today_profit_margin_pct is not None else None,
            'yesterday_profit': round(yesterday_profit, 2),
            'today_profit_vs_yesterday_pct': round(today_profit_vs_yesterday_pct, 1) if today_profit_vs_yesterday_pct is not None else None,
        },
        'series': {
            'last_7_days_sales': [
                {
                    'period': row['period'],
                    'documents': int(row.get('documents') or 0),
                    'net_value': round(float(row.get('net_value') or 0.0), 2),
                    'net_weight': round(float(row.get('net_weight') or 0.0), 3),
                }
                for row in last_7_days_sales
            ],
            'last_7_days_purchases': [
                {
                    'period': row['period'],
                    'documents': int(row.get('documents') or 0),
                    'net_value': round(float(row.get('net_value') or 0.0), 2),
                    'net_weight': round(float(row.get('net_weight') or 0.0), 3),
                }
                for row in last_7_days_purchases
            ],
        },
        'alerts': {
            'last_shift_closing': last_shift_alert,
            'critical_unreviewed_count': int(critical_unreviewed_count or 0),
            'critical_unreviewed_latest': critical_latest,
            'unposted_invoices_count': unposted_invoices_count,
            'critical_bar': critical_bar[:3],
        },
        'valuation': {
            'spot_price_24k_per_gram': round(float(spot_price_24k_per_gram), 2)
            if spot_price_24k_per_gram is not None
            else None,
            'spot_price_timestamp': spot_price_timestamp,
            'currency': 'ر.س',
            'inventory_value': round(float(inventory_value), 2) if inventory_value is not None else None,
            'avg_cost_per_gram': round(float(avg_cost_per_gram), 2) if avg_cost_per_gram else None,
            'profit_margin_pct': round(float(profit_margin), 2) if profit_margin is not None else None,
        },
        'liquidity': {
            'cash_available': round(cash_balance, 2),
            'cash_in_hand': round(cash_in_hand, 2),
            'cash_in_banks': round(cash_in_banks, 2),
            'receivables': round(receivables_due_7_days, 2),
            'payables_due_7_days': round(payables_due_7_days, 2),
            'receivables_due_7_days': round(receivables_due_7_days, 2),
            'coverage_ratio_pct': round(liquidity_coverage_ratio, 1) if liquidity_coverage_ratio is not None else None,
        },
        'safe_boxes': safe_boxes_enhanced,
        'sensitive_operations': sensitive_operations,
        'sales_purchases_summary': sales_purchases_summary,
    }), 200


def _time_ago(dt, now):
    """Helper to format time ago in Arabic."""
    if not dt:
        return None
    diff = now - dt
    seconds = diff.total_seconds()
    if seconds < 60:
        return 'الآن'
    elif seconds < 3600:
        mins = int(seconds // 60)
        return f'منذ {mins} دقيقة'
    elif seconds < 86400:
        hours = int(seconds // 3600)
        return f'منذ {hours} ساعة'
    else:
        days = int(seconds // 86400)
        return f'منذ {days} يوم'


